    const H = s.seatH || 47, a = (s.back ?? 38) * D2R, sa = (s.seat ?? 12) * D2R, T = 6, W = s.width || 30, bl = s.backLen || 82, sl = s.seatLen || 34;
    const hz = s.hingeZ ?? 0, hinge = [0, H - T, hz], X = s.halfWidth || 56, upZ = s.upZ ?? 62, hookH = s.hook || 130;
