    for (const sx of [-1, 1]) b.box('capF' + (sx < 0 ? 'R' : 'L'), [sx * 30.5, 3.75, Math.min(kz, az) - 12], [2, 7, 7], { mount: 'footF', tone: 'rubber', round: .5 });
