    const down = [0, -Math.sin(sl), Math.cos(sl)], nrm = [0, Math.cos(sl), Math.sin(sl)], edge = [0, padTop, pz];
    const padC = V.add(V.add(edge, down, PL / 2), nrm, -T / 2);
