    b.box('stopH', [0, Hd - .6, 8.5], [2 * W, 1.4, 3], { mount: 'head', tone: 'wood', round: .2 });
    /* полотно двери (закрыто, открывается от пользователя), петли со стороны −X, ручка со стороны +X */
