  b.tube(k + 'BaseS', P(0, 3.75, -d), P(0, 3.75, d), [8, 7.5], { mount: k + 'Base' });
  for (const sg of [-1, 1]) b.tube(k + 'Post' + (sg > 0 ? 'A' : 'B'), P(sg * hw, 7.5, 0), P(sg * hw, h, 0), [6, 6], { mount: k + 'Base' });
