    b.tube('leg' + k, [sg * (rx + 14), 7.5, a0[2] + 4], [sg * (rx + 14), a0[1], a0[2] + 4], [7, 7], { mount: 'base' + k });
    b.tube('legLink' + k, [sg * (rx + 14), a0[1] - 2, a0[2] + 4], [sg * rx, a0[1] - 2, a0[2] + 4], [6, 6], { mount: 'leg' + k });
