    b.box('screen', V.add(V.add(colT, [0, 6, -3]), cz, -4.2), [24, 14, .6], { axes: [[1, 0, 0], cy, cz], mount: 'console', tone: 'rubber', round: .3 });
    const fy = colT[1] - 22, fz = colAt(fy)[2] - 9;
