      const ga = Math.atan2(e.grip * Math.sin(bd), e.upper + e.grip * Math.cos(bd)), vn = Math.hypot(G[1] - H[1], G[2] - H[2]), vy = (G[1] - H[1]) / vn, vz = (G[2] - H[2]) / vn;
      const u = [0, vy * Math.cos(ga) + vz * Math.sin(ga), vz * Math.cos(ga) - vy * Math.sin(ga)];
