    const b = bones.find(x => x.name === 'ribcage'); if (!b) return null;
    const p = b.pos, n = p.length / 3; let zc = 0; for (let i = 2; i < p.length; i += 3) zc += p[i]; zc /= n;
    const sh = new Map();
