/* ---------- сборка одной тренировки ---------- */
function buildPlan(ctx = {}) {
  /* свой план: упражнения и порядок задал человек; мышцы — только подсказка для подбора */
  const custom = S.mode === 'custom' && !ctx.groups ? customOf() : null;
  /* тренировка на сегодня по журналу: группы уже в S.groups, отсюда — доли групп, отдых и облегчение (13d-muscle-load.js) */
  const lp = !custom && !ctx.groups && S.mode === 'single' ? logPickCtx() : null;
  const groups = ctx.groups || S.groups, count = custom ? custom.items.length : ctx.count || (lp ? lp.count : S.count), week = ctx.week || null;
  const sw = custom ? {} : ctx.swaps || {};
  const E = effEquip(S.equip);
  const rand = rng((ctx.seed ?? S.seed) * 9973 + count * 31 + groups.length * 7);
  if (custom && !custom.items.length) return {empty:'custom', groups};
  if (!groups.length && !custom) return {empty:'groups'};
  /* программа другого места: подбор под его инвентарь, затем недоступное здесь заменяется аналогами;
     в своём плане так же заменяется то, чего нет в этом месте */
  const ref = custom ? null : programEquip(), PE = ref ? effEquip(ref) : E;
  let picked = custom ? custom.items.map(it => EXI[it.id]) : pickExercises(PE, rand, groups, count, ctx.avoid, lp || undefined).picked;
  /* «можно здесь»: есть инвентарь, и упражнение не нагружает суставы, которые бережём (11g-gentle.js) */
  const usable = ex => available(ex, E) && fitsBody(ex);
  const pool = EX.filter(usable);
  const subs = new Map(), lost = [];
  let slots = picked.map((_, i) => i);
  if (ref || custom) {
    const lvlMax = custom ? 3 : S.level === 'beg' ? 2 : 3, used = new Set(picked.filter(usable).map(ex => ex.id));
    const keep = [], ok = S.format === 'static' ? b => staticOk(b) && fitsBody(b) : fitsBody;
    picked = picked.map((ex, i) => {
      if (usable(ex)) { keep.push(i); return ex; }
      const alt = analogsFor(ex, E, {exclude:used, lvlMax, limit:1, ok})[0];
      if (!alt) { lost.push(ex); return null; }
      const why = available(ex, E) ? unfitWhy(ex) : '';
      used.add(alt.ex.id); subs.set(alt.ex, {from:ex, note:[why, alt.note].filter(Boolean).join(' · ')}); keep.push(i); return alt.ex;
    }).filter(Boolean);
    slots = keep;
  }
  for (const [i, id] of Object.entries(sw)) {
    const ex = EXI[id];
    if (picked[i] && ex && usable(ex) && !picked.includes(ex)) picked[i] = ex;
  }
  if (!picked.length) return {empty:'none', pool, groups, lost};
  const G = GOALS[S.goal];
  const items = picked.map((ex, k) => {
    const slot = slots[k], rx = applyLight(prescribe(ex, week, E), ex);
    if (lp && lp.light.has(ex.g)) easeRx(rx);
    return {ex, slot, rx:custom ? customRx(rx, custom.items[slot], ex) : rx, name:exName(ex, E), eqLine:equipLine(ex, E), eqIds:chosenEquip(ex, E), has:propHas(ex, E), sub:subs.get(ex) || null};
  });
  const bySlot = new Map(items.map(it => [it.ex, it]));
  let blocks = [], minutes = 0, totalSets = 0;
  if (S.format === 'classic' || S.format === 'static') {
    const ord = byOrder((custom ? picked : orderClassic(picked)).map(ex => bySlot.get(ex)), custom ? null : ctx.order, it => [it.slot]);
    ord.forEach((it, i) => { it.label = String(i + 1); });
    blocks = [{kind:'list', items:ord}];
    for (const it of ord) { minutes += it.rx.static ? staticSeconds(it.rx) : it.rx.sets * (it.rx.work + it.rx.rest) + 60; totalSets += it.rx.sets; }
  } else if (S.format === 'superset') {
    /* в своём плане пары — соседние упражнения по порядку человека */
    const pairs = custom ? picked.reduce((a, ex, i) => (i % 2 ? a[a.length - 1].push(ex) : a.push([ex]), a), []) : byOrder(pairSupersets(picked), ctx.order, pr => pr.map(ex => bySlot.get(ex).slot));
    pairs.forEach((pr, pi) => {
      const L = String.fromCharCode(65 + pi);
      const its = pr.map((ex, j) => { const it = bySlot.get(ex); it.label = pr.length > 1 ? L + (j + 1) : L; return it; });
      const sets = Math.max(...its.map(it => it.rx.sets));
      const rest = pr.length > 1 ? G.ss.rest : its[0].rx.rest;
      its.forEach(it => { it.rx.sets = sets; it.rx.restShown = pr.length > 1 ? (it === its[its.length - 1] ? rest : 0) : rest; });
      blocks.push({kind:'pair', letter:L, items:its, sets, rest});
      minutes += sets * (its.reduce((a, it) => a + it.rx.work, 0) + 15 + rest) + 60;
      totalSets += sets * its.length;
    });
  } else {
    const ord = byOrder((custom ? picked : orderCircuit(picked)).map(ex => bySlot.get(ex)), custom ? null : ctx.order, it => [it.slot]);
    const c = G.circ;
    let rounds = c.rounds + (S.level === 'beg' ? -1 : S.level === 'adv' ? 1 : 0);
    if (week && week.deload) rounds -= 1;
    else if (week && week.add) rounds += 0;
    rounds = Math.max(2, rounds);
    if (AR.light && S.mode !== 'program') rounds = Math.max(1, Math.round(rounds * .6));
    ord.forEach((it, i) => {
      it.label = String(i + 1);
      it.rounds = rounds;
      if (!it.ex.kind && !(custom && custom.items[it.slot]?.reps)) it.rx.reps = c.reps;
      it.rx.circ = true;
      it.rx.work = it.ex.kind === 'time' ? c.work : it.ex.kind === 'dist' ? 30 : midOf(it.rx.reps) * G.rep * (it.ex.uni ? 2 : 1);
    });
    blocks = [{kind:'circuit', items:ord, rounds, rest:c.rest, roundRest:c.roundRest}];
    minutes = rounds * (ord.reduce((a, it) => a + it.rx.work, 0) + c.rest * (ord.length - 1)) + (rounds - 1) * c.roundRest;
    totalSets = rounds * ord.length;
  }
  const missing = groups.filter(g => !pool.some(ex => groupsOf(ex).has(g)));
  const load = {}, gvol = {};
  for (const it of items) {
    const k = S.format === 'circuit' ? blocks[0].rounds : it.rx.sets;
    for (const m of it.ex.pri) load[m] = (load[m] || 0) + k;
    for (const m of it.ex.sec) load[m] = (load[m] || 0) + k * 0.5;
    /* дробный учёт: целевая группа — полный подход, остальные работающие — половина */
    for (const [g, x] of Object.entries(groupShare(it.ex))) gvol[g] = (gvol[g] || 0) + k * x;
  }
  return {blocks, items, minutes:Math.round(minutes / 60), totalSets, missing:custom ? [] : missing, load, gvol, pool, E, groups, count, lost, custom:!!custom, byLog:!!lp};
}

/* ---------- сборка недели ---------- */
function buildProgram() {
  const days = S.days, split = splitFor(days);
  const tmpl = SPLITS[split].days[days];
  const week = WEEKS[S.week - 1];
  const avoid = new Set();
  const seen = {};
  const out = tmpl.map((tid, i) => {
    seen[tid] = (seen[tid] || 0) + 1;
    /* день «всё тело» включает мышцу акцента, даже если по шаблону её группы в этот день нет */
    const fg = S.focus && MUSCLE_GROUP[S.focus], g = DAY_T[tid].name === 'Всё тело' && fg && !DAY_T[tid].g.includes(fg) ? DAY_T[tid].g.concat(fg) : DAY_T[tid].g;
    const p = buildPlan({groups:g, count:S.count, seed:S.seed * 131 + i * 977 + 13, avoid:new Set(avoid), week, swaps:swaps['d' + i] || {}, order:swaps.__order?.['d' + i]});
    if (p.items) p.items.forEach(it => avoid.add(it.ex.id));
    return {tid, i, wd:SCHEDULE[days][i], plan:p};
  });
  for (const d of out) {
    const same = tmpl.filter(t => t === d.tid).length;
    const k = tmpl.slice(0, d.i + 1).filter(t => t === d.tid).length;
    const letters = DAY_T[d.tid].name === 'Всё тело' ? 'АБВГ' : 'АБ';
    const isFull = DAY_T[d.tid].name === 'Всё тело';
    const fullIdx = isFull ? tmpl.slice(0, d.i + 1).filter(t => DAY_T[t].name === 'Всё тело').length : 0;
    const fullTotal = tmpl.filter(t => DAY_T[t].name === 'Всё тело').length;
    d.name = DAY_T[d.tid].name + (isFull ? (fullTotal > 1 ? ' ' + letters[fullIdx - 1] : '') : (same > 1 ? ' ' + letters[k - 1] : ''));
  }
  const gvol = {}, load = {};
  let minutes = 0, sets = 0;
  for (const d of out) {
    if (!d.plan.items) continue;
    minutes += d.plan.minutes; sets += d.plan.totalSets;
    for (const [g, v] of Object.entries(d.plan.gvol)) gvol[g] = (gvol[g] || 0) + v;
    for (const [m, v] of Object.entries(d.plan.load)) load[m] = (load[m] || 0) + v;
  }
  return {days:out, split, week, gvol, load, minutes, sets};
}

/* ---------- отрисовка ---------- */
const $ = (sel, root = document) => root.querySelector(sel);
const ICON = {
  swap:'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 7h10l-3-3M16 13H6l3 3" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  dice:'<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="3" y="3" width="14" height="14" rx="3.5" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="7.2" cy="7.2" r="1.3" fill="currentColor"/><circle cx="12.8" cy="12.8" r="1.3" fill="currentColor"/><circle cx="10" cy="10" r="1.3" fill="currentColor"/></svg>',
  copy:'<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="7" y="7" width="10" height="10" rx="2" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M13 7V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h2" fill="none" stroke="currentColor" stroke-width="1.7"/></svg>',
  loop:'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M15.5 8.5A6 6 0 1 0 15 13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M16 3.5v5h-5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  chart:'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 16h14M5 13l3.5-4 3 2.5L16 6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  cal:'<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="3" y="4" width="14" height="13" rx="2" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M3 8h14M7 2.5v3M13 2.5v3" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',
  save:'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5 3h8l3 3v10a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><path d="M7 3v4h6V3M7 17v-5h6v5" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>',
  share:'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 13V3M6.5 6.5 10 3l3.5 3.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M5 10v6h10v-6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  load:'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 3v10M6.5 9.5 10 13l3.5-3.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M5 12v4h10v-4" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  check:'<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
};

function renderSetup() {
  const seg = (name, dict, cur) => Object.entries(dict).map(([k, v]) =>
    `<button type="button" class="seg-b${k === cur ? ' on' : ''}" data-set="${name}" data-v="${k}" aria-pressed="${k === cur}"><b>${v.name}</b>${v.hint ? `<small>${v.hint}</small>` : ''}</button>`).join('');
  const prog = S.mode === 'program', custom = S.mode === 'custom';
  $('#views').innerHTML = viewTabs();
  const jv = S.view === 'journal' || S.view === 'atlas';
  $('.setup').hidden = jv; $('.layout').classList.toggle('solo', jv);
  renderSetupFold();
  $('#f-mode').innerHTML = seg('mode', MODES, S.mode);
  $('#f-prog').hidden = !prog;
  $('#f-custom').hidden = !custom;
  if (custom) $('#f-custom-body').innerHTML = customSetupHtml();
  $('#f-muscles').hidden = prog;
  $('#g-note').hidden = !custom;
  $('#count-l').closest('.field').hidden = custom;
  $('#count-l').textContent = prog ? 'Упражнений в тренировке' : 'Упражнений';
  if (prog) {
    $('#f-days').innerHTML = [2, 3, 4, 5].map(d => `<button type="button" class="seg-b${d === S.days ? ' on' : ''}" data-days="${d}" aria-pressed="${d === S.days}"><b>${d}</b><small>${SCHEDULE[d].map(i => WD[i]).join(' ')}</small></button>`).join('');
    const sp = splitFor(S.days);
    const opts = Object.entries(SPLITS).filter(([, v]) => v.days[S.days]);
    $('#f-split').style.gridTemplateColumns = `repeat(${opts.length}, 1fr)`;
    $('#f-split').innerHTML = opts.map(([k, v]) => `<button type="button" class="seg-b${k === sp ? ' on' : ''}" data-split="${k}" aria-pressed="${k === sp}"><b>${v.name}</b><small>${v.hint}</small></button>`).join('');
    $('#split-note').textContent = SPLITS[sp].note;
  }
  $('#f-goal').innerHTML = seg('goal', GOALS, S.goal);
  $('#f-format').innerHTML = seg('format', FORMATS, S.format);
  $('#f-level').innerHTML = seg('level', LEVELS, S.level);
  renderProtect();
  $('#count-v').textContent = S.count;
  $('#count-minus').disabled = S.count <= 3; $('#count-plus').disabled = S.count >= 10;
  const gs = new Set(S.groups);
  $('#g-presets').innerHTML = GROUP_PRESETS.map(p => {
    const on = p.g.length === gs.size && p.g.every(g => gs.has(g));
    return `<button type="button" class="pre${on ? ' on' : ''}" data-gp="${p.id}">${p.name}</button>`;
  }).join('') + logPresetHtml();
  const lpMsg = $('#lp-msg'); if (lpMsg) lpMsg.hidden = true;
  $('#g-chips').innerHTML = GROUPS.map(g => `<button type="button" class="chip${gs.has(g.id) ? ' on' : ''}" data-g="${g.id}" aria-pressed="${gs.has(g.id)}">${ICON.check}<span>${g.name}</span></button>`).join('');
  const cur = placeOf();
  $('#e-places').innerHTML = S.places.map(p => `<button type="button" class="place${p.id === S.place ? ' on' : ''}" data-place="${p.id}" aria-pressed="${p.id === S.place}"><b>${esc(p.name)}</b><small>${p.equip.length ? p.equip.length + ' ' + plural(p.equip.length, 'снаряд', 'снаряда', 'снарядов') : 'без снаряжения'}</small></button>`).join('')
    + `<button type="button" class="place place-add" data-place-add="1">+ Место</button>`;
  const others = S.places.filter(p => p.id !== S.place);
  $('#e-place-tools').innerHTML = `<label class="place-name">Название<input id="place-name" type="text" maxlength="24" value="${esc(cur.name)}" autocomplete="off"></label>`
    + (S.places.length > 1 ? `<button type="button" class="place-del${placeDel ? ' armed' : ''}" data-place-del="1">${placeDel ? 'Точно удалить?' : 'Удалить место'}</button>` : '')
    + (others.length ? `<label class="place-adapt">Программа<select id="place-adapt"><option value="">Своя для этого места</option>${others.map(p => `<option value="${p.id}"${S.adapt === p.id ? ' selected' : ''}>Как в «${esc(p.name)}», с заменами</option>`).join('')}</select></label>
      <p class="f-note">${S.adapt ? `Упражнения подобраны под «${esc(placeOf(S, S.adapt).name)}»; то, чего здесь нет, заменено ближайшим аналогом — по тому же движению и тем же мышцам.` : 'Программа собирается из того, что есть в этом месте.'}</p>` : '');
  const es = new Set(S.equip);
  $('#e-presets').innerHTML = '<span class="pres-l">Заполнить:</span>' + EQUIP_PRESETS.map(p => {
    const on = p.eq.length === es.size && p.eq.every(e => es.has(e));
    return `<button type="button" class="pre${on ? ' on' : ''}" data-ep="${p.id}">${p.name}</button>`;
  }).join('');
  $('#e-chips').innerHTML = EQUIP_CATS.map(c => `<div class="e-cat"><h3>${c.name}</h3><div class="chips">${EQUIP.filter(e => e.cat === c.id).map(e =>
    `<button type="button" class="chip${es.has(e.id) ? ' on' : ''}" data-e="${e.id}" aria-pressed="${es.has(e.id)}"${e.hint ? ` title="${esc(e.hint)}"` : ''}>${ICON.check}<span>${e.name}</span></button>`).join('')}</div></div>`).join('');
  $('#e-count').textContent = es.size ? `${es.size} из ${EQUIP.length}` : 'только вес тела';
  /* список оборудования сворачивается всегда — и для своего набора, не совпадающего с заготовкой;
     кнопка вверху видна без прокрутки, внизу раскрытого списка — ещё одна «Свернуть» */
  const open = eqOpen, names = EQUIP.filter(e => es.has(e.id)).map(e => e.name);
  $('#e-chips').hidden = !open;
  $('#e-sum').hidden = open;
  $('#e-sum').textContent = es.size === EQUIP.length ? 'Всё оборудование зала.' : !names.length ? 'Только вес тела.'
    : names.length > 10 ? names.slice(0, 10).join(', ') + ` и ещё ${names.length - 10}.` : names.join(', ') + '.';
  $('#e-toggle').hidden = !open;
  $('#e-toggle-top').textContent = open ? 'Свернуть' : 'Изменить список';
  for (const b of [$('#e-toggle'), $('#e-toggle-top')]) b.setAttribute('aria-expanded', String(open));
}

function titleFor() {
  if (S.mode === 'custom') return customOf().name;
  const gs = new Set(S.groups);
  const p = GROUP_PRESETS.find(p => p.g.length === gs.size && p.g.every(g => gs.has(g)));
  if (p) return p.id === 'full' ? 'Всё тело' : p.id === 'legs' ? 'Ноги и ягодицы' : p.id === 'push' ? 'Грудь, плечи, трицепс' : p.id === 'pull' ? 'Спина, бицепс, хват' : 'Верх тела';
  const names = S.groups.map(g => GN[g].toLowerCase());
  const s = names.length > 1 ? names.slice(0, -1).join(', ') + ' и ' + names[names.length - 1] : names[0];
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function loadBars(load) {
  const rows = Object.entries(load).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]).slice(0, 6);
  const max = rows.length ? rows[0][1] : 1;
  return rows.map(([m, v]) => `<li><span class="lb-n">${MUSCLE_NAMES[m]}</span><span class="lb-t"><i style="width:${Math.max(6, v / max * 100).toFixed(0)}%"></i></span><span class="lb-v">${fmtNum(v)}</span></li>`).join('');
}
/* недельный объём по группам с ориентиром 10–20 подходов */
function volBars(gvol, groups) {
  const ids = GROUPS.map(g => g.id).filter(g => g !== 'cardio' && (groups.has(g) || (gvol[g] || 0) >= 1));
  const max = Math.max(22, ...ids.map(g => gvol[g] || 0));
  return ids.map(g => volRow(g, gvol[g] || 0, max)).join('');
}
/* строка полосы «подходов на группу»: коридор 10–20, «мало / в норме / много»; extra — добавка под полосой
   (статус восстановления в журнале, 13d-muscle-load.js) */
function volRow(g, val, max, extra = '', cls = '') {
  const pct = v => (v / max * 100).toFixed(1);
  const v = Math.round(val * 2) / 2;
  const st = v < 10 ? 'lo' : v > 20 ? 'hi' : 'ok';
  const lab = st === 'lo' ? 'мало' : st === 'hi' ? 'много' : 'в норме';
  return `<li class="${st}${cls ? ' ' + cls : ''}"${cls ? ` data-lg="${g}"` : ''}><span class="vb-n">${GN[g]}</span><span class="vb-v">${fmtNum(v)}<em>${lab}</em></span><span class="vb-t"><b style="left:${pct(10)}%;width:${pct(10)}%"></b><i style="width:${Math.max(1.5, +pct(v))}%"></i></span>${extra}</li>`;
}

/* вес по плану (свой план или план тренера) — рядом с подходами */
function rxKgHtml(it) {
  const r = it.rx; if (!r.kgPlan || typeof loadType !== 'function') return '';
  const lt = loadType(it.ex); if (lt === 'none') return '';
  return `<span class="rx-kg">${lt === 'assist' ? 'противовес ' : lt === 'extra' ? '+' : ''}${planKgText(r.kgPlan)} кг</span>`;
}
function rxHtml(it) {
  const r = it.rx;
  const unit = r.unit ? ` <small>${r.unit}</small>` : '';
  const side = r.uni ? '<small> на сторону</small>' : '';
  if (r.static) return `<div class="rx"><span class="rx-big">${r.series} × 3 × ${r.reps}${unit}${side}</span><span class="rx-rest">${r.series} ${plural(r.series, 'серия', 'серии', 'серий')} по 3 подхода · отдых ${fmtRest(r.rest)}${r.series > 1 ? `, между сериями ${fmtRest(r.seriesRest)}` : ''}</span>${rxKgHtml(it)}${r.light ? '<span class="rx-light">облегчено</span>' : ''}${easedTag(r)}</div>`;
  if (r.circ) return `<div class="rx"><span class="rx-big">${r.reps}${unit}${side}</span>${rxKgHtml(it)}</div>`;
  const rest = r.restShown !== undefined ? (r.restShown ? `отдых ${fmtRest(r.restShown)}` : 'сразу к следующему') : `отдых ${fmtRest(r.rest)}`;
  return `<div class="rx"><span class="rx-big">${r.sets} × ${r.reps}${unit}${side}</span><span class="rx-rest">${rest}</span>${rxKgHtml(it)}${r.light ? '<span class="rx-light">облегчено</span>' : ''}${easedTag(r)}</div>`;
}

/* суставы под пиковой нагрузкой — короткая строка в карточке; подробности в разборе движения */
function jointsLine(ex) {
  const zones = typeof stressZones === 'function' ? stressZones(ex) : [];
  if (!zones.length) return '';
  const on = typeof motionPrefs === 'undefined' || motionPrefs.stress !== false;
  return `<p class="c-joints"${on ? '' : ' hidden'} title="Красные метки в разборе движения показывают, когда нагрузка наибольшая"><span class="stress-dot" aria-hidden="true"></span>Пиковая нагрузка: ${esc(zones.join(', '))}</p>`;
}
function cardHtml(it, idx) {
  const ex = it.ex, r = it.rx;
  const lvl = {};
  for (const m of ex.pri) lvl[m] = 1;
  for (const m of ex.sec) if (!lvl[m]) lvl[m] = 0.38;
  const mus = ex.pri.map(m => `<li class="p">${MUSCLE_NAMES[m]}</li>`).join('') + ex.sec.map(m => `<li class="s">${MUSCLE_NAMES[m]}</li>`).join('');
  const meta = [];
  if (r.tempo) meta.push(`<span title="опускание – пауза – подъём – пауза, секунды; X — взрывно">темп <b>${r.tempo}</b></span>`);
  if (r.load) meta.push(`<span>${r.load}</span>`);
  const view = ex.anim.catalogRig?'Изометрия · 5 ракурсов':(ex.viewNote || (ex.anim.view === 'front' ? 'вид спереди' : 'вид сбоку'));
  return `<li class="card${cardFoldClass(ex.id)}" data-ex="${ex.id}" data-slot="${it.slot}">
  <div class="c-top">
    <div class="motion-tile"><button type="button" class="illus" data-fig="${idx}" aria-haspopup="dialog" aria-controls="motion-view" aria-label="Разобрать движение: ${esc(it.name)}"><span class="illus-v">${view}</span><span class="illus-zoom" aria-hidden="true">Увеличить ↗</span></button><div class="motion-bar"><span class="motion-caption">Исходное положение</span><button type="button" data-motion-pause="${idx}" aria-label="Пауза демонстрации: ${esc(it.name)}" aria-pressed="false">Пауза</button></div></div>
    <div class="c-info">
      <div class="c-head"><span class="c-idx">${it.label}</span><span class="c-type">${ex.type === 'c' ? 'базовое' : 'изолирующее'}</span>${favButton(ex.id)}</div>
      <h3 class="c-name">${esc(it.name)}</h3>
      <p class="c-eq">${esc(it.eqLine)}</p>
      ${it.sub ? `<p class="c-sub"><b>Вместо: ${esc(exName(it.sub.from, effEquip(programEquip() || S.equip)))}</b>${it.sub.note ? ` · ${esc(it.sub.note)}` : ''}</p>` : ''}
      ${rxHtml(it)}
      ${meta.length ? `<p class="c-meta">${meta.join('<i>·</i>')}</p>` : ''}
      ${r.coachNote ? `<p class="c-note"><b>Заметка:</b> ${esc(r.coachNote)}</p>` : ''}
    </div>
  </div>
  ${variantRowHtml(it)}
  <div class="c-mus">
    ${musFoldHead(ex)}
    <div class="c-map">${muscleMapSvg(lvl, {aria:'Работающие мышцы: ' + ex.pri.map(m => MUSCLE_NAMES[m]).join(', ')})}</div>
    <ul class="mus">${mus}</ul>
  </div>
  ${jointsLine(ex)}
  ${logBlock(it)}
  <div class="c-hist" hidden></div>
  <div class="c-warm">${warmupHtml(it, workWeightOf(it, null))}</div>
  <div class="c-prog">${progressionHint(it)}</div>
  <div class="c-act">
    <button type="button" class="btn-ghost" data-workout="${ex.id}" aria-haspopup="dialog" aria-controls="workout-view">Начать тренировку →</button>
    <span class="c-act-r">${S.mode === 'custom' ? '' : moveButtons(it)}<button type="button" class="btn-ghost" data-swap="${it.slot}">${ICON.swap}<span>Заменить</span></button></span>
  </div>
  ${S.mode === 'custom' ? customToolsHtml(it) : ''}
  <details class="tech">
    <summary>Техника выполнения</summary>
    <ol class="t-steps">${ex.tech.map(s => `<li>${esc(s)}</li>`).join('')}</ol>
    <div class="t-cols">
      <div><h4>Частые ошибки</h4><ul class="t-err">${ex.err.map(s => `<li>${esc(s)}</li>`).join('')}</ul></div>
      <div><h4>Дыхание</h4><p>${esc(ex.breath)}</p>${ex.note ? `<h4>Важно</h4><p>${esc(ex.note)}</p>` : ''}${r.notes.map(n => `<p class="t-tip">${esc(n)}</p>`).join('')}</div>
    </div>
  </details>
</li>`;
}

/* единицы порядка плана: упражнение (классика, круг) или пара суперсета — их и двигают кнопки ↑ ↓ */
function planUnits(p) { return p.blocks.flatMap(b => b.kind === 'pair' ? [b.items.map(it => it.slot)] : b.items.map(it => [it.slot])); }
let MOVE_UNITS = [];
function moveButtons(it) {
  const n = MOVE_UNITS.length, i = MOVE_UNITS.findIndex(u => u.includes(it.slot));
  if (n < 2 || i < 0) return '';
  const pair = MOVE_UNITS[i].length > 1, up = pair ? 'Пару выше' : 'Упражнение выше', down = pair ? 'Пару ниже' : 'Упражнение ниже';
  return `<span class="c-move" role="group" aria-label="Порядок в тренировке"><button type="button" class="btn-ghost" data-move="${it.slot}" data-d="-1" aria-label="${up}" title="${up}"${i === 0 ? ' disabled' : ''}>↑</button><button type="button" class="btn-ghost" data-move="${it.slot}" data-d="1" aria-label="${down}" title="${down}"${i === n - 1 ? ' disabled' : ''}>↓</button></span>`;
}
/* сдвиг упражнения (или пары) на одно место: новый порядок — в swaps.__order того же ключа, что и замены */
function movePlanItem(slot, d) {
  const units = planUnits(plan), i = units.findIndex(u => u.includes(slot)), j = i + d;
  if (i < 0 || j < 0 || j >= units.length) return false;
  [units[i], units[j]] = [units[j], units[i]];
  swaps.__order = swaps.__order || {}; swaps.__order[swapKey()] = units.flat();
  return true;
}
function blocksHtml(p) {
  MOVE_UNITS = S.mode === 'custom' ? [] : planUnits(p);
  let html = `<p class="phase"><b>Разминка, 8–10 мин.</b> Лёгкое кардио до тёплого пота, суставная гимнастика, затем 1–2 разминочных подхода с лёгким весом в первом упражнении.</p>`;
  html += cardsViewHtml();
  if (S.format === 'static') html += `<p class="phase phase-static"><b>Статодинамика.</b> Вес — около половины от 1ПМ. Медленно: 3 с вниз и 3 с вверх, без пауз; не выпрямляйтесь до конца и не расслабляйтесь внизу — мышца всё время напряжена. К концу подхода (30–40 с) — сильное жжение, но не отказ. Три подхода с отдыхом 30 с — одна серия.</p>`;
  let idx = 0;
  for (const b of p.blocks) {
    if (b.kind === 'list') {
      html += `<ol class="cards">${b.items.map(it => cardHtml(it, idx++)).join('')}</ol>`;
    } else if (b.kind === 'pair') {
      const many = b.items.length > 1;
      html += `<section class="block">
        <header class="b-head"><h2><span class="b-letter">${b.letter}</span>${many ? 'Суперсет' : 'Отдельное упражнение'}</h2>
        <p>${many ? `${b.sets} ${plural(b.sets, 'круг', 'круга', 'кругов')}: ${b.items.map(it => it.label).join(' → ')} без паузы, затем отдых ${fmtRest(b.rest)}` : `${b.sets} ${plural(b.sets, 'подход', 'подхода', 'подходов')}, отдых ${fmtRest(b.rest)}`}</p></header>
        <ol class="cards">${b.items.map(it => cardHtml(it, idx++)).join('')}</ol></section>`;
    } else {
      const rd = done.__rounds || 0;
      html += `<section class="block block-c">
        <header class="b-head"><h2><span class="b-letter">${ICON.loop}</span>Круг × ${b.rounds}</h2>
        <p>Выполняйте станции подряд: ${fmtRest(b.rest)} на переход между упражнениями, ${fmtRest(b.roundRest)} отдыха после круга.</p>
        <div class="sets rounds" role="group" aria-label="Отметить пройденные круги">${Array.from({length:b.rounds}, (_, k) => `<button type="button" class="set${rd > k ? ' done' : ''}" data-round="${k}" aria-label="Круг ${k + 1}">${k + 1}</button>`).join('')}<span class="rounds-l">круги</span></div></header>
        <ol class="cards">${b.items.map(it => cardHtml(it, idx++)).join('')}</ol></section>`;
    }
  }
  html += `<p class="phase"><b>Заминка, 5 мин.</b> Спокойная ходьба и растяжка мышц, которые работали: по 20–30 секунд на каждую.</p>`;
  return html;
}
const LEGEND = `<p class="legend">1ПМ — вес, который вы можете поднять один раз. Темп — секунды на опускание, паузу внизу, подъём и паузу вверху; X — взрывной подъём.</p>`;
function warnHtml(p) {
  const warn = [];
  const gentle = S.goal === 'gentle' || S.protect.length > 0;
  if (p.items.length < p.count) warn.push(`Подобрано ${p.items.length} ${plural(p.items.length, 'упражнение', 'упражнения', 'упражнений')} из ${p.count}: ${gentle ? 'других вариантов для этих мышц и оборудования в бережном режиме нет.' : 'других вариантов для этих мышц и оборудования нет.'}`);
  if (p.lost && p.lost.length) warn.push(`Здесь нечем заменить: ${p.lost.map(ex => ex.name).join(', ')}. ${p.lost.length > 1 ? 'Их' : 'Его'} можно сделать здесь: ${placeOf(S, S.adapt).name}.`);
  /* мышца без упражнений: не хватает инвентаря — или всё, что есть, нагружает суставы, которые бережём */
  const byBody = p.missing.filter(g => EX.some(ex => available(ex, p.E) && groupsOf(ex).has(g))), byEq = p.missing.filter(g => !byBody.includes(g));
  if (byEq.length) warn.push(`Без упражнений осталось: ${byEq.map(g => GN[g].toLowerCase()).join(', ')}. Для них нужно другое оборудование.`);
  if (byBody.length) warn.push(`Без упражнений в бережном режиме осталось: ${byBody.map(g => GN[g].toLowerCase()).join(', ')}. Всё, что для этого есть, даёт нагрузку, которую вы бережёте.`);
  return warn.length ? `<div class="warn">${warn.map(w => `<p>${esc(w)}</p>`).join('')}</div>` : '';
}
function headButtons(copyLabel) {
  return `<div class="p-btns">
        <button type="button" class="btn" id="start-workout" aria-haspopup="dialog" aria-controls="workout-view">Начать тренировку →</button>
        ${S.mode === 'custom' ? '' : `<button type="button" class="btn btn-2" id="reroll">${ICON.dice}<span>Другой вариант</span></button>`}
        <button type="button" class="btn btn-2" id="copy">${ICON.copy}<span>${copyLabel}</span></button>
        ${S.mode === 'program' ? `<button type="button" class="btn btn-2" id="ics-open">${ICON.cal}<span>В календарь</span></button>` : ''}
        ${S.mode === 'custom' ? `<button type="button" class="btn btn-2" id="plan-export">${ICON.share}<span>Выгрузить</span></button>`
          : `<button type="button" class="btn btn-2" id="save-plan">${ICON.save}<span>${S.mode === 'program' ? 'Сохранить неделю' : 'Сохранить как свой план'}</span></button>`}
      </div>
      <p class="p-hint" id="copy-msg" role="status"></p>
      <p class="p-hint" id="save-msg" role="status"></p>`;
}
/* акцент, выбранный в атласе мышц */
function focusHtml() {
  if (!S.focus || !MUSCLE_NAMES[S.focus]) return '';
  return `<p class="focus-chip"><span>Акцент: <b>${esc(MUSCLE_NAMES[S.focus])}</b></span><button type="button" data-focus-clear="1">Убрать акцент</button></p>`;
}
function norm(load) { const mx = Math.max(1, ...Object.values(load)); const o = {}; for (const [m, v] of Object.entries(load)) o[m] = v / mx; return o; }

function renderPlan() {
  stopFigures();
  if (S.view === 'journal') { prog = null; plan = null; return renderJournal(); }
  if (S.view === 'atlas') { prog = null; plan = null; return renderAtlas(); }
  if (S.mode === 'program') return renderProgram();
  prog = null;
  plan = buildPlan({swaps:swaps.s || {}, order:swaps.__order?.s});
  const root = $('#plan');
  if (plan.empty === 'groups') {
    root.innerHTML = `<div class="empty"><h2>Выберите мышцы</h2><p>Отметьте хотя бы одну группу мышц в параметрах — план соберётся сразу.</p></div>`;
    return;
  }
  if (plan.empty === 'custom') {
    root.innerHTML = `<header class="p-head p-head-c"><div class="p-sum"><p class="eyebrow">Свой план · ${GOALS[S.goal].name} · ${FORMATS[S.format].name}</p><h1 class="p-title">${esc(titleFor())}</h1>${customHeadHtml()}</div></header>` + customEmptyHtml() + customAddHtml();
    return;
  }
  if (plan.empty === 'none') {
    root.innerHTML = S.mode === 'custom'
      ? `<div class="empty"><h2>Здесь нечем выполнить этот план</h2>${lostMessages(plan.lost, effEquip(S.equip)).map(m => `<p>${esc(m)}</p>`).join('')}<p>Выберите другое место или добавьте упражнения.</p></div>` + customAddHtml()
      : `<div class="empty"><h2>Не из чего собрать тренировку</h2><p>Для выбранных мышц нет упражнений с этим оборудованием и уровнем. Добавьте оборудование или выберите другие группы мышц.</p></div>`;
    return;
  }
  const G = GOALS[S.goal];
  const setsWord = S.format === 'circuit' ? plural(plan.totalSets, 'подход', 'подхода', 'подходов') + ' за круги' : plural(plan.totalSets, 'подход', 'подхода', 'подходов');
  const lf = ensureFold(S).load, loadRows = Object.entries(plan.load).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]).map(([m, v]) => [MUSCLE_NAMES[m], v]);
  let html = `<header class="p-head${lf ? ' load-folded' : ''}">
    <div class="p-sum">
      <p class="eyebrow">${plan.custom ? 'Свой план · ' : plan.byLog ? 'По журналу · ' : ''}${G.name} · ${FORMATS[S.format].name} · ${LEVELS[S.level].name.toLowerCase()}</p>
      <h1 class="p-title">${esc(titleFor())}</h1>
      ${plan.custom ? customHeadHtml() : focusHtml()}
      <dl class="stats">
        <div><dt>время</dt><dd>≈${plan.minutes}<small>мин</small></dd></div>
        <div><dt>${setsWord}</dt><dd>${plan.totalSets}</dd></div>
        <div><dt>${plural(plan.items.length, 'упражнение', 'упражнения', 'упражнений')}</dt><dd>${plan.items.length}</dd></div>
      </dl>
      ${headButtons('Скопировать план')}
    </div>
    <figure class="p-load${lf ? ' folded' : ''}">
      <div class="p-map">${muscleMapSvg(norm(plan.load), {labels:true, aria:'Карта нагрузки тренировки'})}</div>
      <figcaption>
        ${loadFoldHead('Нагрузка по мышцам, подходов', loadTop(loadRows))}
        <ul class="lbars">${loadBars(plan.load)}</ul>
        <p class="lb-note">Вспомогательная работа считается за половину подхода.</p>
      </figcaption>
    </figure>
  </header>`;
  if (plan.custom) {
    const hints = customHints(plan), lost = lostMessages(plan.lost, plan.E);
    html += autoregHtml() + gentleHtml() + (lost.length ? `<div class="warn">${lost.map(w => `<p>${esc(w)}</p>`).join('')}</div>` : '')
      + (hints.length ? `<div class="cp-hints">${hints.map(w => `<p>${esc(w)}</p>`).join('')}</div>` : '') + blocksHtml(plan) + customAddHtml() + LEGEND;
  } else html += logPickHtml(plan) + autoregHtml() + gentleHtml() + warnHtml(plan) + blocksHtml(plan) + LEGEND;
  root.innerHTML = html;
  mountFigures();
}

function renderProgram() {
  prog = buildProgram();
  if (S.day >= prog.days.length) S.day = 0;
  const day = prog.days[S.day];
  plan = day.plan;
  const G = GOALS[S.goal], wk = prog.week;
  const allGroups = new Set(prog.days.flatMap(d => DAY_T[d.tid].g));
  const sp = SPLITS[prog.split];
  const lf = ensureFold(S).load, volRows = Object.entries(prog.gvol).filter(([g, v]) => g !== 'cardio' && v >= 1).sort((a, b) => b[1] - a[1]).map(([g, v]) => [GN[g], Math.round(v * 2) / 2]);
  let html = `<header class="p-head${lf ? ' load-folded' : ''}">
    <div class="p-sum">
      <p class="eyebrow">${G.name} · ${FORMATS[S.format].name} · ${LEVELS[S.level].name.toLowerCase()}</p>
      <h1 class="p-title">${esc(sp.name)}, ${S.days} ${plural(S.days, 'тренировка', 'тренировки', 'тренировок')} в неделю</h1>
      ${focusHtml()}
      <dl class="stats">
        <div><dt>в неделю</dt><dd>≈${prog.minutes}<small>мин</small></dd></div>
        <div><dt>${plural(prog.sets, 'подход', 'подхода', 'подходов')} в неделю</dt><dd>${prog.sets}</dd></div>
        <div><dt>неделя цикла</dt><dd>${S.week}<small>из 4</small></dd></div>
      </dl>
      ${headButtons('Скопировать неделю')}
    </div>
    <figure class="p-load${lf ? ' folded' : ''}">
      <div class="p-map">${muscleMapSvg(norm(prog.load), {labels:true, aria:'Карта недельной нагрузки'})}</div>
      <figcaption>
        ${loadFoldHead('Подходов на группу за неделю', loadTop(volRows))}
        <ul class="vbars">${volBars(prog.gvol, allGroups)}</ul>
        <p class="lb-note">Полоса — ориентир для роста мышц: 10–20 подходов в неделю. Подход засчитывается целиком целевой группе и наполовину остальным работающим. ${S.goal === 'strength' ? 'В силовом цикле объём ниже — это нормально.' : S.goal === 'gentle' ? 'В бережном режиме объём ниже намеренно: сначала суставы и техника.' : ''}</p>
      </figcaption>
    </figure>
  </header>
  <section class="weeks" aria-label="Неделя цикла">
    <h2>Цикл из 4 недель</h2>
    <div class="wk" role="group" aria-label="Неделя цикла">${WEEKS.map((w, i) => `<button type="button" class="${i + 1 === S.week ? 'on' : ''}" data-week="${i + 1}" aria-pressed="${i + 1 === S.week}"><b>${i + 1}</b><small>${w.name}</small></button>`).join('')}</div>
    <p class="wk-note"><b>${wk.name}.</b> ${esc(wk.note)}</p>
    <details class="rule"><summary>Как добавлять вес</summary><p>Работайте в диапазоне повторов из карточки. Когда во всех подходах сделали верхнюю границу, в следующий раз добавьте вес — 1–2,5 кг для верха тела, 2,5–5 кг для ног — и начните с нижней границы. Если записывать подходы в карточках, планировщик сам подскажет, когда прибавлять. После разгрузки повторите цикл с новыми весами.</p></details>
  </section>
  <nav class="days" role="tablist" aria-label="Дни недели">${prog.days.map((d, i) => `<button type="button" role="tab" class="${i === S.day ? 'on' : ''}" data-day="${i}" aria-selected="${i === S.day}"><b>${WD[d.wd]}</b><span>${esc(d.name)}</span><small>${d.plan.items ? `≈${d.plan.minutes} мин` : 'нет упражнений'}</small></button>`).join('')}</nav>
  <div class="day-head"><h2>${WD_FULL[day.wd]} — ${esc(day.name)}</h2>
    <p>${(plan.groups || DAY_T[day.tid].g).map(g => GN[g].toLowerCase()).join(', ')}${plan.items ? ` · ≈${plan.minutes} мин · ${plan.totalSets} ${plural(plan.totalSets, 'подход', 'подхода', 'подходов')}` : ''}</p></div>`;
  if (!plan.items) html += `<div class="empty"><h2>Для этого дня нет упражнений</h2><p>С выбранным оборудованием нечем нагрузить эти мышцы. Добавьте оборудование или выберите другой сплит.</p></div>`;
  else html += autoregHtml() + gentleHtml() + warnHtml(plan) + blocksHtml(plan);
  html += LEGEND;
  $('#plan').innerHTML = html;
  if (plan.items) mountFigures();
}

/* ===================== АНАЛОГИ УПРАЖНЕНИЙ =====================
   Замена по смыслу, а не по названию: то же движение (PATTERN), те же работающие мышцы, близкий уровень.
   Каждая замена объясняет, что меняется: другой снаряд, другая мышца в акценте, работа по одной стороне. */
const PATTERN_NAMES = {squat:'присед', hinge:'наклон от таза', hpush:'горизонтальный жим', ipush:'жим под углом вверх', dpush:'жим под углом вниз',
  fly:'сведение рук', pullover:'пуловер', vpull:'вертикальная тяга', hrow:'горизонтальная тяга', vpush:'жим вверх', raise:'подъём рук',
  rear:'задняя дельта и лопатки', curl:'сгибание рук', ext:'разгибание рук', lunge:'выпад', bridge:'ягодичный мост', flex:'скручивание',
  hold:'удержание корпуса', side:'боковой наклон', calf:'подъём на носки', grip:'хват', jump:'прыжки', burpee:'бёрпи', climb:'скалолаз',
  adduct:'сведение ног', extrot:'вращение плеча наружу', run:'бег', ride:'вращение педалей', row:'гребля', kneeext:'разгибание колена', kneeflex:'сгибание колена', shrug:'шраги'};
/* движения, которым не нашлось места в общей таблице */
[['kneeext', 'legext'], ['kneeflex', 'legcurl nordic'], ['shrug', 'shrug'], ['raise', 'frontraise']].forEach(([p, ids]) => ids.split(' ').forEach(id => PATTERN[id] = p));

/* вид сопротивления: от него зависит, как ощущается замена */
const LOAD_KIND_NOTE = {
  band:'резина: сопротивление растёт к концу амплитуды',
  body:'вес тела: усложняйте темпом и амплитудой',
  free:'свободный вес: больше работы мышц-стабилизаторов',
  machine:'тренажёр ведёт траекторию: меньше стабилизации',
  cable:'блок: нагрузка ровнее по всей амплитуде'
};
function loadKind(ex, E) {
  const ids = E ? chosenEquip(ex, E) : ex.eq.map(g => g[0]);
  const cat = id => (EQUIP.find(e => e.id === id) || {}).cat;
  if (ids.some(id => id === 'cable')) return 'cable';
  if (ids.some(id => cat(id) === 'mach' || cat(id) === 'cardio')) return 'machine';
  if (ids.some(id => id === 'band')) return 'band';
  if (ids.some(id => ['db', 'bb', 'kb'].includes(id)) || (E && (ex.opt || []).some(id => ['db', 'kb'].includes(id) && E.has(id)))) return 'free';
  return 'body';
}
function muscleVector(ex) { const v = {}; for (const m of ex.pri) v[m] = 1; for (const m of ex.sec) v[m] = Math.max(v[m] || 0, .45); return v; }
function cosine(a, b) {
  let d = 0, na = 0, nb = 0;
  for (const [k, x] of Object.entries(a)) { na += x * x; if (b[k]) d += x * b[k]; }
  for (const x of Object.values(b)) nb += x * x;
  return na && nb ? d / Math.sqrt(na * nb) : 0;
}
/* близость упражнения b к a: 0…1 с небольшим запасом; движение и мышцы весят больше всего */
function analogScore(a, b) {
  const same = PATTERN[a.id] && PATTERN[a.id] === PATTERN[b.id];
  let s = .55 * cosine(muscleVector(a), muscleVector(b)) + (same ? .35 : 0) + (a.g === b.g ? .1 : 0);
  s -= .05 * Math.max(0, b.lvl - a.lvl);
  s -= .15 * (1 - (EX_W[b.id] ?? 1));
  if (!!a.uni !== !!b.uni) s -= .03;
  if ((a.kind || '') !== (b.kind || '')) s -= .08;
  return s;
}
/* что меняется при замене a → b: коротко, не больше трёх пунктов */
function analogNote(a, b, E) {
  const out = [], name = m => MUSCLE_NAMES[m].toLowerCase();
  if (PATTERN[b.id] && PATTERN[a.id] !== PATTERN[b.id]) out.push('другое движение: ' + PATTERN_NAMES[PATTERN[b.id]]);
  const bAll = new Set(b.pri.concat(b.sec)), aAll = new Set(a.pri.concat(a.sec));
  const lost = a.pri.filter(m => !bAll.has(m)), gained = b.pri.filter(m => !aAll.has(m));
  if (lost.length) out.push('меньше нагрузки: ' + lost.slice(0, 2).map(name).join(', '));
  if (gained.length) out.push('добавляется: ' + gained.slice(0, 2).map(name).join(', '));
  const ka = loadKind(a), kb = loadKind(b, E);
  if (ka !== kb && LOAD_KIND_NOTE[kb]) out.push(LOAD_KIND_NOTE[kb]);
  if (b.uni && !a.uni) out.push('по одной стороне — подход дольше');
  return out.slice(0, 3).join('; ');
}
/* лучшие замены упражнения ex среди доступных при оборудовании E */
function analogsFor(ex, E, {exclude = new Set(), lvlMax = 3, limit = 5, min = .45, ok = null} = {}) {
  const cardio = ex.g === 'cardio';
  return EX.filter(b => b !== ex && !exclude.has(b.id) && available(b, E) && b.lvl <= lvlMax && (b.g === 'cardio') === cardio && (!ok || ok(b)))
    .map(b => ({ex:b, score:analogScore(ex, b)}))
    .filter(r => r.score >= min)
    .sort((x, y) => y.score - x.score)
    .slice(0, limit)
    .map(r => ({...r, note:analogNote(ex, r.ex, E)}));
}

/* ===================== МЕСТА ТРЕНИРОВОК =====================
   У каждого места свой инвентарь: зал, дом, площадка во дворе. S.equip — инвентарь текущего места. */
const PLACE_DEFAULTS = [
  {id:'gym', name:'Зал', equip:EQUIP.map(e => e.id)},
  {id:'home', name:'Дом', equip:['db', 'band', 'abwheel']},
  {id:'street', name:'Улица', equip:['pullup', 'dipbars']}
];
function ensurePlaces(s) {
  if (!Array.isArray(s.places) || !s.places.length) {
    s.places = PLACE_DEFAULTS.map(p => ({...p, equip:p.equip.slice()}));
    /* перенос старой настройки: инвентарь, который уже был выбран, становится инвентарём подходящего места */
    const same = (a, b) => a.length === b.length && a.every(x => b.includes(x));
    const match = s.places.find(p => same(p.equip, s.equip || []));
    if (match) s.place = match.id;
    else { s.place = 'gym'; s.places[0].equip = (s.equip || []).slice(); }
  }
  if (!s.places.some(p => p.id === s.place)) s.place = s.places[0].id;
  if (s.adapt && (!s.places.some(p => p.id === s.adapt) || s.adapt === s.place)) s.adapt = null;
  s.equip = placeOf(s).equip.slice();
  return s;
}
function placeOf(s = S, id = s.place) { return s.places.find(p => p.id === id) || s.places[0]; }
function setPlaceEquip(list) { S.equip = list.slice(); placeOf().equip = list.slice(); }
/* инвентарь, под который собирается программа: своё место или выбранное «как в …» */
function programEquip() { return S.adapt && S.adapt !== S.place ? placeOf(S, S.adapt).equip : null; }
ensurePlaces(S);

/* ===================== СТАТОДИНАМИКА =====================
   Медленно, без пауз и без расслабления, в неполной амплитуде: мышца всё время напряжена, кровоток в ней пережат,
   к концу подхода — сильное жжение, но не отказ. Три подхода с короткой паузой — одна серия.
   Основания: В. Н. Селуянов — статодинамический режим (30–70% от максимума, подход 30–60 с, отдых 20–60 с,
   не меньше трёх подходов, без полного расслабления); Tanimoto, Ishii 2006, J Appl Physiol 100(4):1150–1157 —
   около 50% 1ПМ, 3 с опускание и 3 с подъём без расслабления, 3 подхода: прирост массы и силы как при 80% 1ПМ. */
const STATIC = {
  tempo:'3-0-3-0', reps:'5–7', work:36, rest:30, perSeries:3, nextExercise:120,
  series:{beg:1, mid:2, adv:3}, seriesRest:{beg:180, mid:180, adv:240},
  /* показ на манекене: рабочая часть амплитуды без выпрямления вверху и без провала внизу */
  partial:[.12, .88]
};
/* где медленная неполная амплитуда не имеет смысла или опасна при утомлении:
   кардио, удержания, прыжки, махи гирей, тяги с пола и наклоны со штангой (поясница), подтягивания на весе тела
   (30–40 с без расслабления почти никому не по силам), уступающие сгибания, ролик, пистолет */
const STATIC_SKIP = new Set(['kbswing', 'deadlift', 'goodmorning', 'pullup', 'chinup', 'nordic', 'rollout', 'pistolbox']);
function staticOk(ex) {
  if (ex.g === 'cardio' || ex.kind || ex.anim.hold || ex.anim.loop || STATIC_SKIP.has(ex.id)) return false;
  return !['jump', 'burpee', 'climb'].includes(PATTERN[ex.id]);
}
/* назначение в статодинамике поверх обычного: серии по три подхода, медленный темп, нагрузка по жжению */
function staticRx(rx, ex, week, E) {
  let series = STATIC.series[S.level] || 2;
  if (week && week.deload) series = Math.max(1, series - 1);
  const band = ex.eq.length && ex.eq.every(g => g.every(id => id === 'band')), assisted = ex.eq.some(g => g.includes('gravitron'));
  const load = weighable(ex, E) ? '≈ 40–60% от 1ПМ: к концу подхода сильное жжение, но не отказ'
    : band ? 'натяжение ленты: к концу подхода сильное жжение, но не отказ'
    : assisted ? 'противовес: к концу подхода сильное жжение, но не отказ'
    : 'вес тела: если жжения нет — медленнее и без отдыха в крайних точках';
  return {...rx, sets:series * STATIC.perSeries, series, reps:STATIC.reps, unit:'повт.', rest:STATIC.rest, seriesRest:STATIC.seriesRest[S.level] || 180,
    tempo:STATIC.tempo, load, work:STATIC.work * (ex.uni ? 2 : 1), static:true, partial:STATIC.partial,
    notes:[...rx.notes, 'Подход ≈ 30–40 с: 3 с вниз и 3 с вверх без пауз, не выпрямляйтесь до конца и не расслабляйтесь внизу.']};
}
/* отдых после подхода k (с нуля): внутри серии коротко, между сериями долго, после последнего — переход к следующему */
function restAfter(rx, k) {
  if (!rx.static) return rx.restShown !== undefined ? rx.restShown : rx.rest;
  if (k + 1 >= rx.sets) return STATIC.nextExercise;
  return (k + 1) % STATIC.perSeries === 0 ? rx.seriesRest : rx.rest;
}
/* время упражнения в статодинамике, секунды */
function staticSeconds(rx) {
  return rx.series * (STATIC.perSeries * rx.work + (STATIC.perSeries - 1) * rx.rest) + (rx.series - 1) * rx.seriesRest + STATIC.nextExercise;
}

/* ===================== ИЗБРАННОЕ И СВОЙ ПЛАН =====================
   Избранное — упражнения, отмеченные звёздочкой в атласе, в разборе движения или в карточке плана.
   Свой план — тренировка из упражнений, выбранных вручную (из избранного или по мышцам): порядок, подходы,
   повторы и отдых задаёт человек; по умолчанию дозировку подставляют цель, формат и уровень, как в обычном плане.
   Своих планов может быть несколько, у каждого имя. Журнал, разминка, подсказки веса и режим тренировки — общие. */
const CUSTOM_MAX = 12, CUSTOM_NAME = 40, CUSTOM_TEXT = 40, CUSTOM_NOTE = 400, ITEM_NOTE = 200;
const CUSTOM_REPS = /^(\d{1,3})(?:\s*[–-]\s*(\d{1,3}))?$/;
const CUSTOM_TEMPO = /^[0-9X]{1,2}-[0-9X]{1,2}-[0-9X]{1,2}-[0-9X]{1,2}$/;
const PLAN_KEYS = ['goal', 'format', 'level'];
let cpTab = null, cpOpen = new Set(), cpDel = false, cpMsg = '';

/* текст от человека или из чужого файла: без управляющих символов, с ограничением длины (переводы строк в заметках остаются) */
function cleanText(v, max, lines = false) {
  if (typeof v !== 'string') return '';
  return v.replace(lines ? /[\u0000-\u0009\u000B-\u001F\u007F]/g : /[\u0000-\u001F\u007F]/g, lines ? '' : ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
}
/* вес: одно число на все подходы или по подходам; 0–500 кг, шаг 0,25 */
function cleanKg(v) {
  const list = (Array.isArray(v) ? v : [v]).map(x => typeof x === 'string' ? parseFloat(x.replace(',', '.')) : x)
    .filter(x => typeof x === 'number' && Number.isFinite(x) && x >= 0 && x <= 500).map(x => Math.round(x * 4) / 4).slice(0, 10);
  return list.length ? list : null;
}
/* ввод веса: «60», «62,5», «60 / 62,5 / 65», «60, 62,5, 65» — запятая с пробелом, пробел, «/» и «;» разделяют подходы,
   запятая внутри числа — десятичная */
function parseKgInput(text) {
  return cleanKg(String(text || '').split(/\s*[;\/]\s*|,\s+|\s+/).map(x => x.trim()).filter(Boolean));
}
function cleanCustomItem(it) {
  if (!it || !EXI[it.id]) return null;
  const o = {id:it.id};
  if (Number.isInteger(it.sets) && it.sets >= 1 && it.sets <= 10) o.sets = it.sets;
  const m = typeof it.reps === 'string' && it.reps.trim().match(CUSTOM_REPS);
  if (m && +m[1] >= 1 && (!m[2] || +m[2] >= +m[1])) o.reps = m[2] ? `${+m[1]}–${+m[2]}` : String(+m[1]);
  if (Number.isInteger(it.rest) && it.rest >= 0 && it.rest <= 600) o.rest = it.rest;
  const kg = it.kg != null ? cleanKg(it.kg) : null; if (kg) o.kg = kg;
  if (typeof it.tempo === 'string' && CUSTOM_TEMPO.test(it.tempo.trim().toUpperCase())) o.tempo = it.tempo.trim().toUpperCase();
  const note = cleanText(it.note, ITEM_NOTE, true); if (note) o.note = note;
  return o;
}
function cleanPlan(c, id) {
  const ids = new Set(), out = {id, name:cleanText(c.name, CUSTOM_NAME) || 'Мой план',
    items:(Array.isArray(c.items) ? c.items : []).map(cleanCustomItem).filter(it => it && !ids.has(it.id) && ids.add(it.id)).slice(0, CUSTOM_MAX)};
  for (const [k, dict] of [['goal', GOALS], ['format', FORMATS], ['level', LEVELS]]) if (typeof c[k] === 'string' && dict[c[k]]) out[k] = c[k];
  for (const k of ['group', 'for', 'from']) { const v = cleanText(c[k], CUSTOM_TEXT); if (v) out[k] = v; }
  const note = cleanText(c.note, CUSTOM_NOTE, true); if (note) out.note = note;
  return out;
}
/* настройки из хранилища или резервной копии: только известные упражнения и разумные значения */
function ensureCustoms(s) {
  s.fav = Array.isArray(s.fav) ? [...new Set(s.fav.filter(id => typeof id === 'string' && EXI[id]))] : [];
  const seen = new Set();
  s.customs = (Array.isArray(s.customs) ? s.customs : []).filter(c => c && typeof c.id === 'string' && /^[\w-]{1,24}$/.test(c.id) && !seen.has(c.id) && seen.add(c.id)).map(c => cleanPlan(c, c.id));
  if (!s.customs.length) s.customs.push({id:'c1', name:'Мой план', items:[]});
  if (!s.customs.some(c => c.id === s.custom)) s.custom = s.customs[0].id;
  if (!MODES[s.mode]) s.mode = 'single';
  s.author = cleanText(s.author, CUSTOM_TEXT);
  /* цель, формат и уровень обычных планов, пока открыт свой план (у своего — свои) */
  const g = s.gen && typeof s.gen === 'object' ? s.gen : {};
  s.gen = {goal:GOALS[g.goal] ? g.goal : s.goal, format:FORMATS[g.format] ? g.format : s.format, level:LEVELS[g.level] ? g.level : s.level};
  return s;
}
function newPlanId() { let id; do id = 'c' + Date.now().toString(36) + Math.floor(Math.random() * 1296).toString(36); while (S.customs.some(c => c.id === id)); return id; }
function customOf(s = S) { return s.customs.find(c => c.id === s.custom) || s.customs[0]; }

/* У каждого своего плана свои цель, формат и уровень: план выглядит одинаково у тренера и у ученика.
   Переключатели в параметрах правят открытый план; обычная тренировка и неделя держат свои (S.gen). */
function loadPlanSettings() { const c = customOf(); for (const k of PLAN_KEYS) { if (!c[k]) c[k] = S[k]; S[k] = c[k]; } }
function storePlanSetting(k) { if (S.mode === 'custom' && PLAN_KEYS.includes(k)) customOf()[k] = S[k]; else if (PLAN_KEYS.includes(k)) S.gen[k] = S[k]; }
function switchModeSettings(prev) {
  if (prev !== 'custom' && S.mode === 'custom') { for (const k of PLAN_KEYS) S.gen[k] = S[k]; loadPlanSettings(); }
  else if (prev === 'custom' && S.mode !== 'custom') for (const k of PLAN_KEYS) S[k] = S.gen[k];
}
function openCustom(id) {
  const prev = S.mode; if (id) S.custom = id;
  S.mode = 'custom'; S.view = 'plan'; S.day = 0; cpOpen = new Set(); cpDel = false;
  if (prev === 'custom') loadPlanSettings(); else switchModeSettings(prev);
}
ensureCustoms(S);
if (S.mode === 'custom') loadPlanSettings();

/* ---------- избранное ---------- */
const isFav = id => S.fav.includes(id);
function toggleFav(id) {
  if (!EXI[id]) return;
  S.fav = isFav(id) ? S.fav.filter(x => x !== id) : S.fav.concat(id);
  saveSettings(); refreshFav(id);
}
function favLabel(on) { return on ? 'Убрать из избранного' : 'В избранное'; }
function favButton(id, text = false) {
  const on = isFav(id);
  return `<button type="button" class="fav${on ? ' on' : ''}${text ? ' fav-t' : ''}" data-fav="${id}" aria-pressed="${on}" aria-label="${favLabel(on)}: ${esc(EXI[id].name)}" title="${favLabel(on)}"><span class="fav-i" aria-hidden="true">${on ? '★' : '☆'}</span>${text ? `<span class="fav-l">${on ? 'В избранном' : 'В избранное'}</span>` : ''}</button>`;
}
/* звёздочки обновляются на месте: анимации и открытые панели не перестраиваются */
function refreshFav(id) {
  const on = isFav(id);
  for (const b of document.querySelectorAll(`[data-fav="${id}"]`)) {
    b.classList.toggle('on', on); b.setAttribute('aria-pressed', String(on)); b.setAttribute('title', favLabel(on));
    b.setAttribute('aria-label', `${favLabel(on)}: ${EXI[id].name}`);
    const i = b.querySelector('.fav-i'); if (i) i.textContent = on ? '★' : '☆';
    const l = b.querySelector('.fav-l'); if (l) l.textContent = on ? 'В избранном' : 'В избранное';
  }
  const n = document.querySelector('[data-cp-tab="fav"] small'); if (n) n.textContent = S.fav.length || '';
  const c = document.querySelector('.at-favn'); if (c) c.textContent = S.fav.length;
  if (S.view === 'plan' && S.mode === 'custom' && (cpTab || 'fav') === 'fav' && $('#cp-list')) $('#cp-list').innerHTML = customListHtml();
}

/* ---------- свой план: правка ---------- */
const customHas = id => customOf().items.some(it => it.id === id);
function customAdd(id) {
  const c = customOf();
  if (!EXI[id] || customHas(id) || c.items.length >= CUSTOM_MAX) return false;
  c.items.push({id}); saveSettings(); return true;
}
function customMove(slot, d) {
  const items = customOf().items, j = slot + d;
  if (slot < 0 || j < 0 || slot >= items.length || j >= items.length) return;
  [items[slot], items[j]] = [items[j], items[slot]];
  const a = cpOpen.has(slot), b = cpOpen.has(j); cpOpen.delete(slot); cpOpen.delete(j); if (a) cpOpen.add(j); if (b) cpOpen.add(slot);
  saveSettings();
}
function customRemove(slot) {
  const items = customOf().items; items.splice(slot, 1);
  cpOpen = new Set([...cpOpen].filter(i => i !== slot).map(i => i > slot ? i - 1 : i)); saveSettings();
}
function customSet(slot, key, value) {
  const items = customOf().items, it = items[slot]; if (!it) return;
  const next = {...it}, clear = value === null || value === undefined || value === '';
  if (clear) delete next[key]; else next[key] = value;
  const ok = cleanCustomItem(next);
  if (!ok || (!clear && !(key in ok))) return;   /* неверное значение не стирает прежнее */
  items[slot] = ok; saveSettings();
}

/* дозировка по цели и формату, поверх — правка человека (кроме статодинамики: там серии заданы методом) */
function customRx(rx, o, ex) {
  if (!o) return rx;
  const r = {...rx};
  if (!rx.static) {
    if (o.sets) r.sets = o.sets;
    if (o.reps && !ex.kind) { r.reps = o.reps; r.work = midOf(o.reps) * GOALS[S.goal].rep * (ex.uni ? 2 : 1); }
    if (o.rest !== undefined) r.rest = o.rest;
    if (o.tempo && !ex.kind) r.tempo = o.tempo;
  }
  /* вес и заметка тренера — и в статодинамике */
  if (o.kg) r.kgPlan = o.kg;
  if (o.note) r.coachNote = o.note;
  r.edited = r.sets !== rx.sets || r.reps !== rx.reps || r.rest !== rx.rest || r.tempo !== rx.tempo || !!o.kg || !!o.note;
  return r;
}
/* вес по плану для подхода k (с нуля): список короче подходов — последний вес повторяется */
const planKg = (rx, k) => rx && rx.kgPlan ? rx.kgPlan[Math.min(k, rx.kgPlan.length - 1)] : null;
function planKgText(list) { return list.every(v => v === list[0]) ? fmtKg(list[0]) : list.map(fmtKg).join(' / '); }

/* подсказки по составу: выбранные мышцы без упражнений и заметный перекос жимов и тяг, передней и задней поверхности бедра */
function customHints(p) {
  const out = [], v = g => p.gvol[g] || 0;
  const idle = S.groups.filter(g => g !== 'cardio' && v(g) < 1);
  if (idle.length) out.push(`Пока не нагружены: ${idle.map(g => GN[g].toLowerCase()).join(', ')}. Добавьте упражнение ниже — или снимите эти мышцы в параметрах.`);
  /* перекос — по основным упражнениям (не по вспомогательной работе) и только когда в плане есть обе стороны:
     день «только жим» или «только тяга» — осознанный выбор */
  const sets = g => p.items.filter(it => g.includes(it.ex.g)).reduce((a, it) => a + (it.rounds || it.rx.sets), 0);
  const push = sets(['chest', 'shoulders']), pull = sets(['back']);
  if (pull >= 1 && push >= 4 && push > pull * 2.5) out.push('Жимов заметно больше, чем тяг. Плечевым суставам полезен баланс: добавьте тягу для спины — горизонтальную или вертикальную.');
  else if (push >= 1 && pull >= 4 && pull > push * 2.5) out.push('Тяг заметно больше, чем жимов. Для баланса добавьте жим — для груди или плеч.');
  return out;
}

/* ---------- отрисовка ---------- */
/* список своих планов: без программы — сверху, программы — группами со своим заголовком */
function customSetupHtml() {
  const c = customOf(), groups = [...new Set(S.customs.map(p => p.group || ''))].sort((a, b) => (a ? 1 : 0) - (b ? 1 : 0));
  const chip = p => `<button type="button" class="place${p.id === c.id ? ' on' : ''}" data-cp-plan="${p.id}" aria-pressed="${p.id === c.id}"><b>${esc(p.name)}</b><small>${p.items.length ? p.items.length + ' ' + plural(p.items.length, 'упражнение', 'упражнения', 'упражнений') : 'пусто'}</small></button>`;
  const lists = groups.map(g => `${g ? `<p class="cp-group">${esc(g)}</p>` : ''}<div class="places cp-plans" role="group" aria-label="${g ? esc(g) : 'Свои планы'}">${S.customs.filter(p => (p.group || '') === g).map(chip).join('')}</div>`).join('');
  const known = [...new Set(S.customs.map(p => p.group).filter(Boolean))];
  return `${lists}<div class="cp-acts"><button type="button" class="place place-add" data-cp-new="1">+ План</button><button type="button" class="btn-ghost" data-cp-copy="1">Копия плана</button><button type="button" class="btn-ghost" data-cp-import="1">${ICON.load}<span>Загрузить план</span></button></div>`
    + `<div class="place-tools"><label class="place-name">Название<input id="cp-name" type="text" maxlength="${CUSTOM_NAME}" value="${esc(c.name)}" autocomplete="off"></label>`
    + (S.customs.length > 1 ? `<button type="button" class="place-del${cpDel ? ' armed' : ''}" data-cp-del="1">${cpDel ? 'Точно удалить?' : 'Удалить план'}</button>` : '') + `</div>`
    + `<details class="cp-about"${c.group || c.for || c.note ? ' open' : ''}><summary>Программа, для кого, заметка</summary><div class="cp-about-f">
        <label class="place-name">Программа<input id="cp-group" type="text" maxlength="${CUSTOM_TEXT}" list="cp-groups" value="${esc(c.group || '')}" placeholder="Например: Сила, неделя 1" autocomplete="off"><datalist id="cp-groups">${known.map(g => `<option value="${esc(g)}"></option>`).join('')}</datalist></label>
        <label class="place-name">Для кого<input id="cp-for" type="text" maxlength="${CUSTOM_TEXT}" value="${esc(c.for || '')}" placeholder="Имя ученика" autocomplete="off"></label>
        <label class="place-name cp-pnote">Заметка к плану<textarea id="cp-pnote" rows="2" maxlength="${CUSTOM_NOTE}" placeholder="Цель, самочувствие, что важно в этой тренировке">${esc(c.note || '')}</textarea></label>
        ${c.from ? `<p class="f-note">От кого: ${esc(c.from)}</p>` : ''}
      </div></details>`;
}
function customRowHtml(ex, E) {
  const here = available(ex, E), inPlan = customHas(ex.id), full = customOf().items.length >= CUSTOM_MAX, name = exName(ex, here ? E : effEquip(EQUIP.map(e => e.id)));
  const add = inPlan ? `<button type="button" class="cp-addb in" disabled>✓ В плане</button>`
    : full ? `<button type="button" class="cp-addb" disabled>Не больше ${CUSTOM_MAX}</button>`
    : `<button type="button" class="cp-addb" data-cp-add="${ex.id}" aria-label="Добавить в план: ${esc(name)}">+ В план</button>`;
  return `<li class="cp-row${here ? '' : ' away'}">${favButton(ex.id)}<button type="button" class="cp-open" data-cp-open="${ex.id}" aria-haspopup="dialog" aria-controls="motion-view" aria-label="Разобрать движение: ${esc(name)}"><b>${esc(name)}</b><small>${esc(here ? equipLine(ex, E) : 'здесь нет инвентаря — в плане будет замена')} · ${esc(ex.pri.slice(0, 2).map(m => MUSCLE_NAMES[m].toLowerCase()).join(', '))}${ex.lvl >= 3 ? ' · сложное' : ''}${unfitHtml(ex, true)}</small></button>${add}</li>`;
}
function customListHtml() {
  const E = effEquip(S.equip), tab = cpTab || (S.fav.length ? 'fav' : 'groups');
  if (tab === 'fav') {
    if (!S.fav.length) return `<li class="cp-none">Избранного пока нет. Отметьте упражнения звёздочкой ☆ — здесь, в атласе мышц или в разборе движения.</li>`;
    return S.fav.map(id => customRowHtml(EXI[id], E)).join('');
  }
  if (!S.groups.length) return `<li class="cp-none">Отметьте мышцы в параметрах — здесь появятся упражнения для них.</li>`;
  const lvlMax = S.level === 'beg' ? 2 : 3;
  return S.groups.map(g => {
    const list = EX.filter(ex => ex.g === g && available(ex, E) && ex.lvl <= lvlMax).sort((a, b) => (fitsBody(a) ? 0 : 1) - (fitsBody(b) ? 0 : 1) || (a.type === 'c' ? 0 : 1) - (b.type === 'c' ? 0 : 1) || (EX_W[b.id] ?? 1) - (EX_W[a.id] ?? 1));
    /* по шесть на группу, остальное — по кнопке: на телефоне список не превращается в ленту */
    const rows = list.map((ex, i) => customRowHtml(ex, E).replace('<li class="cp-row', i >= 6 ? `<li hidden data-cp-g="${g}" class="cp-row` : '<li class="cp-row'));
    return list.length ? `<li class="cp-gh">${esc(GN[g])} <small>${list.length}</small></li>` + rows.join('') + (list.length > 6 ? `<li class="cp-morel"><button type="button" class="link" data-cp-more="${g}">Ещё ${list.length - 6}</button></li>` : '') : '';
  }).join('') || `<li class="cp-none">Для этих мышц здесь нет упражнений — добавьте инвентарь места.</li>`;
}
function customAddHtml() {
  const tab = cpTab || (S.fav.length ? 'fav' : 'groups'), E = effEquip(S.equip), lvlMax = S.level === 'beg' ? 2 : 3;
  const nG = EX.filter(ex => S.groups.includes(ex.g) && available(ex, E) && ex.lvl <= lvlMax).length;
  const t = (id, label, n) => `<button type="button" role="tab" data-cp-tab="${id}" aria-selected="${tab === id}" class="${tab === id ? 'on' : ''}">${label} <small>${n || ''}</small></button>`;
  return `<section class="cp-add" id="cp-add" aria-labelledby="cp-add-h">
    <h2 id="cp-add-h">Добавить упражнение</h2>
    <div class="cp-tabs" role="tablist" aria-label="Откуда добавить">${t('fav', '★ Избранное', S.fav.length)}${t('groups', 'По выбранным мышцам', nG)}</div>
    <ol class="cp-list" id="cp-list">${customListHtml()}</ol>
    <p class="f-note">Звёздочка ☆ добавляет упражнение в избранное. Больше вариантов с описанием мышц — в атласе. <button type="button" class="link" data-view="atlas">Открыть атлас мышц →</button></p>
  </section>`;
}
/* панель под карточкой своего плана: порядок, подходы, повторы, отдых */
function customToolsHtml(it) {
  const c = customOf(), slot = it.slot, o = c.items[slot] || {}, r = it.rx, open = cpOpen.has(slot), n = c.items.length;
  const restOpts = [0, 15, 30, 45, 60, 75, 90, 120, 150, 180, 240, 300];
  if (!restOpts.includes(r.rest)) restOpts.push(r.rest), restOpts.sort((a, b) => a - b);
  const edit = r.static ? `<p class="f-note">В статодинамике серии, темп и отдых заданы методом — меняются цель и уровень.</p>`
    : `<div class="cp-fields">
        ${r.circ ? '' : `<div class="cp-f"><span>Подходов</span><div class="stepper sm"><button type="button" data-cp-step="${slot}" data-d="-1" aria-label="Меньше подходов"${r.sets <= 1 ? ' disabled' : ''}>−</button><output>${r.sets}</output><button type="button" data-cp-step="${slot}" data-d="1" aria-label="Больше подходов"${r.sets >= 10 ? ' disabled' : ''}>+</button></div></div>`}
        ${it.ex.kind ? '' : `<label class="cp-f"><span>Повторов</span><input type="text" inputmode="numeric" maxlength="7" data-cp-reps="${slot}" value="${esc(r.reps)}" aria-label="Повторов, например 8–12"></label>`}
        ${r.circ ? '' : `<label class="cp-f"><span>Отдых</span><select data-cp-rest="${slot}">${restOpts.map(s => `<option value="${s}"${s === r.rest ? ' selected' : ''}>${s ? fmtRest(s) : 'без отдыха'}</option>`).join('')}</select></label>`}
        ${it.ex.kind ? '' : `<label class="cp-f"><span>Темп</span><input type="text" maxlength="11" data-cp-tempo="${slot}" value="${esc(o.tempo || '')}" placeholder="${esc(r.tempo || '3-0-1-0')}" aria-label="Темп: опускание, пауза, подъём, пауза — например 3-0-1-0" autocomplete="off"></label>`}
        ${o.sets || o.reps || o.rest !== undefined || o.tempo ? `<button type="button" class="btn-ghost cp-reset" data-cp-reset="${slot}">Как по цели</button>` : ''}
      </div>`;
  const lt = loadType(it.ex), kgLabel = lt === 'assist' ? 'Противовес, кг' : lt === 'extra' ? 'Доп. вес, кг' : 'Вес, кг';
  const extra = `<div class="cp-fields">
      ${lt === 'none' ? '' : `<label class="cp-f cp-kg"><span>${kgLabel}</span><input type="text" maxlength="60" data-cp-kg="${slot}" value="${o.kg ? esc(o.kg.map(fmtKg).join(' / ')) : ''}" placeholder="60 или 60 / 62,5 / 65" aria-label="${kgLabel}: одно число на все подходы или по подходам через «/»" autocomplete="off"></label>`}
      <label class="cp-f cp-note"><span>Заметка к упражнению</span><textarea rows="2" maxlength="${ITEM_NOTE}" data-cp-note="${slot}" placeholder="Например: пауза 1 с на груди">${esc(o.note || '')}</textarea></label>
    </div>`;
  return `<div class="cp-tools">
    <button type="button" class="btn-ghost" data-cp-move="${slot}" data-d="-1" aria-label="Выше"${slot === 0 ? ' disabled' : ''}>↑</button>
    <button type="button" class="btn-ghost" data-cp-move="${slot}" data-d="1" aria-label="Ниже"${slot >= n - 1 ? ' disabled' : ''}>↓</button>
    <button type="button" class="btn-ghost${r.edited ? ' cp-edited' : ''}" data-cp-edit="${slot}" aria-expanded="${open}">Подходы, вес, заметка${r.edited ? '<i class="cp-dot" aria-label="изменено"></i>' : ''}</button>
    <button type="button" class="btn-ghost cp-rm" data-cp-rm="${slot}">Убрать</button>
  </div>${open ? `<div class="cp-edit">${edit}${extra}</div>` : ''}`;
}
function customEmptyHtml() {
  return `<div class="empty cp-empty"><h2>План пока пустой</h2><p>Добавьте упражнения из избранного или из списка по выбранным мышцам. Подходы, повторы и отдых подставятся по цели и формату — их можно поправить в карточке.</p><p><button type="button" class="btn btn-2" data-cp-import="1">${ICON.load}<span>Загрузить план из файла</span></button></p></div>`;
}
/* под названием своего плана: программа, для кого, от кого и заметка */
function customHeadHtml() {
  /* название программы само может содержать «·», поэтому части разделены отступом, а значения выделены */
  const c = customOf(), sub = [c.group ? `<span>программа: <b>${esc(c.group)}</b></span>` : '', c.for ? `<span>для: <b>${esc(c.for)}</b></span>` : '', c.from ? `<span>от: <b>${esc(c.from)}</b></span>` : ''].filter(Boolean);
  return (sub.length ? `<p class="cp-sub">${sub.join('')}</p>` : '') + (c.note ? `<p class="c-note cp-pn">${esc(c.note)}</p>` : '');
}

/* ---------- сохранить собранный план как свой ----------
   Обычная тренировка и неделя пересобираются при любой смене настроек; сохранение фиксирует состав, порядок
   и дозировку, какими они видны сейчас. Неделя — несколько планов с общим названием программы. */
function uniquePlanName(name, taken = S.customs.map(c => c.name)) {
  const base = cleanText(name, CUSTOM_NAME - 4) || 'Мой план';
  if (!taken.includes(base)) return base;
  for (let k = 2; ; k++) { const v = `${base} (${k})`; if (!taken.includes(v)) return v; }
}
function freezePlan(p) {
  return p.blocks.flatMap(b => b.items).map(it => {
    const r = it.rx, o = {id:it.ex.id};
    if (!r.static) {
      if (!r.circ) { o.sets = r.sets; o.rest = r.rest; }
      if (!it.ex.kind && CUSTOM_REPS.test(String(r.reps))) o.reps = String(r.reps);
    }
    return cleanCustomItem(o);
  }).filter(Boolean).slice(0, CUSTOM_MAX);
}
function savePlansFrom() {
  const set = Object.fromEntries(PLAN_KEYS.map(k => [k, S[k]])), added = [];
  if (S.mode === 'program' && prog) {
    const group = cleanText(`${SPLITS[prog.split].name} · неделя ${S.week}`, CUSTOM_TEXT);
    for (const d of prog.days) if (d.plan.items) added.push({id:newPlanId(), name:uniquePlanName(`${WD[d.wd]} · ${d.name}`, S.customs.map(c => c.name).concat(added.map(c => c.name))), group, ...set, items:freezePlan(d.plan)});
  } else if (plan && plan.items) added.push({id:newPlanId(), name:uniquePlanName(titleFor()), ...set, items:freezePlan(plan)});
  S.customs.push(...added); saveSettings();
  return added;
}

/* ---------- события ---------- */
function customRerender(focusSel) {
  const y = window.scrollY; saveSettings(); renderSetup(); renderPlan(); window.scrollTo(0, y);
  if (focusSel) { const el = document.querySelector(focusSel); if (el) el.focus(); }
}
document.addEventListener('click', e => {
  const t = e.target.closest('button');
  if (!t) return;
  if (t.dataset.fav) { toggleFav(t.dataset.fav); return; }
  if (t.dataset.cpAdd) {
    const id = t.dataset.cpAdd, ok = customAdd(id);
    if (S.view === 'plan' && S.mode === 'custom') return customRerender(`[data-cp-tab="${cpTab || (S.fav.length ? 'fav' : 'groups')}"]`);
    cpMsg = ok ? `Добавлено в план: ${customOf().name}` : customHas(id) ? `Уже в плане: ${customOf().name}` : `В плане не больше ${CUSTOM_MAX} упражнений`;
    for (const m of document.querySelectorAll('.cp-msg')) { m.hidden = false; m.querySelector('span').textContent = cpMsg; }
    return;
  }
  if (t.id === 'save-plan') {
    const added = savePlansFrom(), msg = $('#save-msg');
    if (msg && added.length) msg.innerHTML = `Сохранено в свои планы: ${esc(added.map(c => c.name).join(', '))}. <button type="button" class="link" data-cp-go="${added[0].id}">Открыть →</button>`;
    return;
  }
  if (t.dataset.cpGo !== undefined) { if (document.querySelector('#motion-view')?.open) closeMotion(); openCustom(S.customs.some(c => c.id === t.dataset.cpGo) ? t.dataset.cpGo : null); regen(); window.scrollTo({top:0}); return; }
  if (t.dataset.cpOpen) { openMotionItem(previewItem(t.dataset.cpOpen)); return; }
  if (t.dataset.cpMore) { for (const li of document.querySelectorAll(`[data-cp-g="${t.dataset.cpMore}"]`)) li.hidden = false; t.closest('li').remove(); return; }
  if (t.dataset.cpTab) { cpTab = t.dataset.cpTab; for (const b of document.querySelectorAll('[data-cp-tab]')) { const on = b === t; b.classList.toggle('on', on); b.setAttribute('aria-selected', String(on)); } $('#cp-list').innerHTML = customListHtml(); return; }
  if (t.dataset.cpPlan) { openCustom(t.dataset.cpPlan); return regen(); }
  if (t.dataset.cpNew !== undefined) {
    const c = customOf(), id = newPlanId();
    S.customs.push({id, name:'План ' + (S.customs.length + 1), items:[], ...(c.group ? {group:c.group} : {}), ...Object.fromEntries(PLAN_KEYS.map(k => [k, S[k]]))});
    openCustom(id); regen();
    const inp = $('#cp-name'); if (inp) { inp.focus(); inp.select(); }
    return;
  }
  if (t.dataset.cpCopy !== undefined) {
    const c = customOf(), copy = JSON.parse(JSON.stringify(c)); copy.id = newPlanId(); copy.name = uniquePlanName(c.name + ' — копия');
    S.customs.splice(S.customs.indexOf(c) + 1, 0, copy); openCustom(copy.id); regen();
    const inp = $('#cp-name'); if (inp) { inp.focus(); inp.select(); }
    return;
  }
  if (t.dataset.cpDel !== undefined) {
    if (!cpDel) { cpDel = true; return renderSetup(); }
    S.customs = S.customs.filter(c => c.id !== S.custom); ensureCustoms(S); openCustom(S.customs[0].id); return regen();
  }
  if (S.mode !== 'custom' || S.view !== 'plan') return;
  if (t.dataset.cpMove !== undefined) { const s = +t.dataset.cpMove, d = +t.dataset.d; customMove(s, d); return customRerender(`[data-cp-move="${s + d}"][data-d="${d}"]`); }
  if (t.dataset.cpRm !== undefined) { customRemove(+t.dataset.cpRm); return customRerender(); }
  if (t.dataset.cpEdit !== undefined) { const s = +t.dataset.cpEdit; cpOpen.has(s) ? cpOpen.delete(s) : cpOpen.add(s); return customRerender(`[data-cp-edit="${s}"]`); }
  if (t.dataset.cpStep !== undefined) {
    const s = +t.dataset.cpStep, it = plan.items.find(x => x.slot === s);
    customSet(s, 'sets', Math.max(1, Math.min(10, it.rx.sets + +t.dataset.d)));
    return customRerender(`[data-cp-step="${s}"][data-d="${t.dataset.d}"]`);
  }
  if (t.dataset.cpReset !== undefined) { const s = +t.dataset.cpReset; for (const k of ['sets', 'reps', 'rest', 'tempo']) customSet(s, k, null); return customRerender(`[data-cp-edit="${s}"]`); }
});
document.addEventListener('change', e => {
  const t = e.target;
  if (['cp-group', 'cp-for', 'cp-pnote'].includes(t.id)) {
    const c = customOf(), k = {'cp-group':'group', 'cp-for':'for', 'cp-pnote':'note'}[t.id], v = k === 'note' ? cleanText(t.value, CUSTOM_NOTE, true) : cleanText(t.value, CUSTOM_TEXT);
    if (v) c[k] = v; else delete c[k];
    saveSettings(); if (k === 'group') renderSetup(); if (S.mode === 'custom' && S.view === 'plan') renderPlan(); return;
  }
  if (t.id === 'cp-name') { const v = t.value.trim().slice(0, CUSTOM_NAME); if (v) customOf().name = v; saveSettings(); renderSetup(); if (S.mode === 'custom' && S.view === 'plan') renderPlan(); return; }
  if (t.dataset.cpReps !== undefined) {
    const s = +t.dataset.cpReps, ok = cleanCustomItem({id:customOf().items[s]?.id, reps:t.value});
    if (ok && ok.reps) customSet(s, 'reps', ok.reps); else { t.value = plan.items.find(x => x.slot === s)?.rx.reps || ''; return; }
    return customRerender(`[data-cp-reps="${s}"]`);
  }
  if (t.dataset.cpRest !== undefined) { const s = +t.dataset.cpRest; customSet(s, 'rest', +t.value); return customRerender(`[data-cp-rest="${s}"]`); }
  if (t.dataset.cpKg !== undefined) {
    const s = +t.dataset.cpKg, v = t.value.trim(), kg = v ? parseKgInput(v) : null;
    if (v && !kg) { t.setAttribute('aria-invalid', 'true'); return; }
    customSet(s, 'kg', kg); return customRerender(`[data-cp-kg="${s}"]`);
  }
  if (t.dataset.cpTempo !== undefined) {
    const s = +t.dataset.cpTempo, v = t.value.trim().toUpperCase().replace(/[–—]/g, '-');
    if (v && !CUSTOM_TEMPO.test(v)) { t.setAttribute('aria-invalid', 'true'); return; }
    customSet(s, 'tempo', v || null); return customRerender(`[data-cp-tempo="${s}"]`);
  }
  if (t.dataset.cpNote !== undefined) { const s = +t.dataset.cpNote; customSet(s, 'note', cleanText(t.value, ITEM_NOTE, true) || null); return customRerender(`[data-cp-note="${s}"]`); }
});

/* ===================== ФАЙЛЫ ПЛАНОВ =====================
   Свои планы выгружаются в JSON и загружаются обратно — свои, от тренера, для ученика. Формат описан в docs/plan-format.md.
   Упражнения хранятся кодами каталога (общими для русской и английской версий), название — для чтения человеком.
   Подходы, повторы и отдых пишутся явно, как их видно в плане, — у получателя план выглядит так же. */
const PLAN_FILE = 'lazy-gym-planner/plans', PLAN_FILE_V = 1, PLAN_FILE_MAX = 256 * 1024, PLAN_FILE_PLANS = 50;
let planIn = null;

/* план с его целью, форматом и уровнем: дозировка считается так, как её видит владелец плана */
function withPlanSettings(c, fn) {
  const keep = PLAN_KEYS.map(k => S[k]);
  for (const k of PLAN_KEYS) if (c[k]) S[k] = c[k];
  try { return fn(); } finally { PLAN_KEYS.forEach((k, i) => { S[k] = keep[i]; }); }
}
function exportItem(c, item) {
  const ex = EXI[item.id];
  return withPlanSettings(c, () => {
    const rx = customRx(prescribe(ex, null, effEquip(EQUIP.map(e => e.id))), item, ex), o = {id:ex.id, name:ex.name};
    if (!rx.static) {
      if (S.format !== 'circuit') { o.sets = rx.sets; o.rest = rx.rest; }
      if (!ex.kind) o.reps = item.reps || (S.format === 'circuit' ? GOALS[S.goal].circ.reps : String(rx.reps));
      if (item.tempo) o.tempo = item.tempo;
    } else if (item.sets) o.sets = item.sets; /* статодинамика: число серий человек задаёт сам, остальное — метод */
    if (item.kg) o.kg = item.kg.length === 1 ? item.kg[0] : item.kg.slice();
    if (item.note) o.note = item.note;
    return o;
  });
}
function exportPlan(c) {
  const o = {name:c.name};
  for (const k of ['group', 'for', 'note']) if (c[k]) o[k] = c[k];
  for (const k of PLAN_KEYS) o[k] = c[k] || S.gen[k] || S[k];
  o.items = c.items.map(it => exportItem(c, it));
  return o;
}
function planFileObject(plans, from) {
  const o = {format:PLAN_FILE, version:PLAN_FILE_V, app:typeof window !== 'undefined' && window.PODHOD_VERSION || '', exported:new Date().toISOString().slice(0, 10)};
  if (from) o.from = from;
  o.plans = plans.map(exportPlan);
  return o;
}
/* имя файла латиницей: браузеры подменяют имя с кириллицей на «download» */
const TRANSLIT = {а:'a', б:'b', в:'v', г:'g', д:'d', е:'e', ё:'e', ж:'zh', з:'z', и:'i', й:'y', к:'k', л:'l', м:'m', н:'n', о:'o', п:'p', р:'r', с:'s', т:'t', у:'u', ф:'f', х:'h', ц:'ts', ч:'ch', ш:'sh', щ:'sch', ъ:'', ы:'y', ь:'', э:'e', ю:'yu', я:'ya'};
function planFileName(plans) {
  const slug = v => String(v).toLowerCase().replace(/[а-яё]/g, ch => TRANSLIT[ch] ?? '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'plan';
  const c = plans[0], group = plans.length > 1 && plans.every(p => p.group && p.group === c.group) ? c.group : null;
  return `lazy-gym-${plans.length > 1 ? (group ? 'program-' + slug(group) : 'plans') : 'plan-' + slug(c.name)}.json`;
}

/* ---------- чтение файла: только известные поля, разумные значения, понятные ошибки ---------- */
function readPlanFile(text) {
  if (typeof text !== 'string' || !text.trim()) return {error:'Файл пустой.'};
  if (text.length > PLAN_FILE_MAX) return {error:'Файл слишком большой для плана.'};
  let o; try { o = JSON.parse(text); } catch (e) { return {error:'Это не файл плана: текст не читается как JSON. Возможно, файл обрезан при пересылке.'}; }
  if (!o || typeof o !== 'object' || Array.isArray(o)) return {error:'Это не файл плана.'};
  if (o.v && (o.log || o.settings || o.body)) return {error:'Это резервная копия приложения, а не план. Её восстанавливают в разделе «Журнал».'};
  const raw = Array.isArray(o.plans) ? o.plans : Array.isArray(o.items) ? [o] : null;
  if (!raw || (o.format && o.format !== PLAN_FILE)) return {error:'Это не файл плана Lazy Gym Planner.'};
  const newer = Number(o.version) > PLAN_FILE_V;
  const from = cleanText(o.from, CUSTOM_TEXT), plans = [], unknown = [];
  for (const p of raw.slice(0, PLAN_FILE_PLANS)) {
    if (!p || typeof p !== 'object') continue;
    const items = Array.isArray(p.items) ? p.items : [];
    for (const it of items) if (it && !EXI[it.id]) unknown.push(cleanText(it.name, 60) || cleanText(String(it.id || ''), 30) || '?');
    const c = cleanPlan({...p, items:items.map(it => it && typeof it === 'object' ? {...it, sets:Number.isInteger(it.sets) ? it.sets : undefined, rest:Number.isInteger(it.rest) ? it.rest : undefined} : it)}, '');
    if (from && !c.from) c.from = from;
    plans.push(c);
  }
  if (!plans.length) return {error:'В файле нет планов.'};
  return {plans, from, note:cleanText(o.note, CUSTOM_NOTE, true), unknown:[...new Set(unknown)], newer, cut:raw.length > PLAN_FILE_PLANS};
}
/* добавление: всегда новыми планами, занятые имена получают «(2)» */
function addPlans(plans) {
  const taken = S.customs.map(c => c.name), added = [];
  for (const p of plans) { const c = {...p, id:newPlanId(), name:uniquePlanName(p.name, taken)}; taken.push(c.name); S.customs.push(c); added.push(c); }
  saveSettings(); return added;
}

/* ---------- окно выгрузки ---------- */
function planOutScope(scope) {
  const c = customOf();
  return scope === 'all' ? S.customs.filter(p => p.items.length) : scope === 'group' && c.group ? S.customs.filter(p => p.group === c.group) : [c];
}
function planOutHtml() {
  const c = customOf(), group = c.group ? S.customs.filter(p => p.group === c.group).length : 0, all = S.customs.filter(p => p.items.length).length;
  const radio = (v, label, on, dis) => `<label class="po-opt"><input type="radio" name="po-scope" value="${v}"${on ? ' checked' : ''}${dis ? ' disabled' : ''}><span>${label}</span></label>`;
  const share = typeof navigator !== 'undefined' && navigator.canShare && typeof File === 'function';
  return `<form method="dialog" class="gear po">
    <h2>Выгрузить план</h2>
    <p class="gear-hint">Файл .json откроется в Lazy Gym Planner на любом телефоне или компьютере: «Свой план» → «Загрузить план». Журнал и веса из журнала в файл не попадают.</p>
    <fieldset class="po-set"><legend>Что выгрузить</legend>
      ${radio('one', `Этот план: ${esc(c.name)}`, true)}
      ${group > 1 ? radio('group', `Всю программу (${esc(c.group)}): ${group} ${plural(group, 'план', 'плана', 'планов')}`) : ''}
      ${all > 1 ? radio('all', `Все свои планы: ${all}`) : ''}
    </fieldset>
    <div class="ics-grid">
      <label>Для кого<input id="po-for" type="text" maxlength="${CUSTOM_TEXT}" value="${esc(c.for || '')}" placeholder="Имя ученика" autocomplete="off"></label>
      <label>От кого<input id="po-from" type="text" maxlength="${CUSTOM_TEXT}" value="${esc(S.author || '')}" placeholder="Ваше имя" autocomplete="off"></label>
    </div>
    <p class="p-hint" id="po-msg" role="status"></p>
    <div class="gear-btns po-btns">
      <button type="button" class="btn btn-2" id="po-close">Закрыть</button>
      <button type="button" class="btn btn-2" id="po-copy">Скопировать текст</button>
      ${share ? '<button type="button" class="btn btn-2" id="po-share">Поделиться</button>' : ''}
      <button type="button" class="btn" id="po-save">Сохранить файл</button>
    </div>
  </form>`;
}
function openPlanOut() {
  let d = $('#plan-out');
  if (!d) { d = document.createElement('dialog'); d.id = 'plan-out'; d.className = 'gear-view'; d.setAttribute('aria-label', 'Выгрузить план'); document.body.appendChild(d); }
  d.innerHTML = planOutHtml(); d.showModal();
}
function planOutPayload() {
  const scope = (document.querySelector('input[name="po-scope"]:checked') || {}).value || 'one', plans = planOutScope(scope);
  const forWho = cleanText($('#po-for').value, CUSTOM_TEXT), from = cleanText($('#po-from').value, CUSTOM_TEXT);
  S.author = from;
  /* «для кого» остаётся в самих планах: при следующей выгрузке подставится */
  for (const p of plans) { if (forWho) p.for = forWho; else delete p.for; }
  saveSettings();
  const obj = planFileObject(plans, from);
  return {plans, text:JSON.stringify(obj, null, 1) + '\n', name:planFileName(plans)};
}
async function planOutAction(kind) {
  const msg = $('#po-msg'), {plans, text, name} = planOutPayload();
  if (!plans.length || plans.every(p => !p.items.length)) { msg.textContent = 'В плане нет упражнений — выгружать нечего.'; return; }
  if (kind === 'copy') {
    try { await navigator.clipboard.writeText(text); msg.textContent = 'Текст файла скопирован. Его можно вставить в «Загрузить план» на другом устройстве.'; }
    catch (e) { msg.innerHTML = 'Скопировать автоматически не удалось. Выделите текст:<textarea readonly rows="5"></textarea>'; const ta = msg.querySelector('textarea'); ta.value = text; ta.focus(); ta.select(); }
    return;
  }
  if (kind === 'share') {
    try {
      const file = new File([text], name, {type:'application/json'});
      if (!navigator.canShare({files:[file]})) throw new Error('no files');
      await navigator.share({files:[file], title:plans.length > 1 ? 'Планы тренировок' : plans[0].name});
      msg.textContent = 'Отправлено.';
    } catch (e) { msg.textContent = e && e.name === 'AbortError' ? 'Отправка отменена.' : 'Поделиться файлом не получилось — сохраните его и отправьте вручную.'; }
    return;
  }
  const r = await saveFile(name, text, 'application/json');
  msg.textContent = r === 'ok' ? `Файл сохранён: ${name}` : r === 'declined' ? 'Сохранение отменено.' : 'Сохранить файл не получилось.';
}

/* ---------- окно загрузки ---------- */
function planInHtml() {
  const r = planIn;
  let body = '';
  if (r && r.error) body = `<p class="warn">${esc(r.error)}</p>`;
  else if (r) {
    /* общая программа и адресат — один раз сверху; у плана — только то, что отличает его от соседей */
    const groups = [...new Set(r.plans.map(p => p.group || ''))], common = groups.length === 1 && groups[0];
    const meta = [common ? `<span>программа: <b>${esc(common)}</b></span>` : '', r.from ? `<span>от: <b>${esc(r.from)}</b></span>` : '', r.plans[0].for ? `<span>для: <b>${esc(r.plans[0].for)}</b></span>` : ''].join('');
    const setup = p => [GOALS[p.goal]?.name, FORMATS[p.format]?.name, LEVELS[p.level]?.name].filter(Boolean).join(', ').toLowerCase();
    body = `${meta ? `<p class="cp-sub pi-meta">${meta}</p>` : ''}${r.note ? `<p class="c-note">${esc(r.note)}</p>` : ''}
      ${r.newer ? '<p class="warn">Файл сделан в более новой версии приложения: то, что эта версия не знает, будет пропущено. Обновите приложение.</p>' : ''}
      ${r.unknown.length ? `<p class="warn">Этой версии приложения неизвестны упражнения: ${esc(r.unknown.join(', '))}. Они будут пропущены.</p>` : ''}
      ${r.cut ? `<p class="warn">В файле больше ${PLAN_FILE_PLANS} планов — загрузятся первые ${PLAN_FILE_PLANS}.</p>` : ''}
      <fieldset class="po-set"><legend>Планы в файле</legend>${r.plans.map((p, i) => `<label class="po-opt pi-plan"><input type="checkbox" data-pi="${i}" checked><span><b>${esc(p.name)}</b><small>${p.items.length} ${plural(p.items.length, 'упражнение', 'упражнения', 'упражнений')}${setup(p) ? ` — ${setup(p)}` : ''}</small>${!common && p.group ? `<small>программа: ${esc(p.group)}</small>` : ''}</span></label>`).join('')}</fieldset>`;
  }
  return `<form method="dialog" class="gear pi">
    <h2>Загрузить план</h2>
    <p class="gear-hint">Выберите файл .json, который выгрузили из Lazy Gym Planner, — свой или от тренера. Планы добавятся к вашим, ничего не перезапишется.</p>
    <label class="btn btn-2 pi-file" for="pi-file">Выбрать файл</label><input type="file" id="pi-file" accept=".json,application/json,text/plain" hidden>
    <details class="pi-paste"${r && r.pasted && r.error ? ' open' : ''}><summary>или вставить текст файла</summary><textarea id="pi-text" rows="4" placeholder='{"format": "lazy-gym-planner/plans", …}'></textarea><button type="button" class="btn btn-2" id="pi-read">Прочитать</button></details>
    ${body}
    <p class="p-hint" id="pi-msg" role="status"></p>
    <div class="gear-btns"><button type="button" class="btn btn-2" id="pi-close">Закрыть</button>${r && r.plans ? `<button type="button" class="btn" id="pi-add">Добавить в свои планы</button>` : ''}</div>
  </form>`;
}
function openPlanIn() {
  planIn = null;
  let d = $('#plan-in');
  if (!d) { d = document.createElement('dialog'); d.id = 'plan-in'; d.className = 'gear-view'; d.setAttribute('aria-label', 'Загрузить план'); document.body.appendChild(d); }
  d.innerHTML = planInHtml(); d.showModal();
}
function showPlanIn(result) { planIn = result; $('#plan-in').innerHTML = planInHtml(); const f = $('#pi-add') || $('#pi-close'); if (f) f.focus(); }

document.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t) return;
  if (t.id === 'plan-export') { openPlanOut(); return; }
  if (t.id === 'po-close') { $('#plan-out').close(); return; }
  if (t.id === 'po-save') { planOutAction('save'); return; }
  if (t.id === 'po-share') { planOutAction('share'); return; }
  if (t.id === 'po-copy') { planOutAction('copy'); return; }
  if (t.dataset.cpImport !== undefined) { openPlanIn(); return; }
  if (t.id === 'pi-close') { $('#plan-in').close(); return; }
  if (t.id === 'pi-read') { showPlanIn({...readPlanFile($('#pi-text').value), pasted:true}); return; }
  if (t.id === 'pi-add') {
    const pick = [...document.querySelectorAll('[data-pi]')].filter(x => x.checked).map(x => planIn.plans[+x.dataset.pi]);
    if (!pick.length) { $('#pi-msg').textContent = 'Отметьте хотя бы один план.'; return; }
    const added = addPlans(pick); $('#plan-in').close(); planIn = null;
    openCustom(added[0].id); regen(); window.scrollTo({top:0});
    return;
  }
});
document.addEventListener('change', e => {
  if (e.target.id !== 'pi-file') return;
  const f = e.target.files && e.target.files[0]; if (!f) return;
  if (f.size > PLAN_FILE_MAX) { showPlanIn({error:'Файл слишком большой для плана.'}); return; }
  const rd = new FileReader();
  rd.onload = () => showPlanIn(readPlanFile(String(rd.result || '')));
  rd.onerror = () => showPlanIn({error:'Файл не читается.'});
  rd.readAsText(f);
});

/* ===================== СВОРАЧИВАНИЕ БЛОКОВ =====================
   Объёмные блоки сворачиваются в строку-сводку, из которой видно главное:
   • параметры (на телефоне и планшете — на компьютере они в боковой колонке и не мешают);
   • нагрузка по мышцам в шапке плана;
   • в карточке упражнения — мышцы и таблица записи подходов (подсказка по весу остаётся на виду).
   «Подробно / Компактно» над карточками задаёт, как они открываются; отдельную карточку можно развернуть или
   свернуть — это помнится до перезагрузки страницы. Параметры, нагрузка и вид карточек сохраняются в настройках. */
const FOLD_CARDS = ['compact', 'full'];
function ensureFold(s) {
  const f = s.fold && typeof s.fold === 'object' ? s.fold : {};
  s.fold = {setup:f.setup === true, load:f.load === true, cards:FOLD_CARDS.includes(f.cards) ? f.cards : 'compact', gentle:f.gentle === true};
  return s.fold;
}
ensureFold(S);
/* После первого плана параметры на телефоне и планшете свёрнуты: при каждом следующем запуске на первом экране —
   план, а не два с половиной экрана параметров (выбранное видно строкой, нажатие ведёт к полю). Самый первый
   запуск — план ещё не показывался — открывается с раскрытыми параметрами. На компьютере параметры в боковой колонке. */
const PLAN_SEEN = 'podhod.planSeen.v1';
(() => {
  let seen = false;
  try { seen = !!(localStorage.getItem(PLAN_SEEN) || localStorage.getItem(STORE)); localStorage.setItem(PLAN_SEEN, '1'); } catch (e) {}
  if (seen && typeof matchMedia === 'function' && matchMedia('(max-width:959px)').matches) S.fold.setup = true;
})();
const FOLD_GROUPS = ['mus', 'log'];
const cardFold = new Map(); /* «группа:упражнение» → раскрыт ли блок в этой карточке, если человек менял его сам */
function cardOpen(g, id) { const k = g + ':' + id; return cardFold.has(k) ? cardFold.get(k) : ensureFold(S).cards === 'full'; }
function cardFoldClass(id) { return FOLD_GROUPS.filter(g => cardOpen(g, id)).map(g => ' open-' + g).join(''); }
const lowFirst = s => s ? s.charAt(0).toLowerCase() + s.slice(1) : s;
const chev = '<i class="cg-chev" aria-hidden="true"></i>';

/* ---------- карточка: мышцы и запись подходов ---------- */
function musFoldHead(ex) {
  const open = cardOpen('mus', ex.id), list = ms => ms.map((m, i) => i ? lowFirst(MUSCLE_NAMES[m]) : MUSCLE_NAMES[m]).join(', ');
  return `<button type="button" class="cg-h" data-cfold="mus" aria-expanded="${open}"><span class="cg-x"><span class="cg-t">Мышцы</span><span class="cg-s cg-mus"><span class="cg-p">${list(ex.pri)}</span>${ex.sec.length ? `<span class="cg-sec">${list(ex.sec)}</span>` : ''}</span></span>${chev}</button>`;
}
function logFoldBar(it, n, done) {
  const id = it.ex.id, open = cardOpen('log', id), cnt = histCount(id);
  return `<div class="lt-bar"><button type="button" class="cg-h lt-tog" data-cfold="log" aria-expanded="${open}" aria-controls="lt-${id}"><span class="cg-x"><span class="cg-t">Подходы</span><span class="cg-s${done ? ' cg-done' : ''}">${logBarText(done, n)}</span></span>${chev}</button>
    <button type="button" class="btn-ghost" data-hist="1" aria-expanded="false">${ICON.chart}<span>История</span><small>${cnt || ''}</small></button></div>`;
}
function logBarText(done, n) { return `${done} из ${n}`; }
/* отметили или сняли подход — счётчик в заголовке записи */
function logBarUpdate(card) {
  const s = card && card.querySelector('.lt-tog .cg-s'); if (!s) return;
  const done = card.querySelectorAll('.lt-r.done').length;
  s.textContent = logBarText(done, card.querySelectorAll('.lt-r').length); s.classList.toggle('cg-done', done > 0);
}
/* после перерисовки записи: кнопка «История» знает, открыта ли история */
function syncCardLog(card) {
  const h = card.querySelector('.c-hist'), hb = card.querySelector('[data-hist]');
  if (h && hb) hb.setAttribute('aria-expanded', String(!h.hidden));
}
function setCardsView(v) {
  ensureFold(S).cards = v; cardFold.clear(); saveSettings();
  document.querySelectorAll('.card[data-ex]').forEach(card => {
    for (const g of FOLD_GROUPS) {
      const open = cardOpen(g, card.dataset.ex);
      card.classList.toggle('open-' + g, open);
      card.querySelectorAll(`[data-cfold="${g}"]`).forEach(b => b.setAttribute('aria-expanded', String(open)));
    }
  });
  document.querySelectorAll('[data-cards]').forEach(b => { const on = b.dataset.cards === v; b.classList.toggle('on', on); b.setAttribute('aria-pressed', String(on)); });
}
function cardsViewHtml() {
  const v = ensureFold(S).cards, b = (k, label) => `<button type="button" data-cards="${k}" class="${v === k ? 'on' : ''}" aria-pressed="${v === k}">${label}</button>`;
  return `<div class="fold-bar"><span>Карточки</span><div class="fold-seg" role="group" aria-label="Вид карточек">${b('compact', 'Компактно')}${b('full', 'Подробно')}</div></div>`;
}

/* ---------- шапка плана: нагрузка по мышцам ---------- */
function loadFoldHead(title, top) {
  const open = !ensureFold(S).load;
  return `<button type="button" class="cg-h lb-h" data-lfold="1" aria-expanded="${open}"><span class="cg-x"><span class="cg-t">${title}</span><span class="cg-s">${top}</span></span>${chev}</button>`;
}
function loadTop(rows) { return rows.slice(0, 3).map(([n, v], i) => `${i ? lowFirst(n) : n} ${fmtNum(v)}`).join(', '); }

/* ---------- параметры на телефоне ---------- */
function setupSummary() {
  const out = [];
  const go = (sel, text) => out.push(`<button type="button" class="sb-chip" data-sgo="${sel}">${esc(text)}</button>`);
  if (S.mode === 'program') { go('#f-mode', 'Программа на неделю'); go('#f-prog', `${S.days} ${plural(S.days, 'тренировка', 'тренировки', 'тренировок')} · ${SPLITS[splitFor(S.days)].name}`); }
  else if (S.mode === 'custom') { go('#f-mode', 'Свой план'); go('#f-custom', customOf().name); }
  else go('#f-mode', 'Тренировка на день');
  go('#f-goal', `${GOALS[S.goal].name} · ${FORMATS[S.format].name.toLowerCase()} · ${LEVELS[S.level].name.toLowerCase()}`);
  if (S.mode === 'single') { go('#count-l', `${S.count} ${plural(S.count, 'упражнение', 'упражнения', 'упражнений')}`); go('#f-muscles', S.groups.length ? titleFor() : 'Мышцы не выбраны'); }
  if (typeof PROTECT_BY !== 'undefined' && S.protect && S.protect.length) go('#f-joints', 'Бережём ' + hitsText(S.protect.map(id => PROTECT_BY[id])));
  go('#e-places', placeOf().name);
  return out.join('');
}
function setupBarHtml() {
  const folded = ensureFold(S).setup;
  return `<div class="sb-head"><h2 class="lbl">Параметры</h2><button type="button" class="sb-tog" data-sfold="1" aria-expanded="${!folded}">${folded ? 'Развернуть' : 'Свернуть'}${chev}</button></div>${folded ? `<div class="sb-chips">${setupSummary()}</div>` : ''}`;
}
function renderSetupFold() {
  const folded = ensureFold(S).setup, bar = $('#setup-bar');
  $('.setup').classList.toggle('folded', folded);
  if (bar) bar.innerHTML = setupBarHtml();
}
function setSetupFold(folded, from) {
  ensureFold(S).setup = folded; saveSettings(); renderSetupFold();
  /* свернули снизу — возвращаемся к сводке, иначе план «уезжает» вверх */
  if (folded && from === 'end') { const bar = $('#setup-bar'); if (bar && bar.getBoundingClientRect().top < 0) bar.scrollIntoView({block:'start'}); }
}

document.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t) return;
  if (t.dataset.cfold) {
    const card = t.closest('.card'), g = t.dataset.cfold, id = card.dataset.ex, open = !card.classList.contains('open-' + g);
    cardFold.set(g + ':' + id, open); card.classList.toggle('open-' + g, open);
    card.querySelectorAll(`[data-cfold="${g}"]`).forEach(b => b.setAttribute('aria-expanded', String(open)));
    return;
  }
  if (t.dataset.cards) { setCardsView(t.dataset.cards); return; }
  if (t.dataset.lfold) {
    const folded = !ensureFold(S).load; S.fold.load = folded; saveSettings();
    const fig = t.closest('.p-load'); if (fig) fig.classList.toggle('folded', folded);
    const head = t.closest('.p-head'); if (head) head.classList.toggle('load-folded', folded);
    t.setAttribute('aria-expanded', String(!folded));
    return;
  }
  if (t.dataset.sfold) { setSetupFold(!ensureFold(S).setup, t.id === 'setup-fold-end' ? 'end' : 'top'); return; }
  if (t.dataset.sgo) {
    setSetupFold(false);
    const n = $(t.dataset.sgo), f = n && (n.closest('.field') || n);
    if (f) { f.scrollIntoView({block:'start'}); const b = f.querySelector('button, input, select'); if (b) b.focus({preventScroll:true}); }
  }
});

/* ===================== БЕРЕЖНЫЙ РЕЖИМ =====================
   Две независимые настройки:
   • «Беречь суставы» (S.protect) — с любой целью: упражнения с пиковой нагрузкой на отмеченные суставы не
     подбираются, в своём плане и при переносе программы заменяются похожими без неё. Пиковая нагрузка — те же
     правила, что красные метки на манекене (09f-joint-stress.js); пороги здесь не меняются.
   • Цель «Бережно» (GOALS.gentle) — для тех, у кого болят суставы или идёт восстановление: 12–15 повторов лёгким
     весом с запасом 3–4 повтора, медленно; без прыжков, рывковых и сложных (третьего уровня) упражнений;
     при подборе предпочтение упражнениям без пиковой нагрузки на суставы.
     Основание дозировки: Garber C.E. et al. ACSM Position Stand, MSSE 2011, 43(7):1334–1359 — 10–15 повторов
     и 40–50% от 1ПМ для начинающих и старших, 60–70% для новичков; одна-две серии.
   • Правило боли — модель контроля боли: Silbernagel K.G., Thomeé R. et al., Am J Sports Med 2007, 35(6):897–906:
     боль во время нагрузки до 5 из 10, к утру проходит, от недели к неделе не нарастает. */
/* acc — «нагрузка на что»: шею, поясницу, заднюю поверхность бедра */
const PROTECT = [
  {id:'neck', name:'Шея', acc:'шею', part:'шея'},
  {id:'shoulders', name:'Плечи', acc:'плечи', part:'плечи'},
  {id:'elbows', name:'Локти', acc:'локти', part:'локти'},
  {id:'wrists', name:'Запястья', acc:'запястья', part:'запястья'},
  {id:'lumbar', name:'Поясница', acc:'поясницу', part:'поясница'},
  {id:'knees', name:'Колени', acc:'колени', part:'колени'},
  {id:'achilles', name:'Ахилловы сухожилия', acc:'ахилловы сухожилия', part:'ахилловы сухожилия'},
  {id:'hams', name:'Задняя поверхность бедра', acc:'заднюю поверхность бедра', part:'задняя поверхность бедра'}
].map(p => ({...p, rules:STRESS_RULES.filter(r => r.parts.includes(p.part)).map(r => r.id)}));
const PROTECT_BY = Object.fromEntries(PROTECT.map(p => [p.id, p]));
/* ударные и рывковые движения: пиковая нагрузка на суставы в несколько раз больше веса тела */
const GENTLE_SKIP_PATTERNS = new Set(['jump', 'burpee', 'climb']), GENTLE_SKIP = new Set(['kbswing']);

function ensureProtect(s) {
  s.protect = Array.isArray(s.protect) ? PROTECT.map(p => p.id).filter(id => s.protect.includes(id)) : [];
  return s.protect;
}
ensureProtect(S);

/* ---------- какие суставы нагружает упражнение: считается по 41 положению манекена один раз за сборку ---------- */
const STRESS_IDS = new Map(), STRESS_IDS_KEY = 'podhod.stress.v1';
let stressIdsLoaded = false, stressIdsSave = 0;
function stressIdsBuild() { return typeof window !== 'undefined' && window.PODHOD_BUILD || null; }
function stressIdsOf(ex) {
  if (!stressIdsLoaded) {
    stressIdsLoaded = true;
    try {
      const saved = JSON.parse(localStorage.getItem(STRESS_IDS_KEY) || 'null');
      if (saved && saved.build && saved.build === stressIdsBuild())
        for (const [id, v] of Object.entries(saved.ids || {})) if (EXI[id] && Array.isArray(v) && v.every(r => STRESS_RULE[r])) STRESS_IDS.set(id, v);
    } catch (e) {}
  }
  let v = STRESS_IDS.get(ex.id);
  if (!v) { v = jointStress(ex).rules.map(r => r.id); STRESS_IDS.set(ex.id, v); stressIdsSchedule(); }
  return v;
}
function stressIdsSchedule() {
  if (!stressIdsBuild() || stressIdsSave) return;
  stressIdsSave = setTimeout(() => {
    stressIdsSave = 0;
    try { localStorage.setItem(STRESS_IDS_KEY, JSON.stringify({build:stressIdsBuild(), ids:Object.fromEntries(STRESS_IDS)})); } catch (e) {}
  }, 1500);
}
/* досчитать заранее, в простое: тогда переключение суставов и цели не ждёт расчёта */
function prefetchStressIds() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  const queue = EX.filter(ex => !STRESS_IDS.has(ex.id));
  const idle = window.requestIdleCallback ? cb => requestIdleCallback(cb, {timeout:1500}) : cb => setTimeout(() => { const end = performance.now() + 8; cb({timeRemaining:() => Math.max(0, end - performance.now())}); }, 60);
  const work = deadline => {
    do { const ex = queue.shift(); if (!ex) return; try { stressIdsOf(ex); } catch (e) {} } while (deadline.timeRemaining() > 10);
    idle(work);
  };
  idle(work);
}

/* ---------- подходит ли упражнение при выбранных суставах и цели ---------- */
function protectRules() { const set = new Set(); for (const id of ensureProtect(S)) for (const r of PROTECT_BY[id].rules) set.add(r); return set; }
function protectHits(ex) {
  if (!ensureProtect(S).length) return [];
  const ids = stressIdsOf(ex);
  return S.protect.map(id => PROTECT_BY[id]).filter(p => p.rules.some(r => ids.includes(r)));
}
function jointOk(ex) { return !protectHits(ex).length; }
function gentleOk(ex) { return S.goal !== 'gentle' || (ex.lvl <= 2 && !GENTLE_SKIP.has(ex.id) && !GENTLE_SKIP_PATTERNS.has(PATTERN[ex.id])); }
function fitsBody(ex) { return gentleOk(ex) && jointOk(ex); }
const joinNames = list => list.length > 1 ? list.slice(0, -1).join(', ') + ' и ' + list[list.length - 1] : list[0] || '';
function hitsText(hits) { return joinNames(hits.map(p => p.acc)); }
/* почему упражнение не подходит — для замены и для списка «нечем заменить» */
function unfitWhy(ex) {
  const hits = protectHits(ex);
  if (hits.length) return `нагружает ${hitsText(hits)}`;
  if (!gentleOk(ex)) return ex.lvl > 2 ? 'сложный вариант' : 'ударная или рывковая нагрузка';
  return '';
}

/* пометка в списках атласа и «Добавить упражнение»: чем упражнение не подходит бережному режиму */
function unfitHtml(ex, willSwap = false) {
  const why = unfitWhy(ex);
  return why ? ` · <span class="unfit">${esc(why)}${willSwap ? ' — в плане будет замена' : ''}</span>` : '';
}
/* что не вошло в свой план или перенесённую программу и почему */
function lostMessages(lost, E) {
  const eq = lost.filter(ex => !available(ex, E)), body = lost.filter(ex => available(ex, E)), out = [];
  if (eq.length) out.push(`Здесь нечем выполнить и нечем заменить: ${eq.map(ex => ex.name).join(', ')}. В другом месте ${eq.length > 1 ? 'они вернутся' : 'оно вернётся'} в план.`);
  if (body.length) out.push(`${body.length > 1 ? 'Бережный режим: нечем заменить, в план не вошли' : 'Бережный режим: нечем заменить, в план не вошло'}: ${body.map(ex => `${ex.name} (${unfitWhy(ex)})`).join(', ')}.`);
  return out;
}

/* ---------- настройки: «Беречь суставы» ---------- */
function renderProtect() {
  const on = new Set(ensureProtect(S));
  $('#j-chips').innerHTML = PROTECT.map(p => `<button type="button" class="chip${on.has(p.id) ? ' on' : ''}" data-protect="${p.id}" aria-pressed="${on.has(p.id)}">${ICON.check}<span>${p.name}</span></button>`).join('');
  $('#j-note').textContent = on.size
    ? `Упражнения с пиковой нагрузкой на ${hitsText(S.protect.map(id => PROTECT_BY[id]))} не подбираются, в своём плане заменяются похожими.`
    : 'Отметьте суставы, которые болят или восстанавливаются: план обойдёт упражнения с пиковой нагрузкой на них — по тем же правилам, что красные метки на манекене.';
}

/* ---------- плашка в плане: дозировка, правило боли, когда к врачу ---------- */
function gentleHtml() {
  const gentle = S.goal === 'gentle', prot = ensureProtect(S).map(id => PROTECT_BY[id]);
  if (!gentle && !prot.length) return '';
  const lead = gentle
    ? `<p><b>Бережно.</b> 12–15 повторов лёгким весом, 3–4 в запасе, медленно и без рывков. Прыжки, рывковые и сложные упражнения не подбираются.${prot.length ? ` Без пиковой нагрузки на ${hitsText(prot)}.` : ''}</p>`
    : `<p><b>Без пиковой нагрузки на ${hitsText(prot)}.</b> Такие упражнения не подбираются, а в своём плане заменяются похожими.</p>`;
  return `<details class="gentle-box"${ensureFold(S).gentle ? '' : ' open'}><summary>Бережный режим: правило боли</summary>${lead}
    <p><b>Боль во время упражнения</b> по шкале от 0 до 10: до 2 — продолжайте; 3–5 — можно, если к утру боль проходит и от недели к неделе не нарастает; больше 5 — остановитесь, уменьшите вес или амплитуду либо замените упражнение.</p>
    <p class="gentle-warn">Не заменяет врача. Острая боль, отёк, онемение, ощущение нестабильности сустава, недавняя травма или операция — сначала к врачу или реабилитологу.</p></details>`;
}

document.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t || !t.dataset.protect) return;
  const id = t.dataset.protect; if (!PROTECT_BY[id]) return;
  S.protect = S.protect.includes(id) ? S.protect.filter(x => x !== id) : S.protect.concat(id);
  ensureProtect(S); regen();
});
document.addEventListener('toggle', e => {
  if (!e.target.classList || !e.target.classList.contains('gentle-box')) return;
  ensureFold(S).gentle = !e.target.open; saveSettings();
}, true);

/* ===================== ХВАТЫ И ПОСТАНОВКА РУК И СТОП =====================
   Один снаряд — разные хваты: подтягивания прямым и обратным хватом; верхний блок широким хватом, V-рукоятью
   и обратным хватом; горизонтальный блок V-рукоятью и широким хватом; жим лёжа обычным и узким; сгибания
   с супинацией и «молотом»; разгибания и сгибания на блоке прямой рукоятью и канатом; отжимания с обычной,
   широкой и узкой постановкой рук; жим ногами со стопами посередине, выше и ниже на платформе; копенгагенская планка
   с опорой голеностопом и коленом (короткий рычаг — облегчённый вариант; новичку и в бережном режиме
   предлагается только он: опора голеностопом — третий уровень сложности). Для человека
   это одна карточка с переключателем; внутри каждый хват — своё упражнение каталога: своя поза манекена,
   свои мышцы, свои метки нагрузки на суставы и свой вес в журнале (узким хватом обычно поднимают иначе,
   и подсказки «прибавьте» не смешиваются). Переключение меняет упражнение в той же карточке: место в плане и,
   в своём плане, дозировка сохраняются. В семью входят только упражнения на одном и том же инвентаре. */
const VARIANT_FAMILIES = [
  {id:'pullbar', what:'Хват', items:[['pullup', 'Прямой'], ['chinup', 'Обратный']]},
  {id:'latpull', what:'Хват', items:[['latpull', 'Широкий'], ['latpullv', 'V-рукоять'], ['latpulluh', 'Обратный']]},
  {id:'cablerow', what:'Хват', items:[['cablerow', 'V-рукоять'], ['cablerowwide', 'Широкий']]},
  {id:'bench', what:'Хват', items:[['bbbench', 'Обычный'], ['closegrip', 'Узкий']]},
  {id:'dbcurl', what:'Хват', items:[['dbcurl', 'Ладони вверх'], ['hammer', 'Молот']]},
  {id:'pushdown', what:'Рукоять', items:[['pushdown', 'Прямая'], ['ropepushdown', 'Канат']]},
  {id:'cablecurl', what:'Рукоять', items:[['cablecurl', 'Прямая'], ['ropecurl', 'Канат']]},
  {id:'legpress', what:'Постановка стоп', items:[['legpress', 'Обычно'], ['legpresshigh', 'Высоко'], ['legpresslow', 'Низко']]},
  {id:'pushup', what:'Постановка рук', items:[['pushup', 'Обычно'], ['widepush', 'Широко'], ['diamond', 'Узко']]},
  {id:'copenhagen', what:'Опора', items:[['copenhagen', 'Голеностоп'], ['copenhagenknee', 'Колено']]}
];
const VARIANT_OF = Object.fromEntries(VARIANT_FAMILIES.flatMap(f => f.items.map(([id, label]) => [id, {family:f, label}])));

/* хваты, которые можно выбрать здесь и сейчас: есть инвентарь, по уровню, не нагружают бережёмые суставы */
function variantsFor(ex, E, taken = new Set()) {
  const v = VARIANT_OF[ex.id]; if (!v) return [];
  const lvlMax = S.level === 'beg' || S.goal === 'gentle' ? 2 : 3;
  const list = v.family.items.map(([id, label]) => ({ex:EXI[id], label}))
    .filter(x => x.ex && (x.ex === ex || (!taken.has(x.ex.id) && available(x.ex, E) && x.ex.lvl <= lvlMax && fitsBody(x.ex) && (S.format !== 'static' || staticOk(x.ex)))));
  return list.length > 1 ? list : [];
}
/* хват, который уже стоит в другой карточке плана, не предлагается: два одинаковых упражнения в плане не нужны */
function variantTaken() {
  const ids = new Set(plan && plan.items ? plan.items.map(x => x.ex.id) : []);
  if (S.mode === 'custom') for (const x of customOf().items) ids.add(x.id);
  return ids;
}
function variantRowHtml(it, E = plan && plan.E || effEquip(S.equip)) {
  const list = variantsFor(it.ex, E, variantTaken()); if (!list.length) return '';
  const what = VARIANT_OF[it.ex.id].family.what;
  return `<div class="c-var" role="group" aria-label="${what}"><span>${what}:</span>${list.map(x => {
    const on = x.ex === it.ex;
    return `<button type="button" class="${on ? 'on' : ''}" data-variant="${x.ex.id}" data-slot="${it.slot}" aria-pressed="${on}"${on ? '' : ` title="${esc(x.ex.name)}"`}>${esc(x.label)}</button>`;
  }).join('')}</div>`;
}
/* в истории упражнения — что записано другими хватами той же семьи */
function variantHistNote(ex) {
  const v = VARIANT_OF[ex.id]; if (!v) return '';
  const rows = v.family.items.filter(([id]) => id !== ex.id).map(([id, label]) => {
    const ss = (LOG.data[id] || []).filter(x => x.s.some(Boolean)); if (!ss.length) return '';
    const last = ss[ss.length - 1];
    return `<li><b>${esc(label)}</b> · ${ss.length} ${plural(ss.length, 'запись', 'записи', 'записей')}, последняя ${fmtDay(last.d, true)}: ${setsText(last.s, EXI[id])}</li>`;
  }).filter(Boolean);
  return rows.length ? `<div class="h-var"><p class="h-cap">Другие хваты — ведутся отдельно</p><ul>${rows.join('')}</ul></div>` : '';
}

document.addEventListener('click', e => {
  const t = e.target.closest('button[data-variant]'); if (!t || !plan || !plan.items) return;
  const slot = +t.dataset.slot, it = plan.items.find(x => x.slot === slot), next = EXI[t.dataset.variant];
  if (!it || !next || it.ex === next) return;
  /* в своём плане хват записывается в сам план (подходы, вес и заметка остаются); в собранном — как замена */
  if (S.mode === 'custom') { const item = customOf().items[slot]; if (!item || customOf().items.some(x => x.id === next.id)) return; item.id = next.id; saveSettings(); }
  else { const k = swapKey(); swaps[k] = swaps[k] || {}; swaps[k][slot] = next.id; saveSettings(); }
  done = {}; renderPlan();
  const card = document.querySelector(`.card[data-slot="${slot}"]`), b = card && card.querySelector(`[data-variant="${next.id}"]`);
  if (b) b.focus({preventScroll:true});
});

/* ---------- Проигрыватель движений: карточки и увеличенный разбор ---------- */
let figs = [], rafId = 0, io = null;
const reduceMotion = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const motionPrefs = (() => {try {return Object.assign({speed:.5,joints:true,trace:false,vectors:false,muscles:true,view:'anatomy'},JSON.parse(localStorage.getItem('podhod.motion.v2') || '{}'));}catch(e){return {speed:.5,joints:true,trace:false,vectors:false,muscles:true,view:'anatomy'};}})();
/* с 4.29.0 векторы движения по умолчанию выключены (мешали разглядывать технику); сохранённое «включено» прежних версий
   было значением по умолчанию — выключаем один раз, дальше выбор человека запоминается как раньше */
if (motionPrefs.vectorsV !== 2) { motionPrefs.vectors = false; motionPrefs.vectorsV = 2; try { localStorage.setItem('podhod.motion.v2', JSON.stringify(motionPrefs)); } catch (e) {} }
if (![.25,.5,1].includes(+motionPrefs.speed)) motionPrefs.speed = .5;
if(typeof motionPrefs.muscles!=='boolean')motionPrefs.muscles=true;
if(typeof motionPrefs.stress!=='boolean')motionPrefs.stress=true;
/* с 4.30.0 основной вид разбора — «Анатомия» (кости и мышцы в почти невидимом силуэте); прежние флажки «Скелет» и
   «Анатомия мышц» заменены выбором вида — один раз ставим анатомию, дальше выбор человека запоминается */
if (motionPrefs.viewV !== 1) { motionPrefs.view = 'anatomy'; motionPrefs.viewV = 1; delete motionPrefs.skeleton; delete motionPrefs.anatomy; try { localStorage.setItem('podhod.motion.v2', JSON.stringify(motionPrefs)); } catch (e) {} }
let detailMotion = null, detailReturn = null, lastMotionNow = null;
function saveMotionPrefs() {try {localStorage.setItem('podhod.motion.v2',JSON.stringify(motionPrefs));}catch(e){}}
function motionDurations(it) {
  const a = it.ex.anim;
  if (a.timing) return a.timing.map(x=>x*1000);
  if (a.hold) return [3000,0,3000,0];
  if (a.period || it.ex.kind || it.ex.g === 'cardio') {const p = a.period || 3200;return [p*.45,p*.05,p*.45,p*.05];}
  const parsed = String(it.rx.tempo || '3-0-1-0').split('-').map(x=>x==='X'?.6:Number(x));
  const q = parsed.length===4 && parsed.every(Number.isFinite) ? parsed : [3,0,1,0];
  return (a.eccFirst ? q : [q[2],q[3],q[0],q[1]]).map(x=>Math.max(0,x)*1000);
}
function motionFrame(F, clock=F.clock) {
  const d = F.durations, total = d.reduce((a,b)=>a+b,0) || 4000;
  let x = ((clock%total)+total)%total, index = 0;
  while (index<3 && x>=d[index]) {x-=d[index];index++;}
  const q = d[index] ? Math.min(1,x/d[index]) : 0;
  const eased = .5-.5*Math.cos(Math.PI*q);
  let t = index===0 ? eased : index===1 ? 1 : index===2 ? 1-eased : 0;
  if (F.it.ex.anim.hold) t=0;
  /* замкнутый цикл (педали, бег, «велосипед»): фаза идёт по кругу без возврата назад */
  if (F.it.ex.anim.loop) {const p=((clock%total)+total)%total/total;t=p;index=p<.5?0:2;}
  /* статодинамика: только рабочая часть амплитуды, без выпрямления и без провала */
  const part=F.it.rx&&F.it.rx.partial;if(part&&!F.it.ex.anim.loop&&!F.it.ex.anim.hold)t=part[0]+(part[1]-part[0])*t;
  const a = F.it.ex.anim;
  let labels = a.eccFirst ? ['Опускание','Нижняя точка','Подъём','Верхняя точка'] : ['Рабочая фаза','Конечная точка','Возврат','Исходное положение'];
  if (F.it.ex.id === 'kbswing') labels=['Мах вперёд','Верхняя точка','Замах назад','Исходное положение'];
  if (F.it.ex.id === 'deadlift') labels=['Подъём','Верхняя точка','Опускание','Исходное положение'];
  return {t,index,label:a.hold?'Удержание':labels[index],cue:a.hold?a.cues[0]:a.cues[(index<2)!==!!a.eccFirst?0:1],progress:((clock%total)+total)%total/total,total};
}
/* Часы рисунка карточки — по сетке ≈30 кадров в секунду, целое число кадров на повторение: каждый круг проходит те же
   фазы, и готовые кадры берутся из памяти (FIGURE_FRAMES, 07-rigs-core.js). Кадр отстаёт от точного времени
   не больше чем на полкадра (≤17 мс); сами часы идут без округления. */
const CARD_GRID_MS=1000/30;
function cardClock(F){
  const total=F.durations.reduce((a,b)=>a+b,0)||4000,n=Math.max(1,Math.round(total/CARD_GRID_MS)),step=total/n;
  return (((Math.round(F.clock/step))%n)+n)%n*step;
}
function paintMotion(F, detailed=false) {
  const m = motionFrame(F, detailed ? F.clock : cardClock(F)); F.f.at(m.t,m);if(F.extra)F.extra.at(m.t,m);
  if (!detailed) {
    const cap = F.btn.closest('.motion-tile').querySelector('.motion-caption');
    if (cap && cap.textContent!==m.label) cap.textContent=m.label;
    return;
  }
  $('#mv-phase').textContent=m.label; $('#mv-cue').textContent=m.cue;
  $('#mv-progress').value=String(Math.round(m.progress*1000));
  $('#mv-progress').setAttribute('aria-valuetext',`${m.label}, ${Math.round(m.progress*100)}% повторения`);
  $('#mv-play').textContent=F.paused?'Воспроизвести':'Пауза';
  $('#mv-play').setAttribute('aria-label',F.paused?'Воспроизвести движение':'Приостановить движение');
  $('#mv-play').setAttribute('aria-pressed',String(!F.paused));
  $('#mv-position').textContent=`${Math.round(m.progress*100)}% повторения`;
  paintMusclePanel('mv',F,m);paintStressPanel('mv',F,m);
}
function configureMusclePanel(prefix,it){
 const profile=motionProfile(it.ex.anim),toggle=$('#'+prefix+'-muscle-toggle'),panel=$('#'+prefix+'-muscle-panel');
 toggle.checked=!!profile&&!!motionPrefs.muscles;toggle.disabled=!profile;
 $('#'+prefix+'-muscle-availability').hidden=!!profile;
 panel.hidden=!profile||!motionPrefs.muscles;
 if(!profile){$('#'+prefix+'-muscle-list').replaceChildren();return;}
 const rows=[];
 for(const[id,m]of Object.entries(profile.muscles)){
  rows.push(`<li data-muscle-row="${id}"><span class="muscle-swatch" aria-hidden="true"></span><span class="muscle-row-copy"><strong>${esc(MUSCLE_NAMES[id])}</strong><span>${MUSCLE_ROLES[m.role]}</span></span><span class="muscle-level"></span></li>`);
  for(const[key,r]of Object.entries(profile.regions||{}).filter(([,r])=>r.parent===id&&r.id!==id)){
   if(key===id)continue;
   rows.push(`<li class="muscle-region-row" data-muscle-row="${key}" data-deep="${!r.visible}"><span class="muscle-swatch" aria-hidden="true"></span><span class="muscle-row-copy"><span>${esc(r.label)}</span><small>${r.profileBasis==='shared-group'?'Общий профиль группы':'Учебный региональный акцент'}</small></span><span class="muscle-level"></span></li>`);
  }
 }
 $('#'+prefix+'-muscle-list').innerHTML=rows.join('');
 const region=$('#'+prefix+'-region');region.innerHTML='<option value="all">Все области</option>'+Object.entries(profile.regions||{}).filter(([,r])=>r.visible).map(([id,r])=>`<option value="${id}">${esc(r.label)}</option>`).join('');
 const saved=motionPrefs.regions?.[it.ex.id]||'all';region.value=profile.regions?.[saved]?.visible?saved:'all';
 const F=prefix==='mv'?detailMotion:workout?.motion;for(const f of [F?.f,F?.extra].filter(Boolean))f.setRegion?.(region.value);
}
function paintMusclePanel(prefix,F,m){
 const panel=$('#'+prefix+'-muscle-panel');if(panel.hidden)return;
 const state=muscleFrame(F.it.ex.anim,m.t,m.index);if(!state)return;
 const note=$('#'+prefix+'-muscle-note');if(note.textContent!==state.note)note.textContent=state.note;
 for(const row of panel.querySelectorAll('[data-muscle-row]')){
  const v=state.values[row.dataset.muscleRow],level=row.querySelector('.muscle-level'),text=row.dataset.deep==='true'?'Глубже':MUSCLE_BANDS[muscleBand(v)];
  row.querySelector('.muscle-swatch').style.backgroundColor=muscleColor(v);
  if(level.textContent!==text)level.textContent=text;
 }
}
/* ---------- нагрузка на суставы: панель с подсказками и красные отрезки шкалы повторения ---------- */
function stressTrack(F){
 const ex=F.it.ex;if(!jointStress(ex).rules.length)return '';
 const N=160,total=F.durations.reduce((a,b)=>a+b,0)||4000,on=[];
 for(let i=0;i<=N;i++){const m=motionFrame({...F,clock:i/N*total*.9999});on.push(jointStressAt(ex,m.t,m.index).length>0);}
 if(!on.some(Boolean))return '';
 const stops=[],pct=i=>(i/N*100).toFixed(2)+'%';let start=0;
 for(let i=1;i<=N+1;i++)if(i>N||on[i]!==on[start]){stops.push(`${on[start]?'var(--hot)':'var(--line)'} ${pct(start)} ${pct(Math.min(i,N))}`);start=i;}
 return `linear-gradient(90deg,${stops.join(',')})`;
}
function configureStressPanel(prefix,F){
 const panel=$('#'+prefix+'-stress-panel');if(!panel||!F)return;
 const rules=jointStress(F.it.ex).rules,toggle=$('#'+prefix+'-stress-toggle'),track=$('#'+prefix+'-stress-track');
 if(toggle){toggle.checked=!!motionPrefs.stress;toggle.disabled=!rules.length;}
 /* без пиковых нагрузок переключатель серый — подпись объясняет почему */
 const none=$('#'+prefix+'-stress-none');if(none)none.hidden=!!rules.length;
 panel.hidden=!rules.length||!motionPrefs.stress;
 $('#'+prefix+'-stress-list').innerHTML=rules.map(r=>`<li data-stress-row="${r.id}"><span class="stress-dot" aria-hidden="true"></span><span><b>${esc(r.zone)}.</b> ${esc(r.what)} <em>${esc(r.tip)}</em></span></li>`).join('');
 if(track){const g=motionPrefs.stress?stressTrack(F):'';track.hidden=!g;track.style.background=g;}
}
function paintStressPanel(prefix,F,m){
 const panel=$('#'+prefix+'-stress-panel');if(!panel||panel.hidden)return;
 const now=new Set(jointStressAt(F.it.ex,m.t,m.index).map(x=>x.rule.id));
 for(const row of panel.querySelectorAll('[data-stress-row]'))row.classList.toggle('on',now.has(row.dataset.stressRow));
}
function changeStressPreference(show){
 motionPrefs.stress=!!show;saveMotionPrefs();
 for(const F of [...figs,detailMotion,workout?.motion].filter(Boolean))for(const f of [F.f,F.extra].filter(Boolean))f.setStress?.(motionPrefs.stress);
 for(const line of document.querySelectorAll('.c-joints'))line.hidden=!motionPrefs.stress;
 if(detailMotion){configureStressPanel('mv',detailMotion);paintMotion(detailMotion,true);}
 if(workout?.motion){configureStressPanel('wv',workout.motion);paintWorkoutMotion();}
}
function changeMusclePreference(show){
 motionPrefs.muscles=!!show;saveMotionPrefs();
 for(const F of [...figs,detailMotion,workout?.motion].filter(Boolean)){
  for(const f of [F.f,F.extra].filter(Boolean))f.setMuscles?.(motionPrefs.muscles);
  const note=F.btn?.closest('.motion-tile').querySelector('.muscle-tile-note');if(note)note.hidden=!motionPrefs.muscles;
 }
 if(detailMotion){configureMusclePanel('mv',detailMotion.it);paintMotion(detailMotion,true);const note=$('#mv-figure-note'),text=figureNote(figureView(),detailMotion);if(!note.hidden&&!$('#mv-figure').hasAttribute('aria-busy')&&text)note.textContent=text;}
 if(workout?.motion){configureMusclePanel('wv',workout.motion.it);paintWorkoutMotion();}
}
function scheduleMotionLoop() {
  cancelAnimationFrame(rafId); lastMotionNow=null;
  const loop = now => {
    const dt = lastMotionNow===null ? 0 : Math.min(80,now-lastMotionNow); lastMotionNow=now;
    if (!document.hidden) {
      /* кости и мышцы считаются заново в каждом кадре (≈8 мс на компьютере, на телефоне втрое дольше): «Анатомия» и
         «Скелет» рисуются через кадр, как карточки, — часы идут каждый кадр, движение не замедляется */
      if (detailMotion) {if (!detailMotion.paused) {detailMotion.clock+=dt*Number(motionPrefs.speed);detailMotion.since=(detailMotion.since||0)+dt;
        if(figureView()==='mannequin'||detailMotion.since>=CARD_FRAME_MS){detailMotion.since=0;paintMotion(detailMotion,true);}}}
      else if(gallery.on){/* витрина атласа закрывает план: карточки за ней не анимируются */}
      else if(workout && $('#workout-view').open){const F=workout.motion;if(F && !F.paused && !$('#wv-active').hidden){F.clock+=dt;paintWorkoutMotion();}}
      else for (const F of figs) if (F.f && F.vis && !F.paused && F.active!==false) {
        /* карточки и атлас — 30 кадров в секунду: часы идут каждый кадр, рисунок — через кадр */
        F.clock+=dt;F.since=(F.since||0)+dt;
        if(F.since>=CARD_FRAME_MS){F.since=0;paintMotion(F);}
      }
    }
    rafId=requestAnimationFrame(loop);
  };
  rafId=requestAnimationFrame(loop);
}
/* Карточки плана. Рисунок строится, когда карточка подходит к экрану; двигаются только те, на которые смотрят:
   на телефоне — одна (самая видимая или та, где только что нажали «Пуск»), на широком экране — две,
   и ещё та, что под мышью или в фокусе. Остальные стоят в текущей фазе; пауза пользователя не трогается. */
const CARD_FRAME_MS=30, CARD_NEAR='400px 0px';
let ioSeen=null;
function activeCardCount(){return window.innerWidth>=900?2:1;}
function pickActiveCards(){
  const cards=figs.filter(F=>F.card&&F.f);
  const mid=window.innerHeight/2,dist=F=>{const r=F.btn.getBoundingClientRect();return Math.abs(r.top+r.height/2-mid);};
  /* порядок: под мышью или в фокусе, потом последняя нажатая «Пуск» (пока видна хотя бы наполовину),
     потом самая видимая и ближе к середине экрана */
  const pick=F=>F.seen>=.4?F.pick||0:0;
  const order=cards.filter(F=>!F.paused&&(F.seen>0||F.hover)).sort((a,b)=>(b.hover|0)-(a.hover|0)||pick(b)-pick(a)||Math.round(b.seen*5)-Math.round(a.seen*5)||dist(a)-dist(b));
  const on=new Set(order.slice(0,activeCardCount()+(order[0]?.hover?1:0)));
  let k=0;for(const F of figs)if(F.card){const was=F.active;F.active=on.has(F);if(F.active&&!was)F.since=CARD_FRAME_MS/2*(k++%2);}
}
function buildCardFigure(F){
  if(F.f||F.failed)return;
  try {
    /* начатую заранее рамку досчитать, а не начинать заново */
    if(F.job){F.job.step(41);F.job=null;}
    F.f=buildFigure(F.it.ex.anim,{primary:F.it.ex.pri,has:F.it.has,ratio:1,t:0,label:F.it.name,muscles:motionPrefs.muscles,frameCache:true});
    F.btn.prepend(F.f.svg);paintMotion(F);
  } catch(e) {F.failed=true;console.error('Демонстрация',F.it.ex.id,e);}
}
/* Рамки ещё не построенных карточек досчитываются заранее, по два положения за раз: в простое, а если простоя
   нет (идёт анимация на слабом телефоне) — не реже чем раз в четверть секунды. Тогда при прокрутке карточка
   строится сразу, без долгой паузы. */
let framePrefetchGen=0;
function prefetchCardFrames(){
  const gen=++framePrefetchGen,queue=figs.filter(F=>F.card);let F=null;
  const idle=window.requestIdleCallback?cb=>requestIdleCallback(cb,{timeout:200}):cb=>setTimeout(()=>{const end=performance.now()+8;cb({timeRemaining:()=>Math.max(0,end-performance.now())});},40);
  const work=deadline=>{
    if(gen!==framePrefetchGen)return;
    do {
      if(!F||!F.job){
        F=queue.shift();if(!F)return;
        if(F.f||F.failed){F=null;continue;}
        try{F.job=figureFrameJob(F.it.ex.anim,{has:F.it.has,ratio:1});}catch(e){F.job=null;}
        if(!F.job||F.job.done){F.job=null;continue;}
      }
      /* без простоя (сработал таймаут) — кусок побольше: шесть положений ≈ 3 мс на компьютере */
      if(F.job.step(deadline.didTimeout?6:2))F.job=null;
    } while(deadline.timeRemaining()>3);
    idle(work);
  };
  idle(work);
}
let mountedKit=null;
function mountFigures() {
  figs=[];
  /* инвентарь места сменился: готовые кадры карточек прежнего набора больше не понадобятся */
  const kit=S.place+':'+(S.equip||[]).slice().sort().join(',');if(mountedKit!==null&&kit!==mountedKit)figureFramesReset();mountedKit=kit;
  const flat=plan.blocks.flatMap(b=>b.items);
  document.querySelectorAll('[data-fig]').forEach(btn=>{
    const it=flat[+btn.dataset.fig];if(!it)return;
    const F={btn,it,f:null,card:true,vis:false,seen:0,active:false,paused:reduceMotion,clock:0,durations:motionDurations(it)};
    figs.push(F);
    const tile=btn.closest('.motion-tile');
    if(motionProfile(it.ex.anim)){const note=document.createElement('p');note.className='muscle-tile-note';note.textContent='Цвет — учебная схема';note.hidden=!motionPrefs.muscles;tile.appendChild(note);}
    const pause=tile.querySelector('[data-motion-pause]');
    if(pause){pause.textContent=F.paused?'Пуск':'Пауза';pause.setAttribute('aria-pressed',String(!F.paused));pause.setAttribute('aria-label',`${F.paused?'Воспроизвести':'Приостановить'} демонстрацию: ${it.name}`);}
    const hover=on=>e=>{if(e.pointerType&&e.pointerType!=='mouse')return;F.hover=on;pickActiveCards();};
    tile.addEventListener('pointerenter',hover(true));tile.addEventListener('pointerleave',hover(false));
    btn.addEventListener('focus',()=>{F.hover=true;pickActiveCards();});btn.addEventListener('blur',()=>{F.hover=false;pickActiveCards();});
  });
  if ('IntersectionObserver' in window) {
    const byBtn=new Map(figs.map(F=>[F.btn,F]));
    io=new IntersectionObserver(es=>{for(const e of es){const F=byBtn.get(e.target);if(!F)continue;F.vis=e.isIntersecting;if(F.vis)buildCardFigure(F);}pickActiveCards();},{rootMargin:CARD_NEAR});
    ioSeen=new IntersectionObserver(es=>{for(const e of es){const F=byBtn.get(e.target);if(F)F.seen=e.isIntersecting?e.intersectionRatio:0;}pickActiveCards();},{threshold:[0,.2,.4,.6,.8,1]});
    for(const F of figs){io.observe(F.btn);ioSeen.observe(F.btn);}
    prefetchCardFrames();
  } else for(const F of figs){F.vis=true;F.active=true;buildCardFigure(F);}
  scheduleMotionLoop();
}
function stopFigures() {
  if(workout && $('#workout-view').open)closeWorkout();
  if(detailMotion) closeMotion();
  cancelAnimationFrame(rafId);framePrefetchGen++;if(io)io.disconnect();if(ioSeen)ioSeen.disconnect();io=ioSeen=null;for(const F of figs)disposeMotion(F);figs=[];
}
function previewItem(id) {
  const ex=EXI[id];let E=effEquip(S.equip);
  if(!available(ex,E)) E=effEquip(EQUIP.map(e=>e.id));
  return {ex,name:exName(ex,E),rx:prescribe(ex,S.mode==='program'?WEEKS[S.week-1]:null,E),has:propHas(ex,E),eqLine:equipLine(ex,E)};
}
function selectMotion(it, clock=0) {
  disposeMotion(detailMotion);
  detailMotion={it,f:null,clock,paused:true,durations:motionDurations(it)};
  $('#mv-title').textContent=it.name;
  $('#mv-exercise').value=it.ex.id;
  $('#mv-tools').innerHTML=`${favButton(it.ex.id,true)}<button type="button" class="btn-ghost" data-cp-add="${it.ex.id}">+ В свой план</button><p class="cp-msg" hidden><span></span> <button type="button" class="link" data-cp-go="1">Открыть план →</button></p>`;
  $('#mv-view').textContent=it.ex.viewNote||(it.ex.anim.view==='front'?'Вид спереди':'Вид сбоку');
  $('#mv-speed').value=String(motionPrefs.speed);$('#mv-joints').checked=!!motionPrefs.joints;$('#mv-trace').checked=!!motionPrefs.trace;$('#mv-vectors').checked=!!motionPrefs.vectors;
  $('#mv-tempo').textContent=it.ex.anim.hold?'Удерживайте положение и дышите ровно.':it.ex.anim.timing||it.ex.g==='cardio'||it.ex.kind?'Ритм показан схематично. Замедление помогает разобрать движение.':it.rx.static?`Статодинамика: темп ${it.rx.tempo} без пауз, показана рабочая часть амплитуды — без выпрямления до конца и без расслабления внизу.`:`Темп задания: ${it.rx.tempo}. Скорость просмотра не меняет задание.`;
  const level={};it.ex.pri.forEach(m=>level[m]=1);it.ex.sec.forEach(m=>{if(!level[m])level[m]=.38;});
  $('#mv-muscles').innerHTML=muscleMapSvg(level,{labels:true,aria:'Основные и вспомогательные мышцы'});
  $('#mv-primary').textContent=it.ex.pri.map(m=>MUSCLE_NAMES[m]).join(', ');
  $('#mv-secondary').textContent=it.ex.sec.length?it.ex.sec.map(m=>MUSCLE_NAMES[m]).join(', '):'—';
  $('#mv-steps').innerHTML=it.ex.tech.map(x=>`<li>${esc(x)}</li>`).join('');
  $('#mv-errors').innerHTML=it.ex.err.map(x=>`<li>${esc(x)}</li>`).join('');
  $('#mv-breath').textContent=it.ex.breath;
  $('#mv-note').textContent=it.ex.note||'';
  const links=[...(SOURCES_BY_EX[it.ex.id]||[]),...(motionProfile(it.ex.anim)?.sources||[])];
  const src=links.filter((v,i)=>links.findIndex(x=>x[1]===v[1])===i).map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`);
  $('#mv-sources').innerHTML=src.length?`<p class="mv-muscle-label">Подробнее о технике</p>${src.join('')}`:'';
  mountDetailCameras();
}
/* Вид фигуры в подробном разборе (с 4.30.0 по умолчанию — «Анатомия»):
   · «Анатомия» — кости и мышцы объёмом (толщина — по объёму на МРТ) внутри почти невидимого силуэта кожи; цвет мышц —
     как у областей манекена: с «Мышцами по фазам» — участие в текущей фазе, без них — основные и вспомогательные;
   · «Скелет» — только кости в том же силуэте;
   · «Манекен» — прежний манекен с подсветкой мышечных областей.
   Кости (≈220 КБ) и мышцы (≈38 КБ) грузятся один раз — заранее, в простое после первого экрана (setupMotionViewer), или
   при первом открытии разбора; пока они грузятся, показан манекен. Без объёмной графики доступен только манекен. */
const FIGURE_VIEWS=['anatomy','skeleton','mannequin'];
const figureView=()=>FIGURE_VIEWS.includes(motionPrefs.view)?motionPrefs.view:'anatomy';
function anatomyLevel(ex){const level={};ex.pri.forEach(m=>level[m]=1);ex.sec.forEach(m=>{if(!level[m])level[m]=.38;});return level;}
function figureNote(view,F){
  if(view==='skeleton')return 'Кости — по открытым моделям MyoSim, источники — в «О демонстрациях». Мышцы в этом виде скрыты.';
  if(view!=='anatomy')return '';
  return 'Кости и мышцы — по открытым моделям, толщина мышц — по МРТ; источники — в «О демонстрациях». '+(motionPrefs.muscles&&F&&motionProfile(F.it.ex.anim)
    ?'Цвет мышцы — её участие в этой фазе: чем оранжевее, тем сильнее.':'Цветом — мышцы упражнения: основные ярче, вспомогательные бледнее.');
}
function applyFigureView(F=detailMotion){
  const group=$('#mv-figure'),note=$('#mv-figure-note');if(!group)return;
  const list=F?[F.f,F.extra].filter(Boolean):[],able=list.length>0&&list.every(f=>typeof f.setLayers==='function');
  const view=able?figureView():'mannequin';
  for(const b of group.querySelectorAll('[data-mv-figure]')){const off=!able&&b.dataset.mvFigure!=='mannequin';b.disabled=off;b.title=off?'Нужна объёмная графика (WebGL)':'';b.setAttribute('aria-pressed',String(b.dataset.mvFigure===view));}
  const say=text=>{note.textContent=text;note.hidden=!text;};
  if(view==='mannequin'){for(const f of list)f.setLayers?.(null,null);say('');return;}
  const put=()=>{for(const f of list)f.setLayers(Skeleton.data,view==='anatomy'?{skeleton:Skeleton.data,muscles:Muscles.data,level:anatomyLevel(F.it.ex)}:null);say(figureNote(view,F));};
  const need=view==='anatomy'?[Skeleton,Muscles]:[Skeleton];
  if(need.every(x=>x.data)){put();return;}
  for(const f of list)f.setLayers(null,null);
  group.setAttribute('aria-busy','true');say(view==='anatomy'?'Загружаем кости и мышцы…':'Загружаем кости…');
  Promise.all(need.map(x=>x.load())).then(()=>{
    group.removeAttribute('aria-busy');if(detailMotion!==F||figureView()!==view)return;put();
  },()=>{
    /* выбор не сбрасывается: при следующем открытии разбора загрузка повторится */
    group.removeAttribute('aria-busy');if(detailMotion!==F||figureView()!==view)return;
    for(const b of group.querySelectorAll('[data-mv-figure]'))b.setAttribute('aria-pressed',String(b.dataset.mvFigure==='mannequin'));
    say('Не удалось загрузить кости и мышцы — показан манекен. Проверьте связь и выберите вид ещё раз.');
  });
}
function openMotion(idx) {
  const F=figs.find(f=>+f.btn.dataset.fig===Number(idx));
  openMotionItem(F?F.it:previewItem(EX[0].id),F?F.clock:0);
}
function openMotionItem(it,clock=0){
  detailReturn=document.activeElement;
  showDetail();selectMotion(it,clock);
  const d=$('#motion-view');if(!d.open)d.showModal();
  document.documentElement.classList.add('motion-open');
  $('#mv-close').focus();scheduleMotionLoop();
}
function closeMotion() {
  const d=$('#motion-view');disposeMotion(detailMotion);detailMotion=null;closeGallery();
  if(d&&d.open)d.close();
  document.documentElement.classList.remove('motion-open');
  if(detailReturn&&detailReturn.isConnected)detailReturn.focus();
  detailReturn=null;
}
function setupMotionViewer() {
  window.addEventListener('resize',()=>pickActiveCards(),{passive:true});
  $('#mv-exercise').innerHTML=GROUPS.map(g=>`<optgroup label="${esc(g.name)}">${EX.filter(ex=>ex.g===g.id).map(ex=>`<option value="${ex.id}">${esc(ex.name)}</option>`).join('')}</optgroup>`).join('');

  document.addEventListener('click',e=>{
    const t=e.target.closest('button');if(!t)return;
    if(t.dataset.motionPause!==undefined){const F=figs.find(f=>+f.btn.dataset.fig===+t.dataset.motionPause);if(F){F.paused=!F.paused;if(F.card){F.pick=performance.now();pickActiveCards();}t.textContent=F.paused?'Пуск':'Пауза';t.setAttribute('aria-pressed',String(!F.paused));t.setAttribute('aria-label',`${F.paused?'Воспроизвести':'Приостановить'} демонстрацию: ${F.it.name}`);}return;}
    if(t.id==='motion-atlas'){openGallery();return;}
    if(t.id==='mv-close'){closeMotion();return;}
    if(!detailMotion)return;
    if(t.dataset.mvFigure){if(t.dataset.mvFigure!==figureView()||t.getAttribute('aria-pressed')!=='true'){motionPrefs.view=t.dataset.mvFigure;saveMotionPrefs();applyFigureView();}return;}
    if(t.id==='mv-play'){detailMotion.paused=!detailMotion.paused;paintMotion(detailMotion,true);}
    if(t.dataset.mvStep){const m=motionFrame(detailMotion);detailMotion.paused=true;detailMotion.clock=Math.max(0,Math.min(m.total-1,(m.progress+Number(t.dataset.mvStep))*m.total));paintMotion(detailMotion,true);}
    if(t.dataset.mvPose){const d=detailMotion.durations;detailMotion.paused=true;detailMotion.clock=({start:0,middle:d[0]*.5,end:d[0]+d[1]*.5,return:d[0]+d[1]+d[2]*.5})[t.dataset.mvPose];paintMotion(detailMotion,true);}
    /* соседние упражнения — в том же порядке, что в списке (по группам мышц) */
    if(t.dataset.mvNav){const ids=[...$('#mv-exercise').options].map(o=>o.value),i=ids.indexOf(detailMotion.it.ex.id);selectMotion(previewItem(ids[(i+Number(t.dataset.mvNav)+ids.length)%ids.length]));}
  });
  $('#mv-progress').addEventListener('input',e=>{if(!detailMotion)return;const m=motionFrame(detailMotion);detailMotion.paused=true;detailMotion.clock=Number(e.target.value)/1000*(m.total-1);paintMotion(detailMotion,true);});
  $('#mv-speed').addEventListener('change',e=>{motionPrefs.speed=Number(e.target.value);saveMotionPrefs();});
  $('#mv-exercise').addEventListener('change',e=>selectMotion(previewItem(e.target.value)));
  $('#mv-joints').addEventListener('change',e=>{motionPrefs.joints=e.target.checked;if(detailMotion)for(const f of [detailMotion.f,detailMotion.extra].filter(Boolean)){f.svg.classList.toggle('show-joints',e.target.checked);f.setJoints?.(e.target.checked);}saveMotionPrefs();});
  $('#mv-vectors').addEventListener('change',e=>{motionPrefs.vectors=e.target.checked;if(detailMotion)for(const f of [detailMotion.f,detailMotion.extra].filter(Boolean))f.setVectors(e.target.checked);saveMotionPrefs();});
  $('#mv-trace').addEventListener('change',e=>{motionPrefs.trace=e.target.checked;if(detailMotion)for(const f of [detailMotion.f,detailMotion.extra].filter(Boolean))f.setTrace(e.target.checked);saveMotionPrefs();});
  $('#mv-muscle-toggle').addEventListener('change',e=>changeMusclePreference(e.target.checked));
  $('#wv-muscle-toggle').addEventListener('change',e=>changeMusclePreference(e.target.checked));
  for(const prefix of ['mv','wv'])$('#'+prefix+'-stress-toggle').addEventListener('change',e=>changeStressPreference(e.target.checked));
  for(const prefix of ['mv','wv'])$('#'+prefix+'-region').addEventListener('change',e=>selectMuscleRegion(prefix,e.target.value));
  $('#motion-view').addEventListener('cancel',e=>{e.preventDefault();closeMotion();});
  $('#motion-view').addEventListener('close',()=>{disposeMotion(detailMotion);detailMotion=null;closeGallery();document.documentElement.classList.remove('motion-open');});
  /* объёмная графика грузится после первого экрана (build.js): если разбор или тренировка открыты раньше, показывается
     плоская схема, а с приходом объёма та же фаза перерисовывается в нём */
  window.addEventListener('gym-volume',()=>{
    if(detailMotion&&!gallery.on)mountDetailCameras();if(workout?.motion&&$('#workout-view').open)mountWorkoutCameras();
    /* сетка головы (≈55 мс на компьютере) одна на все упражнения: готовится в простое, а не при первом открытии разбора */
    const idle=window.requestIdleCallback||(f=>setTimeout(f,2000));idle(()=>{try{Mannequin.headMesh();}catch(e){}},{timeout:6000});
    /* кости и мышцы для вида «Анатомия» — тоже заранее: первое открытие разбора сразу показывает анатомию */
    if(figureView()!=='mannequin')idle(()=>{Skeleton.load().catch(()=>{});if(figureView()==='anatomy')Muscles.load().catch(()=>{});},{timeout:8000});
  });
  $('#motion-view').addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();if(detailMotion){detailMotion.paused=!detailMotion.paused;paintMotion(detailMotion,true);}}});
}


/* ---------- таймер отдыха в плане ----------
   Время — по меткам (restView в 12a-set-timers.js). После нуля таймер считает вверх «+0:25» и повторяет сигнал (если
   выбран «настойчивый»), пока не отмечен следующий подход или не нажато «Готово»; уходит через 5 с после последнего сигнала. */
const T = {left:0, total:0, id:0, end:0, from:0, label:''};
function startRest(sec, label) {
  if (!sec) return;
  T.total = sec; T.left = sec; T.from = Date.now(); T.end = T.from + sec * 1000; T.label = label || 'Отдых';
  $('#t-label').textContent = T.label;
  $('#timer').hidden = false; $('#timer').classList.remove('over');
  RestAlarm.unlock(); RestAlarm.arm(T.end, {from:T.from}); RestAlarm.paintButton($('#t-sound'));
  clearInterval(T.id); clearTimeout(T.id); tick(); T.id = setInterval(tick, 250);
}
function tick() {
  const now = Date.now(), v = restView(T.end, now);
  T.left = v.left;
  $('#t-time').textContent = v.text;
  $('#t-bar').style.width = (T.total ? (1 - v.left / T.total) * 100 : 100) + '%';
  RestAlarm.poll(now);
  $('#timer').classList.toggle('over', v.over); $('#t-minus').disabled = v.over;
  const label = v.over ? 'Пора к следующему подходу · сверх отдыха' : T.label;
  if ($('#t-label').textContent !== label) $('#t-label').textContent = label;
  if (v.over && now >= Math.max(T.end, RestAlarm.lastAt()) + 5000) stopRest();
}
function adjustRest(d) {
  if ($('#timer').hidden) return;
  const now = Date.now(), end = restAdjust(T.end, now, d);
  if (end === T.end) return;
  T.total = Math.max(1, T.total + Math.round((end - T.end) / 1000)); T.end = end;
  RestAlarm.arm(T.end, {from:T.from}); clearTimeout(T.id); clearInterval(T.id); tick(); T.id = setInterval(tick, 250);
}
function stopRest() { clearInterval(T.id); clearTimeout(T.id); RestAlarm.cancel(); $('#timer').hidden = true; $('#t-minus').disabled = false; }

/* ---------- текст для копирования ---------- */
function blocksText(p) {
  const lines = [];
  for (const b of p.blocks) {
    if (b.kind === 'pair') lines.push(b.items.length > 1 ? `Суперсет ${b.letter}: ${b.sets} ${plural(b.sets, 'круг', 'круга', 'кругов')}, отдых ${fmtRest(b.rest)} после пары` : `${b.letter}:`);
    if (b.kind === 'circuit') lines.push(`Круг × ${b.rounds}: переход ${fmtRest(b.rest)}, отдых после круга ${fmtRest(b.roundRest)}`);
    for (const it of b.items) {
      const r = it.rx;
      const side = r.uni ? ' на сторону' : '';
      if (r.static) { const kgS = r.kgPlan && loadType(it.ex) !== 'none' ? `, ${planKgText(r.kgPlan)} кг` : ''; lines.push(`${it.label}. ${it.name} — ${r.series} × 3 × ${r.reps}${r.unit ? ' ' + r.unit : ''}${side}, темп ${r.tempo} без расслабления, отдых ${fmtRest(r.rest)}${r.series > 1 ? `, между сериями ${fmtRest(r.seriesRest)}` : ''}${kgS}`); if (r.coachNote) lines.push(`   Заметка: ${r.coachNote.replace(/\n+/g, ' ')}`); continue; }
      const kg = r.kgPlan && loadType(it.ex) !== 'none' ? `, ${planKgText(r.kgPlan)} кг` : '';
      lines.push(r.circ ? `${it.label}. ${it.name} — ${r.reps}${r.unit ? ' ' + r.unit : ''}${side}${kg}` : `${it.label}. ${it.name} — ${r.sets} × ${r.reps}${r.unit ? ' ' + r.unit : ''}${side}${kg}${b.kind === 'list' ? `, отдых ${fmtRest(r.rest)}` : ''}`);
      if (r.coachNote) lines.push(`   Заметка: ${r.coachNote.replace(/\n+/g, ' ')}`);
    }
  }
  return lines;
}
function planText() {
  const G = GOALS[S.goal];
  if (S.mode === 'program' && prog) {
    const out = [`${SPLITS[prog.split].name}, ${S.days} ${plural(S.days, 'тренировка', 'тренировки', 'тренировок')} в неделю — ${G.name.toLowerCase()}`,
      `Неделя ${S.week} из 4: ${prog.week.name.toLowerCase()}. ${prog.week.note}`];
    for (const d of prog.days) {
      out.push('', `${WD_FULL[d.wd]} — ${d.name}${d.plan.items ? `, ≈${d.plan.minutes} мин` : ''}`);
      if (d.plan.items) out.push(...blocksText(d.plan)); else out.push('нет упражнений с выбранным оборудованием');
    }
    return out.join('\n');
  }
  return [`${titleFor()} — ${G.name.toLowerCase()}, ${FORMATS[S.format].name.toLowerCase()}, ≈${plan.minutes} мин`, ''].concat(blocksText(plan)).join('\n');
}

/* ---------- события ---------- */
/* место тренировок: название и источник программы */
document.addEventListener('change', e => {
  if (e.target.id === 'place-name') { const v = e.target.value.trim().slice(0, 24); if (v) placeOf().name = v; saveSettings(); renderSetup(); return; }
  if (e.target.id === 'place-adapt') { S.adapt = e.target.value || null; ensurePlaces(S); return regen(); }
});
const swapKey = () => S.mode === 'program' ? 'd' + S.day : 's';
function regen(resetSwaps = true) { if (resetSwaps) swaps = S.swaps = {}; done = {}; saveSettings(); renderSetup(); renderPlan(); }
document.addEventListener('click', e => {
  const t = e.target.closest('button, summary');
  if (!t) return;
  if (t.dataset.set) {
    const k = t.dataset.set, prev = S.mode; S[k] = t.dataset.v;
    if (k === 'mode') { S.day = 0; switchModeSettings(prev); } else storePlanSetting(k);
    return regen();
  }
  if (t.dataset.days) { S.days = +t.dataset.days; S.split = DEFAULT_SPLIT[S.days]; S.day = 0; return regen(); }
  if (t.dataset.split) { S.split = t.dataset.split; S.day = 0; return regen(); }
  if (t.dataset.week) { S.week = +t.dataset.week; done = {}; saveSettings(); renderPlan(); return; }
  if (t.dataset.day !== undefined) {
    S.day = +t.dataset.day; done = {}; saveSettings(); renderPlan();
    const dh = $('.day-head'); if (dh) dh.scrollIntoView({block:'nearest', behavior:reduceMotion ? 'auto' : 'smooth'});
    return;
  }
  if (t.id === 'count-minus') { S.count = Math.max(3, S.count - 1); return regen(); }
  if (t.id === 'count-plus') { S.count = Math.min(10, S.count + 1); return regen(); }
  if (t.dataset.g) { const g = t.dataset.g; S.groups = S.groups.includes(g) ? S.groups.filter(x => x !== g) : S.groups.concat(g); S.groups.sort((a, b) => GROUPS.findIndex(x => x.id === a) - GROUPS.findIndex(x => x.id === b)); return regen(); }
  if (t.dataset.gp) { S.groups = GROUP_PRESETS.find(p => p.id === t.dataset.gp).g.slice(); return regen(); }
  if (t.dataset.e) { eqOpen = true; const id = t.dataset.e; setPlaceEquip(S.equip.includes(id) ? S.equip.filter(x => x !== id) : S.equip.concat(id)); return regen(); }
  if (t.dataset.ep) { setPlaceEquip(EQUIP_PRESETS.find(p => p.id === t.dataset.ep).eq); return regen(); }
  if (t.dataset.place) { S.place = t.dataset.place; ensurePlaces(S); placeDel = false; return regen(); }
  if (t.dataset.placeAdd !== undefined) {
    const id = 'p' + Date.now().toString(36);
    S.places.push({id, name:'Место ' + (S.places.length + 1), equip:[]});
    S.place = id; ensurePlaces(S); eqOpen = true; placeDel = false; regen();
    const inp = $('#place-name'); if (inp) { inp.focus(); inp.select(); }
    return;
  }
  if (t.dataset.placeDel !== undefined) {
    if (!placeDel) { placeDel = true; return renderSetup(); }
    S.places = S.places.filter(p => p.id !== S.place); placeDel = false; ensurePlaces(S); return regen();
  }
  if (t.id === 'reroll') { S.seed = (S.seed * 48271 + 11) % 2147483647; regen(); $('#plan').scrollIntoView({behavior:reduceMotion ? 'auto' : 'smooth', block:'start'}); return; }
  if (t.id === 'copy') {
    const txt = planText(), msg = $('#copy-msg');
    const fallback = () => { msg.innerHTML = 'Скопировать автоматически не удалось. Выделите текст:<textarea readonly rows="6"></textarea>'; const ta = msg.querySelector('textarea'); ta.value = txt; ta.focus(); ta.select(); };
    try { navigator.clipboard.writeText(txt).then(() => { msg.textContent = 'Скопировано — можно вставить в заметки или мессенджер.'; }, fallback); } catch (err) { fallback(); }
    return;
  }
  if (t.dataset.swap !== undefined) {
    const slot = +t.dataset.swap;
    const cur = plan.items.find(it => it.slot === slot).ex;
    const inPlan = new Set(plan.items.map(it => it.ex.id));
    const lvlMax = S.level === 'beg' || S.goal === 'gentle' ? 2 : 3;
    const tried = new Set((swaps.__tried && swaps.__tried[swapKey() + ':' + slot]) || []);
    /* ближайшие по смыслу: то же движение и те же мышцы — первыми */
    if (S.mode === 'custom') for (const it of customOf().items) inPlan.add(it.id);
    let alts = EX.filter(ex => !inPlan.has(ex.id) && available(ex, plan.E) && ex.lvl <= lvlMax && (ex.g === cur.g || PATTERN[ex.id] === PATTERN[cur.id]) && (S.format !== 'static' || staticOk(ex)) && fitsBody(ex))
      .sort((a, b) => analogScore(cur, b) - analogScore(cur, a));
    const msgEl = t.querySelector('span');
    if (!alts.length) { msgEl.textContent = 'Замены нет'; setTimeout(() => { msgEl.textContent = 'Заменить'; }, 1800); return; }
    tried.add(cur.id);
    let next = alts.find(ex => !tried.has(ex.id));
    if (!next) { tried.clear(); tried.add(cur.id); next = alts[0]; }
    swaps.__tried = swaps.__tried || {};
    swaps.__tried[swapKey() + ':' + slot] = [...tried];
    /* в своём плане замена записывается в сам план; правка подходов и отдыха остаётся */
    if (S.mode === 'custom') { const item = customOf().items[slot]; if (item) { item.id = next.id; saveSettings(); } }
    else { const k = swapKey(); swaps[k] = swaps[k] || {}; swaps[k][slot] = next.id; }
    done = {};
    saveSettings(); renderPlan();
    const card = document.querySelector(`.card[data-slot="${slot}"]`);
    if (card) { card.classList.add('flash'); card.scrollIntoView({block:'nearest', behavior:reduceMotion ? 'auto' : 'smooth'}); }
    return;
  }
  /* порядок упражнений: ↑ ↓ на карточке (в своём плане — свои кнопки, 11d-custom.js) */
  if (t.dataset.move !== undefined) {
    const slot = +t.dataset.move, d = +t.dataset.d;
    if (!movePlanItem(slot, d)) return;
    saveSettings(); renderPlan();
    const card = document.querySelector(`.card[data-slot="${slot}"]`);
    if (card) {
      card.classList.add('flash'); card.scrollIntoView({block:'nearest', behavior:reduceMotion ? 'auto' : 'smooth'});
      const b = card.querySelector(`[data-move][data-d="${d}"]:not([disabled])`) || card.querySelector('[data-move]:not([disabled])'); if (b) b.focus({preventScroll:true});
    }
    return;
  }
  if (t.dataset.round !== undefined) {
    const k = +t.dataset.round, cur = done.__rounds || 0;
    done.__rounds = cur === k + 1 ? k : k + 1;
    t.parentElement.querySelectorAll('.set').forEach((b, i) => b.classList.toggle('done', i < done.__rounds));
    const b = plan.blocks[0];
    if (done.__rounds > cur && done.__rounds < b.rounds) startRest(b.roundRest, `Отдых после круга ${done.__rounds}`);
    return;
  }
  if (t.dataset.fig !== undefined) {openMotion(t.dataset.fig);return;}
  if (t.id === 'e-toggle' || t.id === 'e-toggle-top') {
    eqOpen = !eqOpen; renderSetup();
    /* свернули снизу длинного списка — вернуть взгляд к заголовку раздела */
    if (!eqOpen && t.id === 'e-toggle') { const h = $('.e-head'); if (h && h.getBoundingClientRect().top < 0) h.scrollIntoView({block:'start', behavior:reduceMotion ? 'auto' : 'smooth'}); }
    return;
  }
  if (t.id === 't-minus') return adjustRest(-15);
  if (t.id === 't-plus') return adjustRest(15);
  if (t.id === 't-skip') return stopRest();
});

/* ---------- таймеры подхода: чистые расчёты ----------
   Отдых и удержания (планка, вис, «стульчик», «лодочка») считаются только по меткам времени Date.now(), а не по числу
   «тиков»: в скрытой вкладке Chrome таймеры страницы срабатывают раз в секунду, через 5 минут — раз в минуту, и счёт по
   тикам отстал бы. Здесь нет страницы и звука — только фазы, числа на экране и моменты сигналов (проверки —
   tools/set-timers.test.js). Звук и вибрация — 12b-rest-alarm.js, экран тренировки — 14-workout-mode.js. */
/* every — повтор сигнала после нуля, с; repeats — не больше трёх повторов; warn — мягкий сигнал за 10 с до конца;
   grace — сигнал, опоздавший больше чем на 2 с (страница спала), уже не подаётся; maxActual — отдых длиннее 30 мин —
   перерыв, а не отдых: в журнал не пишется */
const REST_SIGNAL = {every:20, repeats:3, warn:10, grace:2, maxActual:1800};
/* удержание: отсчёт 3-2-1 перед стартом и пауза между сторонами (боковая планка), с */
const HOLD = {lead:3, pause:10};

function clockText(sec) { sec = Math.max(0, Math.floor(sec)); return `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`; }

/* отдых на момент now: до конца — обратный отсчёт (с округлением вверх: «0:01» до самого нуля), после — сколько сверх */
function restView(end, now) {
  const ms = end - now;
  if (ms > 0) { const left = Math.ceil(ms / 1000); return {over:false, left, extra:0, text:clockText(left)}; }
  const extra = Math.floor(-ms / 1000);
  return {over:true, left:0, extra, text:'+' + clockText(extra)};
}

/* моменты сигналов отдыха (мс): за 10 с до конца — мягкий (если включён и отдых длиннее 15 с), конец, затем в режиме
   «настойчиво» — повторы раз в 20 с, не больше трёх. from — начало отдыха. */
function restSignals(end, {mode = 'persist', warn = false, from = null} = {}) {
  const out = [];
  if (warn && (from == null || end - from > (REST_SIGNAL.warn + 5) * 1000)) out.push({at:end - REST_SIGNAL.warn * 1000, kind:'warn'});
  out.push({at:end, kind:'end'});
  if (mode !== 'once') for (let i = 1; i <= REST_SIGNAL.repeats; i++) out.push({at:end + i * REST_SIGNAL.every * 1000, kind:'repeat'});
  return out;
}
/* какие сигналы наступили к now и ещё не поданы (fired — отметки по номерам). Опоздавший больше чем на 2 с помечен late:
   его не повторяют — на экране и так видно «+0:40» */
