/* ===================== ЖУРНАЛ ===================== */
/* Хранилище: в опубликованной версии — аккаунт (db, личный раздел пользователя),
   в офлайн-файле — браузер. Формат: LOG.data[exId] = [{d:'2026-10-05', wk?:1, eq?:'db', s:[[кг|null, повторы, отдых?, стороны?] | null, …]}, …].
   Третье поле подхода — необязательное: фактический отдых после подхода, целые секунды (пишет режим тренировки). Старые
   записи без него читаются как раньше, прежние версии приложения его просто не видят. Четвёртое — левая и правая
   сторона отдельно {l:[кг, повторы], r:[кг, повторы]} (переключатель «Л/П отдельно»); тогда отдых может быть пустым
   (null), а основные поля — слабая сторона. eq — снаряд (гантели, гиря, штанга) у упражнений с гантелями или гирей:
   по нему считается общий вес. Подробно — 13a-sets.js. */
const LOG_KEY = 'podhod.log.v1';
const LOG = {mode:'connecting', data:{}, col:null, pending:{}, writing:{}, again:{}, timers:{}, err:'', dl:null, canExport:false};
const WEIGHTED = new Set(['db', 'bb', 'kb', 'cable', 'smith', 'legpress', 'legext', 'legcurl', 'pecdeck', 'hack', 'chestpress', 'shoulderpress', 'leverrow', 'tbar', 'abductor', 'calfseat', 'calfstand']);
const LOWER_G = new Set(['quads', 'hams', 'glutes', 'calves']);
const MACHINE = new Set(['cable', 'smith', 'legext', 'legcurl', 'pecdeck', 'chestpress', 'shoulderpress', 'leverrow', 'abductor', 'calfseat', 'calfstand', 'gravitron', 'hack', 'tbar']);
const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

function dayKey(d) { return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
const todayKey = () => dayKey(new Date());
function fmtDay(k, withYear) {
  if (k === todayKey()) return 'сегодня';
  const [y, m, d] = k.split('-').map(Number);
  return `${d} ${MONTHS[m - 1]}${withYear && y !== new Date().getFullYear() ? ' ' + y : ''}`;
}
let DEC = ','; /* десятичный разделитель; в английской сборке заменяется на точку */
const fmtKg = v => (Math.round(v * 100) / 100).toString().replace('.', DEC);
const parseNum = v => { const n = parseFloat(String(v).replace(',', '.')); return isFinite(n) ? n : null; };

function validSessions(ss) {
  return Array.isArray(ss) && ss.every(x => x && typeof x.d === 'string' && /^\d{4}-\d\d-\d\d$/.test(x.d) && Array.isArray(x.s));
}
function logLoadLocal() {
  try {
    const s = JSON.parse(localStorage.getItem(LOG_KEY) || 'null');
    if (s && typeof s === 'object') for (const [k, v] of Object.entries(s)) if (EXI[k] && validSessions(v)) LOG.data[k] = v;
  } catch (e) {}
}
function logSaveLocal() { try { localStorage.setItem(LOG_KEY, JSON.stringify(LOG.data)); } catch (e) {} }

/* объединение двух историй: по дате; при совпадении берём запись с большим числом подходов */
function mergeSessions(a, b) {
  const by = new Map();
  for (const x of a || []) by.set(x.d, x);
  for (const x of b || []) {
    const cur = by.get(x.d);
    if (!cur || x.s.filter(Boolean).length > cur.s.filter(Boolean).length) by.set(x.d, x);
  }
  return [...by.values()].sort((p, q) => p.d < q.d ? -1 : 1).slice(-150);
}

async function logInit() {
  const c = window.claude;
  if (!c || typeof c.use !== 'function') { LOG.mode = 'local'; LOG.canExport = true; logRefresh(null); return; }
  let db = null, user = null;
  try { [db, user, LOG.dl] = await Promise.all([c.use('db'), c.use('user'), c.use('downloads')]); } catch (e) {}
  LOG.canExport = !!LOG.dl;
  const uid = user ? await user.id() : null;
  if (!db || !uid) { LOG.mode = 'local'; logRefresh(null); return; }
  try { LOG.col = db.collection('data/users/' + uid); } catch (e) { LOG.mode = 'local'; logRefresh(null); return; }
  LOG.mode = 'cloud';
  const before = JSON.parse(JSON.stringify(LOG.data));
  let first = true;
  LOG.col.onSnapshot(snap => {
    const remote = {};
    let bodyDoc = null;
    for (const d of snap.docs) { const b = d.data(); if (d.id === '_body') bodyDoc = b; else if (b && EXI[d.id] && validSessions(b.sessions)) remote[d.id] = b.sessions; }
    const changed = [], wasFirst = first;
    if (first) {
      first = false;
      /* записи, сделанные в этом браузере до подключения, переносим в аккаунт */
      for (const id of new Set([...Object.keys(remote), ...Object.keys(before)])) {
        const merged = mergeSessions(remote[id], before[id]);
        if (JSON.stringify(merged) !== JSON.stringify(remote[id] || [])) { LOG.data[id] = merged; logTouch(id, true); }
        else LOG.data[id] = remote[id];
        changed.push(id);
      }
    } else {
      for (const id of new Set([...Object.keys(remote), ...Object.keys(LOG.data)])) {
        if (LOG.pending[id]) continue;
        const r = remote[id] || [];
        if (JSON.stringify(r) === JSON.stringify(LOG.data[id] || [])) continue;
        if (r.length) LOG.data[id] = r; else delete LOG.data[id];
        changed.push(id);
      }
    }
    logSaveLocal();
    bodyRemote(bodyDoc, wasFirst);
    logRefresh(changed);
  }, err => {
    if (err && err.code === 'unavailable') return;
    LOG.mode = 'local'; LOG.err = 'Связь с аккаунтом потеряна — новые записи сохраняются в этом браузере.'; logRefresh(null);
  });
  logRefresh(null);
}

function logTouch(id, now) {
  logSaveLocal();
  if (LOG.mode !== 'cloud') return;
  LOG.pending[id] = true;
  clearTimeout(LOG.timers[id]);
  LOG.timers[id] = setTimeout(() => logFlush(id), now ? 0 : 800);
}
async function logFlush(id, retried) {
  if (LOG.writing[id]) { LOG.again[id] = true; return; }
  LOG.writing[id] = true;
  try {
    const ss = (LOG.data[id] || []).filter(x => x.s.some(Boolean));
    if (ss.length) await LOG.col.doc(id).set({ex:id, sessions:ss});
    else await LOG.col.doc(id).delete();
  } catch (e) {
    const code = e && e.code;
    if (code === 'unavailable' && !retried) { LOG.writing[id] = false; setTimeout(() => logFlush(id, true), 600 + Math.random() * 900); return; }
    if (code === 'quota_exceeded') LOG.err = 'Хранилище журнала заполнено. Удалите старые записи или сделайте резервную копию.';
    else { LOG.mode = 'local'; LOG.err = 'Сохранить в аккаунт не получилось — записи сохраняются в этом браузере.'; }
    logRefresh(null);
  } finally {
    LOG.writing[id] = false;
    if (LOG.again[id]) { LOG.again[id] = false; logFlush(id); } else LOG.pending[id] = false;
  }
}

function todaySession(id, create) {
  let ss = LOG.data[id];
  if (!ss) { if (!create) return null; ss = LOG.data[id] = []; }
  const d = todayKey();
  let s = ss.find(x => x.d === d);
  if (!s && create) {
    s = {d, s:[]};
    if (S.mode === 'program') s.wk = S.week;
    ss.push(s); ss.sort((a, b) => a.d < b.d ? -1 : 1);
    if (ss.length > 150) ss.splice(0, ss.length - 150);
  }
  return s;
}
function pastSessions(id) { const d = todayKey(); return (LOG.data[id] || []).filter(x => x.d < d && x.s.some(Boolean)); }
function cleanToday(id) {
  const ss = LOG.data[id]; if (!ss) return;
  const s = ss.find(x => x.d === todayKey()); if (!s) return;
  while (s.s.length && !s.s[s.s.length - 1]) s.s.pop();
  if (!s.s.length) ss.splice(ss.indexOf(s), 1);
  if (!ss.length) delete LOG.data[id];
}

/* ---------- что записываем ---------- */
function loadType(ex) {
  if (ex.assist) return 'assist'; /* гравитрон: записываем противовес, меньше — тяжелее */
  if (ex.eq.some(g => g.every(id => WEIGHTED.has(id)))) return 'kg';
  if (ex.g === 'cardio' || ex.eq.some(g => g.includes('band') || g.includes('abwheel'))) return 'none';
  return 'extra';
}
function repLabel(ex) { return ex.kind === 'time' ? 'Секунды' : ex.kind === 'dist' ? 'Метры' : 'Повторы'; }
function stepFor(it) {
  const ids = it.eqIds || [], lower = LOWER_G.has(it.ex.g);
  if (ids.includes('legpress') || ids.includes('hack')) return 10;
  if (ids.includes('bb') || ids.includes('smith')) return lower ? 5 : 2.5;
  if (ids.some(i => MACHINE.has(i))) return lower ? 5 : 2.5;
  if (ids.includes('db')) return 2;
  if (ids.includes('kb')) return 4;
  return 2.5;
}
const roundTo = (v, st) => Math.max(0, Math.round(v / st) * st);
function parseRange(r) { const m = String(r).match(/(\d+)\D+(\d+)/); if (m) return [+m[1], +m[2]]; const n = parseInt(r, 10); return [n || 0, n || 0]; }
const e1rm = (kg, reps) => kg * (1 + Math.min(reps, 12) / 30);

/* ---------- подсказка по двойной прогрессии ---------- */
/* прогрессия — по основным полям подхода (у Л/П это слабая сторона); если в прошлый раз одна сторона отставала —
   короткая строка об этом */
function suggest(it) {
  const res = suggestBase(it), last = res.prev || pastSessions(it.ex.id).slice(-1)[0], note = weakSideNote(it.ex, last);
  if (note) res.text += ' ' + note;
  return res;
}
function suggestBase(it) {
  /* статодинамика и обычные подходы ведутся раздельно: вес в них отличается примерно вдвое */
  const ex = it.ex, lt = loadType(ex), all = pastSessions(ex.id), past = all.filter(s => (s.fmt === 'static') === !!it.rx.static);
  const [lo, hi] = parseRange(it.rx.reps);
  const unit = ex.kind === 'time' ? ' с' : ex.kind === 'dist' ? ' м' : '';
  const week = S.mode === 'program' ? WEEKS[S.week - 1] : null;
  const step = stepFor(it);
  const res = {tone:'new', kg:null, reps:[], text:'', prev:null};
  /* вес по плану (свой план, план тренера) — цель вместо подсказки по прогрессии */
  if (it.rx.kgPlan && lt !== 'none') {
    const prev = past[past.length - 1] || null, ps = prev ? prev.s.filter(Boolean) : [];
    res.tone = 'plan'; res.kgs = it.rx.kgPlan; res.kg = it.rx.kgPlan[0]; res.prev = prev;
    const what = lt === 'assist' ? 'Противовес по плану' : lt === 'extra' ? 'Доп. вес по плану' : 'Вес по плану';
    res.text = `${what}: ${planKgText(it.rx.kgPlan)} кг.` + (ps.length ? ` В прошлый раз: ${ps.map(x => (x[0] ? fmtKg(x[0]) + '×' : '') + x[1]).join(', ')}.` : '');
    return res;
  }
  if (it.rx.static && !past.length) {
    const last = all[all.length - 1], kgs = last ? last.s.filter(Boolean).map(x => x[0]).filter(v => v > 0) : [];
    if (lt === 'kg' && kgs.length) {
      const w = Math.max(...kgs); res.kg = roundTo(w * .6, step);
      res.text = `Статодинамика: около ${fmtKg(res.kg)} кг — примерно 60% от прошлого рабочего веса (${fmtKg(w)} кг). К концу подхода — сильное жжение, но не отказ.`;
    } else res.text = lt === 'kg' ? 'Первая запись в статодинамике. Возьмите около половины обычного рабочего веса: к концу подхода — сильное жжение, но не отказ.'
      : lt === 'assist' ? 'Первая запись в статодинамике. Подберите противовес, при котором к концу подхода сильное жжение, но не отказ.'
      : 'Первая запись в статодинамике. Отметьте, сколько медленных повторов получилось в каждом подходе.';
    return res;
  }
  if (!past.length) {
    res.text = lt === 'assist' ? `Первая запись. Подберите противовес, с которым ${lo === hi ? lo : lo + '–' + hi} повторов даются с запасом в 2.` : lt === 'kg'
      ? (ex.kind === 'dist' ? 'Первая запись. Возьмите тяжёлые снаряды, с которыми проходите дистанцию без остановок.' : `Первая запись. Подберите вес, с которым ${lo === hi ? lo : lo + '–' + hi}${unit} даются с запасом в 2 повтора.`)
      : `Первая запись. Отметьте, сколько ${ex.kind === 'time' ? 'секунд' : ex.kind === 'dist' ? 'метров' : 'повторов'} получилось в каждом подходе.`;
    return res;
  }
  const prev = past[past.length - 1];
  res.prev = prev;
  const sets = prev.s.filter(Boolean);
  const kgs = sets.map(x => x[0]).filter(v => v > 0);
  const work = kgs.length ? Math.max(...kgs) : null;
  const atWork = work ? sets.filter(x => x[0] === work) : sets;
  const repsList = atWork.map(x => x[1]);
  const prevList = sets.map(x => (x[0] ? fmtKg(x[0]) + '×' : '') + x[1]).join(', ');
  if (ex.kind === 'dist') { res.tone = 'same'; res.kg = work; res.text = work ? `В прошлый раз — ${fmtKg(work)} кг. Попробуйте пройти дальше или взять тяжелее.` : `В прошлый раз: ${prevList} м.`; return res; }
  if (!week && AR.light && work && (lt === 'kg' || lt === 'assist')) {
    res.tone = 'deload'; res.kg = lt === 'assist' ? Math.max((Math.floor(work / step) + 1) * step, roundTo(work * 1.1, step)) : roundTo(work * .9, step); res.reps = sets.map(() => lo);
    res.text = lt === 'assist' ? `Облегчённый режим: противовес ${fmtKg(res.kg)} кг вместо ${fmtKg(work)}, без отказа.` : `Облегчённый режим: ${fmtKg(res.kg)} кг вместо ${fmtKg(work)}, без отказа.`;
    return res;
  }
  if (week && week.deload && work) {
    res.tone = 'deload'; res.kg = lt === 'assist' ? Math.max((Math.floor(work / step) + 1) * step, roundTo(work * 1.15, step)) : roundTo(work * .85, step);
    res.reps = sets.map(() => lo);
    res.text = lt === 'assist' ? `Разгрузка: противовес ${fmtKg(res.kg)} кг вместо ${fmtKg(work)}, без отказа.` : `Разгрузка: ${fmtKg(res.kg)} кг вместо ${fmtKg(work)}, без отказа.`;
    return res;
  }
  const required=prev.target || (it.rx.circ ? it.rounds : it.rx.sets) || 1;
  const allTop=prev.s.length>=required && Array.from({length:required},(_,k)=>prev.s[k]).every(v=>v && v[1]>=hi && (!work || v[0]===work));
  const anyLow = repsList.some(r => r < lo);
  if (allTop) {
    if (lt === 'kg' && work) {
      res.tone = 'up'; res.kg = work + step; res.reps = sets.map(() => lo);
      res.text = `Прибавьте до ${fmtKg(res.kg)} кг (+${fmtKg(step)}). В прошлый раз все подходы на верхней границе: ${prevList}.`;
    } else if (lt === 'assist' && work) {
      res.tone = 'up'; res.kg = Math.max(0, work - step); res.reps = sets.map(() => lo);
      res.text = `Уменьшите противовес до ${fmtKg(res.kg)} кг (−${fmtKg(step)}). В прошлый раз все подходы на верхней границе: ${prevList}.`;
    } else if (ex.kind === 'time') {
      res.tone = 'up'; res.kg = work; res.reps = sets.map(() => hi + 10);
      res.text = `Все подходы на верхней границе. Держите на 10 с дольше${lt === 'extra' ? ' или добавьте отягощение' : ''}.`;
    } else {
      res.tone = 'up'; res.kg = work; res.reps = sets.map((x, k) => x[1] + 1);
      res.text = lt === 'extra' ? `Все подходы на верхней границе (${prevList}). Добавьте отягощение или замедлите опускание до 4 с.` : `Все подходы на верхней границе (${prevList}). Возьмите ленту потуже.`;
    }
    return res;
  }
  if (anyLow) {
    const before = past.length > 1 ? past[past.length - 2].s.filter(Boolean) : [];
    const bWork = before.length ? Math.max(0, ...before.map(x => x[0] || 0)) : 0;
    const lowAgain = work && bWork === work && before.filter(x => x[0] === work).some(x => x[1] < lo);
    if (lt === 'kg' && work && lowAgain) {
      res.tone = 'down'; res.kg = roundTo(work * 0.9, step); res.reps = sets.map(() => lo);
      res.text = `Две тренировки подряд меньше ${lo}${unit} — снизьте до ${fmtKg(res.kg)} кг и наберите повторы.`;
    } else if (lt === 'assist' && work != null && lowAgain) {
      res.tone = 'down'; res.kg = work + step; res.reps = sets.map(() => lo);
      res.text = `Две тренировки подряд меньше ${lo} — увеличьте противовес до ${fmtKg(res.kg)} кг и наберите повторы.`;
    } else {
      res.tone = 'same'; res.kg = work; res.reps = sets.map(x => Math.max(lo, x[1]));
      res.text = `${work ? `Оставьте ${fmtKg(work)} кг` : 'Тот же вариант'} и доберите до ${lo}${unit} в каждом подходе. В прошлый раз: ${prevList}.`;
    }
    return res;
  }
  res.tone = 'same'; res.kg = work; res.reps = sets.map(x => Math.min(hi, x[1] + 1));
  res.text = `${work ? `${lt === 'assist' ? 'Тот же противовес' : 'Тот же вес'} — ${fmtKg(work)} кг` : 'Тот же вариант'}, цель — на 1${unit || ' повтор'} больше: в прошлый раз ${prevList}.`;
  return res;
}

/* ---------- блок записи в карточке ---------- */
const SUG_ICON = {up:'↑', same:'→', down:'↓', deload:'↓', new:'+', plan:'≡'};
function logRows(it) {
  const ex = it.ex, lt = loadType(ex), sg = suggest(it), wl = weightLabel(it), lr = lrOn(ex);
  const today = todaySession(ex.id, false);
  const tset = today ? today.s : [];
  const n = Math.max(it.rx.circ ? (it.rounds || it.rx.sets) : it.rx.sets, tset.length);
  const prevSets = sg.prev ? sg.prev.s.filter(Boolean) : [];
  const [lo, hi] = parseRange(it.rx.reps);
  const SIDE = {l:'левая', r:'правая'};
  /* поле веса и повторов; side — 'l' | 'r' в режиме Л/П */
  const fields = (k, side, val, phKg, phR) => `${lt === 'none' ? '' : `<input class="lt-in" id="kg-${ex.id}-${k}${side ? '-' + side : ''}" data-f="kg"${side ? ` data-side="${side}"` : ''} type="text" inputmode="decimal" autocomplete="off" aria-label="${wl.full}${side ? ', ' + SIDE[side] : ''}, подход ${k + 1}" placeholder="${phKg}" value="${val && val[0] != null ? fmtKg(val[0]) : ''}">`}
      <input class="lt-in" id="rp-${ex.id}-${k}${side ? '-' + side : ''}" data-f="reps"${side ? ` data-side="${side}"` : ''} type="text" inputmode="numeric" autocomplete="off" aria-label="${repLabel(ex)}${side ? ', ' + SIDE[side] : ''}, подход ${k + 1}" placeholder="${phR}" value="${val ? val[1] : ''}">`;
  const prevText = p => (p[0] ? fmtKg(p[0]) + ' × ' : '') + p[1];
  const sideTag = side => `<b class="lt-sd" aria-hidden="true">${side === 'l' ? 'Л' : 'П'}</b><span class="vh">${side === 'l' ? 'Левая:' : 'Правая:'}</span>`;
  let rows = '';
  for (let k = 0; k < n; k++) {
    const v = tset[k];
    const p = prevSets[k] || prevSets[prevSets.length - 1];
    const pk = planKg(it.rx, k), phKg = pk != null ? fmtKg(pk) : sg.kg != null ? fmtKg(sg.kg) : (lt === 'kg' ? '' : '—');
    const phR = sg.reps[k] ?? sg.reps[sg.reps.length - 1] ?? (lo === hi ? String(lo) : `${lo}–${hi}`);
    const done = !!v, cls = `lt-r${done ? ' done' : ''}${lr ? ' lt-lr' : ''}${it.rx.static && k > 0 && k % 3 === 0 ? ' lt-series' : ''}`;
    const ok = `<button type="button" class="lt-ok" data-tick="${ex.id}" data-k="${k}" aria-pressed="${done}" aria-label="Подход ${k + 1} выполнен">${ICON.check}</button>`;
    if (lr) {
      /* Л/П: две строки в одном подходе; прошлый раз — по сторонам, если они были записаны, иначе общее значение */
      const sd = v && setSides(v, ex), psd = p && setSides(p, ex);
      const val = side => v ? (sd ? sd[side] : [v[0], v[1]]) : null, pv = side => p ? prevText(psd ? psd[side] : p) : '—';
      rows += `<div class="${cls}" data-k="${k}">
      <span class="lt-n">${k + 1}</span><span class="lt-p">${sideTag('l')} ${pv('l')}</span>
      ${fields(k, 'l', val('l'), phKg, phR)}
      ${ok}
      <span class="lt-p">${sideTag('r')} ${pv('r')}</span>
      ${fields(k, 'r', val('r'), phKg, phR)}
    </div>`;
    } else rows += `<div class="${cls}" data-k="${k}">
      <span class="lt-n">${k + 1}</span><span class="lt-p">${p ? prevText(p) : '—'}</span>
      ${fields(k, null, done ? v : null, phKg, phR)}
      ${ok}
    </div>`;
  }
  const doneN = tset.slice(0, n).filter(Boolean).length;
  /* вес одной гантели: подсказка «×2 = 40 кг» — по первому заполненному полю (пока не вводили — по подсказке) */
  const x2 = wl && wl.n > 1 && !lr ? `<span class="lt-x2" data-n="${wl.n}">${wl.impl === 'kb' ? 'вес — одной гири' : 'вес — одной гантели'}<b>${pairTotalText(wl.n, firstKg(tset, sg, it))}</b></span>` : '';
  const lrBtn = perSide(ex) ? `<button type="button" class="lt-lrb" data-lr="${ex.id}" aria-pressed="${lr}">${'Л/П отдельно'}</button>` : '';
  const perSideNote = perSide(ex) ? `<span>${ex.kind === 'time' ? 'секунды — на каждую сторону' : 'повторы — на каждую сторону'}</span>` : '';
  return {sg, html:`<p class="sug sug-${sg.tone}"><b aria-hidden="true">${SUG_ICON[sg.tone]}</b><span>${esc(sg.text)}</span></p>
    ${logFoldBar(it, n, doneN)}
    <div class="lt-fold" id="lt-${ex.id}"><div class="lt${lt === 'none' ? ' lt-nokg' : ''}" role="group" aria-label="Запись подходов">
      <div class="lt-h"><span>№</span><span>Прошлый раз</span>${lt === 'none' ? '' : `<span title="${wl.full}">${wl.short}</span>`}<span>${repLabel(ex)}</span><span></span></div>
      ${rows}
    </div>
    <div class="lt-foot"><button type="button" class="lt-add" data-addset="${ex.id}">+ подход</button>${lrBtn}${perSideNote}${x2}${it.rx.circ ? '<span>строка — один круг</span>' : ''}</div></div>`};
}
/* вес для подсказки «×2»: записанный или введённый в первом подходе, иначе подсказка по весу */
function firstKg(tset, sg, it) {
  const v = tset.find(x => x && x[0] > 0);
  if (v) return v[0];
  const pk = planKg(it.rx, 0);
  return pk != null ? pk : sg.kg;
}
function logBlock(it) { return `<div class="c-log" data-log="${it.ex.id}">${logRows(it).html}</div>`; }

/* ---------- история упражнения ---------- */
function metricOf(ex) {
  /* расчётный максимум по медленным подходам без расслабления занижен — статодинамика в него не входит */
  if (loadType(ex) === 'kg' && ex.kind !== 'dist') return {name:'Расчётный максимум', unit:'кг', f:s => { if (s.fmt === 'static') return null; const v = s.s.filter(x => x && x[0] > 0).map(x => e1rm(x[0], x[1])); return v.length ? Math.max(...v) : null; }};
  if (ex.kind === 'time') return {name:'Лучший подход', unit:'с', f:s => { const v = s.s.filter(Boolean).map(x => x[1]); return v.length ? Math.max(...v) : null; }};
  if (ex.kind === 'dist') return {name:'Лучшая дистанция', unit:'м', f:s => { const v = s.s.filter(Boolean).map(x => x[1]); return v.length ? Math.max(...v) : null; }};
  return {name:'Лучший подход', unit:'повт.', f:s => { const v = s.s.filter(Boolean).map(x => x[1]); return v.length ? Math.max(...v) : null; }};
}
function sparkSvg(pts, unit, step = 0.5) {
  if (!pts.length) return '';
  const W = 300, H = 74, L = 6, R = 40, T = 12, B = 14;
  const vs = pts.map(p => p.v);
  let mn = Math.min(...vs), mx = Math.max(...vs);
  if (mx - mn < 1e-9) { mn -= 1; mx += 1; }
  const pad = (mx - mn) * 0.12; mn -= pad; mx += pad;
  const x = i => pts.length === 1 ? (L + W - R) / 2 : L + i * (W - L - R) / (pts.length - 1);
  const y = v => T + (1 - (v - mn) / (mx - mn)) * (H - T - B);
  const line = pts.map((p, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(p.v).toFixed(1)}`).join('');
  const area = pts.length > 1 ? `${line}L${x(pts.length - 1).toFixed(1)},${H - B}L${x(0).toFixed(1)},${H - B}Z` : '';
  const last = pts[pts.length - 1], first = pts[0];
  const fv = v => fmtKg(Math.round(v / step) * step);
  const data = esc(JSON.stringify(pts.map((p, i) => [x(i), y(p.v), `${fmtDay(p.d, true)} · ${fv(p.v)} ${unit}`])));
  return `<svg class="spark" viewBox="0 0 ${W} ${H}" role="img" aria-label="Динамика: от ${fv(first.v)} до ${fv(last.v)} ${unit}" data-pts="${data}">
    <line class="sp-base" x1="${L}" x2="${W - R}" y1="${H - B}" y2="${H - B}"/>
    ${area ? `<path class="sp-area" d="${area}"/>` : ''}
    ${pts.length > 1 ? `<path class="sp-line" d="${line}"/>` : ''}
    <circle class="sp-end" cx="${x(pts.length - 1).toFixed(1)}" cy="${y(last.v).toFixed(1)}" r="4"/>
    <text class="sp-lab" x="${(x(pts.length - 1) + 8).toFixed(1)}" y="${(y(last.v) + 4).toFixed(1)}">${fv(last.v)}</text>
    ${pts.length > 1 ? `<text class="sp-d" x="${L}" y="${H - 2}">${fmtDay(first.d, true)}</text><text class="sp-d" x="${W - R}" y="${H - 2}" text-anchor="end">${fmtDay(last.d, true)}</text>` : ''}
    <line class="sp-x" x1="0" x2="0" y1="${T - 4}" y2="${H - B}" visibility="hidden"/><circle class="sp-dot" r="4" cx="0" cy="0" visibility="hidden"/>
  </svg>`;
}
/* подходы записи и её общий вес второй строкой (если есть внешний вес) */
function histSets(ex, s) {
  const t = sessionTonnage(ex, s);
  return `${setsText(s.s, ex)}${t > 0 ? `<small class="h-ton">${'общий вес ' + fmtTon(t) + ' кг'}</small>` : ''}`;
}
function histHtml(ex) {
  const ss = (LOG.data[ex.id] || []).filter(x => x.s.some(Boolean));
  if (!ss.length) return `<p class="h-empty">Записей пока нет. Отметьте подходы выше — здесь появится история и график.</p>${variantHistNote(ex)}`;
  const m = metricOf(ex);
  const pts = ss.map(s => ({d:s.d, v:m.f(s)})).filter(p => p.v != null).slice(-24);
  const best = pts.length ? Math.max(...pts.map(p => p.v)) : null;
  const rows = ss.slice(-6).reverse().map(s => `<li><span class="h-d">${fmtDay(s.d, true)}${s.wk ? `<small>нед. ${s.wk}</small>` : ''}${s.fmt === 'static' ? '<small>статодинамика</small>' : ''}</span>
    <span class="h-s">${histSets(ex, s)}</span>
    <button type="button" class="h-del" data-del="${ex.id}" data-d="${s.d}" aria-label="Удалить запись за ${fmtDay(s.d, true)}">Удалить</button></li>`).join('');
  return `<div class="h-chart"><p class="h-cap">${m.name}, ${m.unit}${best != null ? ` · лучший ${fmtKg(Math.round(best * 2) / 2)}` : ''}</p>${sparkSvg(pts, m.unit)}</div>
    <ul class="h-list">${rows}</ul>${ss.length > 6 ? `<p class="h-more">Всего записей: ${ss.length}. Полная история — в разделе «Журнал».</p>` : ''}${variantHistNote(ex)}`;
}
function histCount(id) { return (LOG.data[id] || []).filter(x => x.s.some(Boolean)).length; }

/* ---------- обновление на странице ---------- */
function refreshCard(card) {
  if (!plan || !plan.items) return;
  const it = plan.items.find(x => x.ex.id === card.dataset.ex);
  if (!it) return;
  const box = card.querySelector('.c-log');
  const ae = document.activeElement;
  if (box && !(box.contains(ae) && ae.tagName === 'INPUT')) {
    const refocus = !box.contains(ae) ? null : ae.dataset.k !== undefined ? `[data-${ae.dataset.tick ? 'tick' : 'addset'}][data-k="${ae.dataset.k}"]`
      : ae.dataset.cfold ? '[data-cfold]' : ae.dataset.hist ? '[data-hist]' : ae.dataset.lr ? '[data-lr]' : null;
    box.innerHTML = logRows(it).html;
    syncCardLog(card);
    if (refocus) { const n = box.querySelector(refocus); if (n) n.focus(); }
  }
  refreshWarmup(card);
  const pg = card.querySelector('.c-prog'); if (pg) pg.innerHTML = progressionHint(it);
  const h = card.querySelector('.c-hist');
  if (h && !h.hidden) h.innerHTML = histHtml(it.ex);
  const hb = card.querySelector('[data-hist]');
  if (hb) { const n = histCount(it.ex.id); hb.querySelector('small').textContent = n ? n : ''; }
}
function logRefresh(ids) {
  const st = $('#log-status'); if (st) st.innerHTML = statusHtml();
  const tab = document.querySelector('[data-view="journal"] small'); if (tab) tab.textContent = journalDays() || '';
  if (S.view === 'journal') { if (!$('#plan').contains(document.activeElement) || document.activeElement === document.body) renderJournal(); return; }
  document.querySelectorAll('.card').forEach(c => { if (!ids || ids.includes(c.dataset.ex)) refreshCard(c); });
}
function statusHtml() {
  const m = LOG.mode;
  const t = m === 'cloud' ? 'Записи сохраняются в вашем аккаунте и доступны на любом устройстве, где вы открываете эту страницу.'
    : m === 'connecting' ? 'Подключаю хранилище записей…'
    : 'Записи хранятся в этом браузере. Делайте резервную копию, чтобы перенести журнал на другое устройство или не потерять его при очистке браузера.';
  return `<span class="ls-dot ls-${m}" aria-hidden="true"></span><span>${LOG.err ? esc(LOG.err) + ' Делайте резервную копию, чтобы не потерять записи.' : t}</span>`;
}
function journalDays() { const s = new Set(); for (const ss of Object.values(LOG.data)) for (const x of ss) if (x.s.some(Boolean)) s.add(x.d); return s.size; }

/* ---------- экран «Журнал» ---------- */
/* тренировки по дням: упражнений, подходов и общий вес за день */
function trainingDays(data = LOG.data) {
  const by = {};
  for (const [id, ss] of Object.entries(data || {})) {
    const ex = EXI[id]; if (!ex || !Array.isArray(ss)) continue;
    for (const s of ss) {
      const n = s && Array.isArray(s.s) ? s.s.filter(Boolean).length : 0; if (!n) continue;
      const d = by[s.d] || (by[s.d] = {d:s.d, ex:0, sets:0, t:0});
      d.ex++; d.sets += n; d.t += sessionTonnage(ex, s);
    }
  }
  return by;
}
/* последние тренировки списком: дата, упражнений и подходов, общий вес за день */
function daysHtml(by = trainingDays(), limit = 5) {
  const days = Object.values(by).sort((a, b) => a.d < b.d ? 1 : -1).slice(0, limit);
  if (!days.length) return '';
  return `<div class="j-days"><p class="lb-h">${'Последние тренировки · общий вес'}</p><ul>${days.map(x => `<li><span class="j-dd">${fmtDay(x.d, true)}</span><span class="j-dn">${x.ex} ${plural(x.ex, 'упражнение', 'упражнения', 'упражнений')} · ${x.sets} ${plural(x.sets, 'подход', 'подхода', 'подходов')}</span><b class="j-dt">${x.t > 0 ? fmtTon(x.t) + `<small>${'кг'}</small>` : '—'}</b></li>`).join('')}</ul></div>`;
}
function heatmap(today = new Date(), by = trainingDays()) {
  const byDay = {};
  for (const x of Object.values(by)) byDay[x.d] = x.sets;
  const W = 12, cell = 15, gap = 3, LX = 22, TY = 16;
  const now = new Date(today); now.setHours(12, 0, 0, 0);
  const dow = (now.getDay() + 6) % 7;
  const start = new Date(now); start.setDate(now.getDate() - dow - (W - 1) * 7);
  let cells = '', lastM = -1;
  const marks = [];
  for (let w = 0; w < W; w++) for (let d = 0; d < 7; d++) {
    const dt = new Date(start); dt.setDate(start.getDate() + w * 7 + d);
    if (dt > now) continue;
    const k = dayKey(dt), n = byDay[k] || 0;
    const lv = n === 0 ? 0 : n < 10 ? 1 : n < 20 ? 2 : 3;
    const t = n && by[k] ? by[k].t : 0;
    cells += `<rect class="hm hm${lv}" x="${LX + w * (cell + gap)}" y="${TY + d * (cell + gap)}" width="${cell}" height="${cell}" rx="3" data-tip="${fmtDay(k, true)}: ${n ? n + ' ' + plural(n, 'подход', 'подхода', 'подходов') + (t > 0 ? ` · ${fmtTon(t)} кг` : '') : 'без тренировки'}"/>`;
    if (d === 0 && dt.getMonth() !== lastM) { lastM = dt.getMonth(); marks.push([w, lastM]); }
  }
  /* подпись месяца — над его первой неделей; хвост прошлого месяца в первой колонке подписывается, только если до
     следующей подписи не меньше двух колонок (иначе подписи наезжают: «июлавг») */
  const months = marks.filter(([w], i) => i + 1 >= marks.length || marks[i + 1][0] - w >= 2)
    .map(([w, m]) => w < W - 1 ? `<text class="hm-l" x="${LX + w * (cell + gap)}" y="10">${MONTHS[m]}</text>`
      : `<text class="hm-l" x="${LX + W * (cell + gap) - gap}" y="10" text-anchor="end">${MONTHS[m]}</text>`).join(''); /* в последней колонке — по правому краю, не обрезается */
  const days = ['Пн', '', 'Ср', '', 'Пт', '', ''].map((t, i) => t ? `<text class="hm-l" x="0" y="${TY + i * (cell + gap) + 11}">${t}</text>` : '').join('');
  const w = LX + W * (cell + gap), h = TY + 7 * (cell + gap);
  return `<svg class="heat" viewBox="0 0 ${w} ${h}" role="img" aria-label="Тренировочные дни за 12 недель">${months}${days}${cells}</svg>
    <p class="hm-legend"><span>меньше</span><i class="hm0"></i><i class="hm1"></i><i class="hm2"></i><i class="hm3"></i><span>больше подходов за день</span></p>`;
}
function renderJournal() {
  stopFigures();
  const entries = Object.entries(LOG.data).map(([id, ss]) => [id, ss.filter(x => x.s.some(Boolean))]).filter(([id, ss]) => EXI[id] && ss.length);
  const days = journalDays();
  const sets = entries.reduce((a, [, ss]) => a + ss.reduce((b, x) => b + x.s.filter(Boolean).length, 0), 0);
  const last = entries.reduce((m, [, ss]) => ss[ss.length - 1].d > m ? ss[ss.length - 1].d : m, '');
  const byDays = trainingDays();
  entries.sort((a, b) => a[1][a[1].length - 1].d < b[1][b[1].length - 1].d ? 1 : -1);
  const tools = `<div class="j-tools">
      ${LOG.canExport ? `<button type="button" class="btn btn-2" id="exp-json">Полная копия (JSON)</button><button type="button" class="btn btn-2" id="exp-csv">Журнал для Excel</button><button type="button" class="btn btn-2" id="exp-body">Замеры для Excel</button>` : ''}
      <label class="btn btn-2" for="imp-file">Восстановить из копии</label><input type="file" id="imp-file" accept=".json,application/json" hidden>
    </div><p class="p-hint" id="j-msg" role="status"></p>
    <p class="p-hint">Полная копия — настройки, инвентарь, журнал и замеры одним файлом: перенесёт всё на другой телефон или вернёт после очистки браузера.</p>`;
  let html = `<header class="p-head j-head">
    <div class="p-sum">
      <p class="eyebrow">Журнал</p>
      <h1 class="p-title">Ваш прогресс</h1>
      <dl class="stats">
        <div><dt>${plural(days, 'тренировка', 'тренировки', 'тренировок')}</dt><dd>${days}</dd></div>
        <div><dt>${plural(sets, 'подход', 'подхода', 'подходов')}</dt><dd>${sets}</dd></div>
        <div><dt>${plural(entries.length, 'упражнение', 'упражнения', 'упражнений')}</dt><dd>${entries.length}</dd></div>
      </dl>
      <p class="ls" id="log-status">${statusHtml()}</p>
      ${tools}
    </div>
    <figure class="j-heat"><figcaption class="lb-h">Активность за 12 недель${last ? ` · последняя тренировка ${fmtDay(last, true)}` : ''}</figcaption>${heatmap(new Date(), byDays)}${daysHtml(byDays)}</figure>
  </header>${entries.length ? muscleLoadHtml() : ''}${bodyHtml()}`;
  if (!entries.length) {
    html += `<div class="empty"><h2>Записей пока нет</h2><p>Откройте план и отмечайте подходы в карточках упражнений: вес и повторы сохранятся здесь, а планировщик начнёт подсказывать, когда прибавлять вес.</p><button type="button" class="btn" data-view="plan">Перейти к плану</button></div>`;
  } else {
    html += `<ul class="j-list">${entries.map(([id, ss]) => {
      const ex = EXI[id], m = metricOf(ex);
      const vals = ss.map(s => m.f(s)).filter(v => v != null);
      const firstV = vals[0], lastV = vals[vals.length - 1];
      const ch = vals.length > 1 && firstV ? Math.round((lastV / firstV - 1) * 100) : null;
      const lastS = ss[ss.length - 1];
      return `<li class="j-row">
        <details>
          <summary>
            <span class="j-name">${esc(ex.name)}<small>${GN[ex.g]} · ${ss.length} ${plural(ss.length, 'запись', 'записи', 'записей')} · ${fmtDay(lastS.d, true)}</small></span>
            <span class="j-val">${lastV != null ? fmtKg(Math.round(lastV * 2) / 2) : '—'}<small>${m.unit}</small>${ch != null ? `<em class="${ch > 0 ? 'pos' : ch < 0 ? 'neg' : ''}">${ch > 0 ? '+' : ''}${ch}%</em>` : ''}</span>
          </summary>
          <div class="j-body">${histHtml(ex).replace(/<p class="h-more">.*?<\/p>/, '')}${ss.length > 6 ? `<details class="j-all"><summary>Все записи (${ss.length})</summary><ul class="h-list">${ss.slice(0, -6).reverse().map(s => `<li><span class="h-d">${fmtDay(s.d, true)}</span><span class="h-s">${histSets(ex, s)}</span><button type="button" class="h-del" data-del="${id}" data-d="${s.d}">Удалить</button></li>`).join('')}</ul></details>` : ''}</div>
        </details>
      </li>`;
    }).join('')}</ul>
    <p class="legend">Расчётный максимум — вес, который вы, по формуле Эпли, подняли бы один раз: вес × (1 + повторы / 30). Он растёт и когда прибавляете вес, и когда делаете больше повторов с тем же весом. У гантелей и гирь он — по весу одного снаряда.</p>
    <p class="legend">Общий вес — сумма «вес × повторы» по всем снарядам и сторонам: жим гантелей 2 × 20 кг на 10 повторов — 400 кг, тяга гантели одной рукой 30 кг по 10 на каждую сторону — 600 кг. Считается только внешний вес: гантели, гири, штанга, тренажёр, доп. вес; вес тела, противовес гравитрона, удержания на время и дистанция не входят. Л/П — подход с левой и правой стороной отдельно: прогресс и рекорды — по слабой стороне.</p>`;
  }
  $('#plan').innerHTML = html;
}
function viewTabs() {
  const n = journalDays(), v = ['atlas', 'journal'].includes(S.view) ? S.view : 'plan';
  const tab = (id, label, extra = '') => `<button type="button" role="tab" data-view="${id}" aria-selected="${v === id}" class="${v === id ? 'on' : ''}">${label}${extra}</button>`;
  return tab('plan', 'План') + tab('atlas', 'Мышцы') + tab('journal', 'Журнал', ` <small>${n || ''}</small>`);
}

/* ---------- экспорт и восстановление ---------- */
async function saveFile(name, text, mime) {
  if (LOG.dl) {
    try { await LOG.dl.save({filename:name, data:text}); return 'ok'; }
    catch (e) { return e && e.code === 'declined' ? 'declined' : 'fail'; }
  }
  if (!window.claude) {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([text], {type:mime}));
    a.download = name; document.body.appendChild(a); a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1500);
    return 'ok';
  }
  return 'fail';
}
/* Таблица для Excel: подход — строка. Вес — одного снаряда (как записан); «Левая» и «Правая» — у подходов с Л/П
   («12×10», у удержаний — секунды), основные вес и повторы тогда — слабая сторона; общий вес — последний столбец,
   у подходов без внешнего веса пусто. */
function csvText() {
  const rows = [['Дата', 'Упражнение', 'Группа мышц', 'Подход', 'Вес, кг', 'Повторы / секунды / метры', 'Неделя цикла', 'Отдых после подхода, с', 'Левая', 'Правая', 'Общий вес за подход, кг']];
  const all = [], side = p => (p[0] != null ? fmtKg(p[0]) + '×' : '') + p[1];
  for (const [id, ss] of Object.entries(LOG.data)) {
    const ex = EXI[id]; if (!ex) continue;
    for (const s of ss) {
      const impl = sessionImpl(ex, s);
      s.s.forEach((x, k) => {
        if (!x) return;
        const sd = setSides(x, ex), t = setTonnage(ex, x, impl);
        all.push([s.d, ex.name, GN[ex.g], k + 1, x[0] != null ? fmtKg(x[0]) : '', x[1], s.wk || '', restField(x[2]) ?? '', sd ? side(sd.l) : '', sd ? side(sd.r) : '', t > 0 ? fmtKg(t) : '']);
      });
    }
  }
  all.sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : 1);
  return '﻿' + rows.concat(all).map(r => r.map(v => /[;"\n]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : v).join(';')).join('\r\n');
}
async function exportLog(kind) {
  const msg = $('#j-msg'), d = todayKey();
  const r = kind === 'csv' ? await saveFile(`lazy-gym-log-${d}.csv`, csvText(), 'text/csv')
    : await saveFile(`lazy-gym-kopiya-${d}.json`, JSON.stringify(backupObject()), 'application/json');
  if (msg) msg.textContent = r === 'ok' ? (kind === 'csv' ? 'Таблица сохранена. Откройте её в Excel: столбцы разделены точкой с запятой.' : 'Полная копия сохранена. Восстановить из неё всё можно здесь же, на любом устройстве.')
    : r === 'declined' ? 'Сохранение отменено.' : 'Сохранить файл не удалось.';
}
function importLog(file) {
  const msg = $('#j-msg');
  const rd = new FileReader();
  rd.onload = () => {
    let obj; try { obj = JSON.parse(rd.result); } catch (e) { obj = null; }
    if (!obj || obj.app !== 'podhod' || (!obj.log && !obj.body && !obj.settings)) { if (msg) msg.textContent = 'Это не резервная копия Lazy Gym Planner. Выберите файл lazy-gym-kopiya-….json.'; return; }
    const r = restoreBackup(obj);
    renderJournal();
    const m2 = $('#j-msg');
    const parts = [];
    if (r.exercises) parts.push(`записей журнала: ${r.sessions} (упражнений: ${r.exercises})`);
    if (r.body > 0) parts.push(`замеров: ${r.body}`);
    if (r.settings) parts.push('настройки');
    if (m2) m2.textContent = parts.length ? `Восстановлено: ${parts.join(', ')}. Совпадающие даты объединены.` : 'Нового в копии нет — всё из неё уже есть.';
  };
  rd.readAsText(file);
}

/* ---------- всплывающая подсказка для графиков ---------- */
const tipEl = document.createElement('div'); tipEl.className = 'tip'; tipEl.hidden = true; document.body.appendChild(tipEl);
function showTip(text, cx, cy) {
  tipEl.textContent = text; tipEl.hidden = false;
  const r = tipEl.getBoundingClientRect();
  tipEl.style.left = Math.max(8, Math.min(innerWidth - r.width - 8, cx - r.width / 2)) + 'px';
  tipEl.style.top = Math.max(8, cy - r.height - 12) + 'px';
}
document.addEventListener('pointermove', e => {
  const sp = e.target.closest && e.target.closest('.spark');
  if (sp) {
    const pts = JSON.parse(sp.dataset.pts || '[]'); if (!pts.length) return;
    const b = sp.getBoundingClientRect(), vb = sp.viewBox.baseVal, sx = b.width / vb.width;
    const px = (e.clientX - b.left) / sx;
    let bi = 0; pts.forEach((p, i) => { if (Math.abs(p[0] - px) < Math.abs(pts[bi][0] - px)) bi = i; });
    const p = pts[bi], xl = sp.querySelector('.sp-x'), dot = sp.querySelector('.sp-dot');
    xl.setAttribute('x1', p[0]); xl.setAttribute('x2', p[0]); xl.setAttribute('visibility', 'visible');
    dot.setAttribute('cx', p[0]); dot.setAttribute('cy', p[1]); dot.setAttribute('visibility', 'visible');
    showTip(p[2], b.left + p[0] * sx, b.top + p[1] * (b.height / vb.height));
    return;
  }
  const c = e.target.closest && e.target.closest('[data-tip]');
  if (c) { const b = c.getBoundingClientRect(); showTip(c.dataset.tip, b.left + b.width / 2, b.top); return; }
  if (!tipEl.hidden) { tipEl.hidden = true; document.querySelectorAll('.spark .sp-x, .spark .sp-dot').forEach(n => n.setAttribute('visibility', 'hidden')); }
}, {passive:true});
document.addEventListener('pointerleave', () => { tipEl.hidden = true; });

/* ---------- действия журнала ---------- */
/* снаряд — в запись дня (по нему считается общий вес: гантели, гиря или штанга у румынской тяги) */
function markImpl(s, it) { if (!hasFreeWeights(it.ex)) return; const impl = itemImpl(it); if (impl) s.eq = impl; else delete s.eq; }
/* поля подхода в строке карточки: side — 'l' | 'r' в режиме Л/П, иначе null */
function rowFields(row, side) {
  const q = f => row.querySelector(side ? `[data-f="${f}"][data-side="${side}"]` : `[data-f="${f}"]:not([data-side])`);
  return {kgIn:q('kg'), rIn:q('reps')};
}
/* значения поля (пустое — подсказка); bad — поле, которое надо заполнить */
function readFields({kgIn, rIn}, lt) {
  const reps = parseNum(rIn.value !== '' ? rIn.value : rIn.placeholder);
  let kg = kgIn ? parseNum(kgIn.value !== '' ? kgIn.value : kgIn.placeholder) : null;
  if (reps == null || reps <= 0) return {bad:rIn};
  if (lt === 'kg' && kg == null && kgIn) return {bad:kgIn};
  if (kg != null && kg < 0) kg = null;
  return {kg, reps:Math.round(reps * 10) / 10};
}
function tickSet(btn) {
  const id = btn.dataset.tick, k = +btn.dataset.k;
  const row = btn.closest('.lt-r');
  const it = plan.items.find(x => x.ex.id === id);
  const lt = loadType(it.ex), lr = row.classList.contains('lt-lr');
  const F = (lr ? ['l', 'r'] : [null]).map(side => rowFields(row, side));
  const s = todaySession(id, true);
  if (s.s[k]) {
    s.s[k] = null; cleanToday(id);
    row.classList.remove('done'); btn.setAttribute('aria-pressed', 'false');
    for (const f of F) { if (f.kgIn) f.kgIn.value = ''; f.rIn.value = ''; }
    logTouch(id); refreshHist(id); return;
  }
  const got = F.map(f => readFields(f, lt)), bad = got.find(g => g.bad);
  if (bad) {
    cleanToday(id);
    bad.bad.focus(); bad.bad.classList.add('need'); setTimeout(() => bad.bad.classList.remove('need'), 1600);
    return;
  }
  while (s.s.length < k) s.s.push(null);
  s.s[k] = lr ? makeSidedSet([got[0].kg, got[0].reps], [got[1].kg, got[1].reps], it.ex) : [got[0].kg, got[0].reps];
  s.target=Math.max(s.target||0,it.rx.circ?(it.rounds||it.rx.sets):it.rx.sets);
  if (it.rx.static) s.fmt = 'static';
  markImpl(s, it);
  F.forEach((f, i) => { if (f.kgIn) f.kgIn.value = got[i].kg != null ? fmtKg(got[i].kg) : ''; f.rIn.value = got[i].reps; });
  row.classList.add('done'); btn.setAttribute('aria-pressed', 'true');
  logTouch(id); refreshHist(id);
  const total = it.rx.circ ? 0 : it.rx.sets;
  const doneN = s.s.filter(Boolean).length;
  if (!it.rx.circ) {
    const r = restAfter(it.rx, doneN - 1);
    if (r) startRest(r, doneN >= total ? 'Отдых перед следующим упражнением' : it.rx.static && doneN % 3 === 0 ? `Отдых после серии ${doneN / 3}` : `Отдых после подхода ${doneN}`);
  }
}
function editSet(inp) {
  const row = inp.closest('.lt-r'); if (!row || !row.classList.contains('done')) return;
  const box = inp.closest('.c-log'), id = box.dataset.log, k = +row.dataset.k, ex = EXI[id];
  const s = todaySession(id, false); if (!s || !s.s[k]) return;
  const v = parseNum(inp.value), x = s.s[k], side = inp.dataset.side;
  if (side) {
    /* Л/П: правится одна сторона, основные поля — снова слабая сторона, отдых остаётся */
    const sd = setSides(x, ex), l = sd ? [...sd.l] : [x[0], x[1]], r = sd ? [...sd.r] : [x[0], x[1]], p = side === 'l' ? l : r;
    if (inp.dataset.f === 'kg') p[0] = v != null && v >= 0 ? v : null;
    else if (v != null && v > 0) p[1] = Math.round(v * 10) / 10; else return;
    const nx = makeSidedSet(l, r, ex, x[2]); if (!nx) return;
    s.s[k] = nx;
  } else {
    if (inp.dataset.f === 'kg') x[0] = v != null && v >= 0 ? v : null;
    else if (v != null && v > 0) x[1] = Math.round(v * 10) / 10; else return;
    /* одно значение на обе стороны: прежние стороны больше не верны */
    if (x.length > 3) x.length = restField(x[2]) ? 3 : 2;
  }
  logTouch(id); refreshHist(id);
}
/* «Л/П отдельно» в карточке: запоминается для упражнения, таблица перерисовывается */
function toggleLr(btn) {
  const id = btn.dataset.lr, ex = EXI[id]; if (!ex) return;
  lrSet(ex, !lrOn(ex));
  const box = btn.closest('.c-log'), it = plan && plan.items && plan.items.find(x => x.ex.id === id);
  if (box && it) { box.innerHTML = logRows(it).html; const card = box.closest('.card'); if (card) syncCardLog(card); const b = box.querySelector(`[data-lr="${id}"]`); if (b) b.focus(); }
}
/* «×2 = 40 кг» под таблицей обновляется при вводе веса */
function updatePairTotal(inp) {
  const box = inp.closest('.c-log'), x2 = box && box.querySelector('.lt-x2 b'); if (!x2) return;
  const n = +box.querySelector('.lt-x2').dataset.n, v = parseNum(inp.value !== '' ? inp.value : inp.placeholder);
  x2.textContent = pairTotalText(n, v);
}
function refreshHist(id) {
  const card = document.querySelector(`.card[data-ex="${id}"]`); if (!card) return;
  const h = card.querySelector('.c-hist'); if (h && !h.hidden) h.innerHTML = histHtml(EXI[id]);
  const hb = card.querySelector('[data-hist] small'); if (hb) { const n = histCount(id); hb.textContent = n || ''; }
  logBarUpdate(card);
  const tab = document.querySelector('[data-view="journal"] small'); if (tab) tab.textContent = journalDays() || '';
}
const delArm = {};
function deleteSession(btn) {
  const id = btn.dataset.del, d = btn.dataset.d, key = id + d;
  if (!delArm[key]) {
    delArm[key] = true; btn.textContent = 'Точно удалить?'; btn.classList.add('armed');
    setTimeout(() => { delArm[key] = false; if (btn.isConnected) { btn.textContent = 'Удалить'; btn.classList.remove('armed'); } }, 3500);
    return;
  }
  delArm[key] = false;
  const ss = LOG.data[id]; if (!ss) return;
  const i = ss.findIndex(x => x.d === d); if (i < 0) return;
  ss.splice(i, 1); if (!ss.length) delete LOG.data[id];
  logTouch(id, true);
  if (S.view === 'journal') renderJournal();
  else { const card = document.querySelector(`.card[data-ex="${id}"]`); if (card) refreshCard(card); }
}

document.addEventListener('click', e => {
  const t = e.target.closest('button');
  if (!t) return;
  if (t.dataset.tick) { tickSet(t); return; }
  if (t.dataset.lr) { toggleLr(t); return; }
  if (t.dataset.addset) {
    const id = t.dataset.addset, it = plan.items.find(x => x.ex.id === id);
    it.extra = (it.extra || 0) + 1;
    const box = t.closest('.c-log');
    const n = box.querySelectorAll('.lt-r').length;
    it.rx.sets = Math.max(it.rx.sets, n + 1);
    if (it.rx.circ) it.rounds = Math.max(it.rounds || 0, n + 1);
    box.innerHTML = logRows(it).html; if (box.closest('.card')) syncCardLog(box.closest('.card'));
    const inp = box.querySelector(`.lt-r[data-k="${n}"] .lt-in`); if (inp) inp.focus();
    return;
  }
  if (t.dataset.hist) {
    const card = t.closest('.card'), h = card.querySelector('.c-hist');
    h.hidden = !h.hidden; t.setAttribute('aria-expanded', String(!h.hidden));
    if (!h.hidden) h.innerHTML = histHtml(EXI[card.dataset.ex]);
    return;
  }
  if (t.dataset.del) { deleteSession(t); return; }
  if (t.dataset.view) { S.view = t.dataset.view; saveSettings(); renderSetup(); renderPlan(); window.scrollTo({top:0}); return; }
  if (t.id === 'exp-csv') { exportLog('csv'); return; }
  if (t.id === 'exp-json') { exportLog('json'); return; }
});
document.addEventListener('change', e => {
  if (e.target.id === 'imp-file' && e.target.files && e.target.files[0]) { importLog(e.target.files[0]); e.target.value = ''; }
  else if (e.target.classList && e.target.classList.contains('lt-in')) editSet(e.target);
});
document.addEventListener('input', e => { if (e.target.classList && e.target.classList.contains('lt-in') && e.target.dataset.f === 'kg' && e.target.closest('.c-log')) updatePairTotal(e.target); });
document.addEventListener('keydown', e => {
  if (e.key === 'Enter' && e.target.classList && e.target.classList.contains('lt-in')) {
    e.preventDefault();
    const row = e.target.closest('.lt-r');
    if (row.classList.contains('done')) { editSet(e.target); return; }
    const ins = [...row.querySelectorAll('.lt-in')];
    const i = ins.indexOf(e.target);
    if (i < ins.length - 1) ins[i + 1].focus(); else row.querySelector('.lt-ok').click();
  }
});

/* ===================== ПОДХОД: СНАРЯДЫ, СТОРОНЫ, ОБЩИЙ ВЕС ===================== */
/* Каталог. У каждого упражнения с гантелями или гирей (в eq или opt) — imp: сколько снарядов в руках (1 или 2) и sides:
   как работают стороны. both — обе сразу (жим гантелей лёжа, гоблет); alt — попеременно (подъём гантелей на бицепс,
   обратные выпады); one — одна сторона за раз (тяга гантели одной рукой). У alt и one повторы считаются на каждую
   сторону — это и есть uni. У остальных упражнений стороны — по uni, снаряд один: вес штанги, стека и блока — общий.

   Вес в журнале — вес одного снаряда (так владелец писал и раньше, история не пересчитывается). Рекорды, расчётный
   максимум, подсказки и автонастройка работают по нему, как раньше.

   Л/П — левая и правая сторона отдельно (переключатель у упражнений alt и one). Подход хранится обратно совместимо:
   [кг, повторы, отдых | null, {l:[кг | null, повторы], r:[кг | null, повторы]}]. Основные поля — СЛАБАЯ сторона: по ним
   идут прогрессия, подсказки, рекорды и старые версии приложения. Поле сторон действительно, только если основные поля
   совпадают со слабой стороной: если старая версия исправила вес или повторы, а стороны не тронула, стороны
   отбрасываются при чтении. */
const SIDE_MODES = ['both', 'alt', 'one'];
const sidesOf = ex => SIDE_MODES.includes(ex.sides) ? ex.sides : ex.uni ? 'one' : 'both';
/* повторы на каждую сторону — и переключатель Л/П */
const perSide = ex => sidesOf(ex) !== 'both';
/* попеременно чередуются руки (у каждой своя гантель) — в упражнениях на верх тела; ноги — в упражнениях на ноги,
   и тогда гантели в руках поднимаются в каждом повторе (обратные выпады) */
const armsAlternate = ex => sidesOf(ex) === 'alt' && !LOWER_G.has(ex.g);

/* ---------- чем нагружено упражнение ---------- */
/* снаряд: 'db' — гантели, 'kb' — гиря, 'bb' — штанга, 'x' — доп. вес без гантелей (жилет, пояс) у упражнений, где гантели
   по желанию, null — тренажёр, блок, вес тела */
const IMPLS = ['db', 'kb', 'bb', 'x'];
const FREE_IMPL = id => id === 'db' || id === 'kb' || id === 'bb';
/* у упражнения есть гантели или гиря — его снаряд записывается в журнал (eq у записи), чтобы общий вес считался верно */
const hasFreeWeights = ex => ex.eq.some(g => g.includes('db') || g.includes('kb')) || (ex.opt || []).includes('db') || (ex.opt || []).includes('kb');
/* снаряд по умолчанию — для записей без поля eq: первый из списка (как в полном зале), гантели по желанию — гантели */
function defaultImpl(ex) {
  for (const g of ex.eq) { const f = g.find(FREE_IMPL); if (f) return f; }
  if ((ex.opt || []).includes('db')) return 'db';
  if ((ex.opt || []).includes('kb')) return 'kb';
  return null;
}
/* снаряд карточки плана: выбранный инвентарь (eqIds) и инвентарь по желанию (has) */
function itemImpl(it) {
  const ex = it.ex, ids = it.eqIds;
  if (!Array.isArray(ids)) return defaultImpl(ex);
  for (const id of ['db', 'kb', 'bb']) if (ids.includes(id)) return id;
  for (const id of ['db', 'kb']) if ((ex.opt || []).includes(id)) return it.has && it.has(id) ? id : 'x';
  return null;
}
/* какие снаряды возможны у упражнения (для проверки поля eq записи) */
function implChoices(ex) {
  const out = new Set();
  for (const g of ex.eq) for (const id of g) if (FREE_IMPL(id)) out.add(id);
  for (const id of ex.opt || []) if (id === 'db' || id === 'kb') { out.add(id); out.add('x'); }
  return out;
}
/* снаряд записи журнала */
function sessionImpl(ex, s) { return s && IMPLS.includes(s.eq) && hasFreeWeights(ex) && implChoices(ex).has(s.eq) ? s.eq : defaultImpl(ex); }
/* поле eq записи: пишется у упражнений с гантелями или гирей, проверяется при восстановлении из копии */
function cleanImpl(ex, v) { return hasFreeWeights(ex) && IMPLS.includes(v) && implChoices(ex).has(v) ? v : null; }
/* снарядов в руках при этом снаряде: у гантелей и гири — из каталога, у штанги и прочего — один (вес общий) */
const impCount = (ex, impl) => (impl === 'db' || impl === 'kb') && ex.imp === 2 ? 2 : 1;
/* сколько снарядов поднимается за повтор одной стороны: попеременно руками — одна гантель, иначе все, что в руках */
const impPerRep = (ex, impl) => armsAlternate(ex) ? 1 : impCount(ex, impl);

/* подпись поля веса: полная (режим тренировки) и короткая (столбец таблицы в карточке); n — снарядов в руках */
function weightLabel(it) {
  const lt = loadType(it.ex);
  if (lt === 'none') return null;
  if (lt === 'assist') return {full:'Противовес, кг', short:'Противовес', n:1, impl:null};
  const impl = itemImpl(it), n = impCount(it.ex, impl);
  if (impl === 'db') return {full:n > 1 ? 'Вес одной гантели, кг' : 'Вес гантели, кг', short:'Гантель, кг', n, impl};
  if (impl === 'kb') return {full:n > 1 ? 'Вес одной гири, кг' : 'Вес гири, кг', short:'Гиря, кг', n, impl};
  return lt === 'extra' ? {full:'Доп. вес, кг', short:'Доп. кг', n:1, impl} : {full:'Вес, кг', short:'Вес, кг', n:1, impl};
}
/* «×2 = 40 кг» — вес двух снарядов в руках */
function pairTotalText(n, kg) { return n > 1 && kg > 0 ? `×${n} = ${fmtKg(kg * n)} кг` : ''; }

/* ---------- стороны подхода ---------- */
/* одна сторона: [кг | null, повторы]; кг — не меньше нуля, повторы (секунды, метры) — больше нуля */
function sidePair(p) {
  if (!Array.isArray(p) || p.length < 2) return null;
  const kg = p[0] == null || p[0] === '' ? null : Number(p[0]), reps = Number(p[1]);
  if ((kg !== null && !(Number.isFinite(kg) && kg >= 0 && kg < 1000)) || !(Number.isFinite(reps) && reps > 0 && reps < 100000)) return null;
  return [kg, reps];
}
/* слабая сторона: по расчётному максимуму, если у обеих есть вес; у удержаний, дистанции, противовеса и без веса —
   по повторам (секундам). При равенстве — меньше повторов, затем меньше вес; совсем поровну — левая */
function weakSide(l, r, ex) {
  const lt = loadType(ex), byE1rm = !ex.kind && (lt === 'kg' || lt === 'extra') && l[0] > 0 && r[0] > 0;
  const key = p => byE1rm ? [e1rm(p[0], p[1]), p[1], p[0]] : lt === 'assist' ? [p[1], -(p[0] || 0)] : [p[1], p[0] || 0];
  const a = key(l), b = key(r);
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] < b[i] ? 'l' : 'r';
  return 'l';
}
/* стороны записанного подхода или null: поле сторон проверено, основные поля — слабая сторона */
function setSides(x, ex) {
  if (!Array.isArray(x) || !x[3] || typeof x[3] !== 'object' || !perSide(ex)) return null;
  const l = sidePair(x[3].l), r = sidePair(x[3].r);
  if (!l || !r) return null;
  const w = weakSide(l, r, ex) === 'l' ? l : r;
  return w[0] === (x[0] ?? null) && w[1] === x[1] ? {l, r, weak:w === l ? 'l' : 'r'} : null;
}
/* подход из двух сторон: основные поля — слабая сторона; отдых (третье поле) — если есть, иначе пусто */
function makeSidedSet(l, r, ex, rest) {
  const L = sidePair(l), R = sidePair(r);
  if (!L || !R) return null;
  const w = weakSide(L, R, ex) === 'l' ? L : R, rf = restField(rest);
  return [w[0], w[1], rf || null, {l:L, r:R}];
}
/* подход из копии или чужого источника: [кг, повторы], отдых и стороны — если верны; неверное отбрасывается, подход остаётся */
function cleanSet(v, ex) {
  if (!Array.isArray(v) || !isFinite(+v[1])) return null;
  const o = [v[0] == null || v[0] === '' ? null : +v[0], +v[1]], r = restField(v[2]);
  const sd = ex && setSides([o[0], o[1], null, v[3]], ex);
  if (sd) o.push(r || null, {l:sd.l, r:sd.r}); else if (r) o.push(r);
  return o;
}

/* ---------- общий вес (тоннаж) ---------- */
/* Общий вес подхода, кг = вес одного снаряда × повторы × снарядов в повторе × сторон.
   both — × снарядов: жим гантелей 2 × 20 кг × 10 = 400 кг, гоблет 24 кг × 10 = 240 кг;
   one — × снарядов × 2 стороны: тяга гантели одной рукой 30 кг по 10 на сторону = 600 кг;
   alt руками — у каждой руки своя гантель, сторон две: попеременные сгибания 2 × 12 кг по 10 на руку = 240 кг;
   alt ногами — гантели в руках поднимаются в каждом повторе: обратные выпады с 2 × 10 кг по 10 на ногу = 400 кг.
   Л/П — сумма сторон, каждая — вес × повторы × снарядов в повторе.
   Считается только внешний вес: гантели, гиря, штанга, стек, доп. вес. Вес тела не входит — доля веса тела, которую
   двигает упражнение, разная (отжимания — около двух третей, подтягивания — почти весь), а взвешивания в день тренировки
   может не быть; без доп. веса общий вес — 0. Противовес гравитрона облегчает подход, удержания на время и дистанция —
   не «вес × повторы»: у них тоже 0. */
function tonnageApplies(ex) { const lt = loadType(ex); return !ex.kind && (lt === 'kg' || lt === 'extra'); }
function setTonnage(ex, x, impl = defaultImpl(ex)) {
  if (!Array.isArray(x) || !tonnageApplies(ex)) return 0;
  const n = impPerRep(ex, impl), sd = setSides(x, ex);
  const part = p => p[0] > 0 && p[1] > 0 ? p[0] * p[1] * n : 0;
  if (sd) return part(sd.l) + part(sd.r);
  return part([x[0], x[1]]) * (perSide(ex) ? 2 : 1);
}
function sessionTonnage(ex, s) {
  if (!s || !Array.isArray(s.s)) return 0;
  const impl = sessionImpl(ex, s);
  return s.s.reduce((a, x) => a + (x ? setTonnage(ex, x, impl) : 0), 0);
}
/* общий вес за день по всему журналу */
function dayTonnage(d, data = LOG.data) {
  let t = 0;
  for (const [id, ss] of Object.entries(data || {})) { const ex = EXI[id]; if (ex && Array.isArray(ss)) for (const s of ss) if (s && s.d === d) t += sessionTonnage(ex, s); }
  return t;
}
/* 4320 → «4 320»; в английской сборке — «4,320» */
function fmtTon(v) { return String(Math.round(v)).replace(/\B(?=(\d{3})+(?!\d))/g, DEC === ',' ? ' ' : ','); }

/* ---------- текст подхода ---------- */
const pairText = p => (p[0] ? fmtKg(p[0]) + '×' : '') + p[1];
/* «20×10», с Л/П — «Л 12×10 · П 12×8» */
function setText(x, ex) { const sd = setSides(x, ex); return sd ? `${'Л'} ${pairText(sd.l)} · ${'П'} ${pairText(sd.r)}` : pairText(x); }
/* подходы записи (разметка): через « · »; если есть подход с Л/П — через «; », чтобы стороны не путались с подходами;
   подход с Л/П не переносится посередине */
function setsText(sets, ex) {
  const xs = sets.filter(Boolean), lr = xs.some(x => setSides(x, ex));
  return xs.map(x => lr ? `<span class="h-lr">${setText(x, ex)}</span>` : setText(x, ex)).join(lr ? '; ' : ' · ');
}
/* «слабая сторона — левая: догоняйте её» — если в записи стороны отличались и слабой всё время была одна и та же */
function weakSideNote(ex, s) {
  if (!s || !perSide(ex)) return '';
  const weak = new Set();
  for (const x of s.s || []) { const sd = x && setSides(x, ex); if (sd && (sd.l[0] !== sd.r[0] || sd.l[1] !== sd.r[1])) weak.add(sd.weak); }
  return weak.size === 1 ? (weak.has('l') ? 'Слабая сторона — левая: догоняйте её.' : 'Слабая сторона — правая: догоняйте её.') : '';
}

/* ---------- переключатель Л/П (запоминается для упражнения, по умолчанию выключен) ---------- */
function lrOn(ex) { return perSide(ex) && !!(S.lr && typeof S.lr === 'object' && S.lr[ex.id] === true); }
function lrSet(ex, on) {
  const m = {...(S.lr && typeof S.lr === 'object' ? S.lr : {})};
  if (on) m[ex.id] = true; else delete m[ex.id];
  S.lr = m; saveSettings();
}
/* из копии: только упражнения каталога со сторонами */
function cleanLr(v) {
  const o = {};
  if (v && typeof v === 'object' && !Array.isArray(v)) for (const [k, on] of Object.entries(v)) if (on === true && EXI[k] && perSide(EXI[k])) o[k] = true;
  return o;
}

/* ===================== АТЛАС МЫШЦ =====================
   Обратный путь к упражнениям: сначала мышца, потом движения. Список берётся из инвентаря текущего места;
   то, что требует другого инвентаря, показано отдельно с подсказкой, где оно есть. */
const ATLAS_GROUPS = [
  ['Грудь и плечи', ['chest', 'delt_f', 'delt_s', 'delt_r', 'serratus', 'cuff']],
  ['Руки', ['biceps', 'triceps', 'forearms']],
  ['Спина', ['lats', 'midback', 'traps', 'lowback']],
  ['Корпус', ['abs', 'obliques']],
  ['Ноги', ['glutes', 'quads', 'adductors', 'hipflex', 'hams', 'calves']]
];
const ATLAS_ORDER = ATLAS_GROUPS.flatMap(g => g[1]);
/* что делает мышца — коротко, чтобы было понятно, зачем её тренировать */
const MUSCLE_INFO = {
  chest:'Сводит руки перед собой и опускает их из положения над головой. Верхняя часть сильнее включается в жимах под углом вверх.',
  delt_f:'Поднимает руку вперёд. Помогает во всех жимах — от груди и над головой.',
  delt_s:'Отводит руку в сторону. От неё больше всего зависит ширина плеч.',
  delt_r:'Отводит руку назад и разворачивает плечо наружу. Уравновешивает жимы и держит плечо в правильном положении.',
  biceps:'Сгибает руку в локте и разворачивает ладонь вверх. Помогает во всех тягах.',
  triceps:'Разгибает руку в локте. Длинная головка ещё и отводит плечо назад — поэтому её сильнее растягивают упражнения с рукой над головой.',
  forearms:'Сжимают кисть и держат хват, сгибают и разгибают запястье. Часто первыми устают в тягах.',
  abs:'Сгибает позвоночник и удерживает таз. Не даёт пояснице прогибаться в жимах и планке.',
  obliques:'Поворачивают и наклоняют корпус, удерживают его от скручивания.',
  traps:'Поднимают, сводят и опускают лопатки. Верхняя часть держит плечевой пояс под нагрузкой.',
  midback:'Сводят лопатки. Работают в тягах к поясу и разведениях назад, держат осанку.',
  lats:'Тянут руку вниз и назад к корпусу. Главные мышцы подтягиваний и тяг.',
  lowback:'Держат позвоночник ровным в наклонах, тягах и приседаниях; разгибают корпус.',
  glutes:'Разгибают бедро — выводят из приседа и толкают таз вперёд. Средняя ягодичная удерживает таз и колено на одной линии.',
  quads:'Разгибают колено. Прямая мышца бедра ещё и поднимает бедро вперёд.',
  hams:'Сгибают колено и разгибают бедро. Работают в наклонах от таза и сгибаниях ног.',
  calves:'Поднимают на носки. Икроножная сильнее включается с прямым коленом, камбаловидная — с согнутым.',
  adductors:'Сводят ноги. Большая приводящая ещё и разгибает бедро: в глубоком приседе и выпаде она работает вместе с ягодичными. Прицельно — сведение ног и копенгагенская планка.',
  hipflex:'Поднимают бедро к корпусу — подвздошно-поясничная мышца, прямая мышца бедра, портняжная. Главные мышцы подъёмов ног и коленей.',
  serratus:'Прижимает лопатку к рёбрам, выводит её вперёд и поворачивает вверх. Работает в отжиманиях и жимах над головой.',
  cuff:'Четыре глубокие мышцы вокруг плечевого сустава: держат головку плеча во впадине и вращают руку. Прицельно — вращение плеча наружу; помогают в разведениях назад, «Y-T-W» и тягах сверху.'
};
/* мышцы-помощники: упражнений, где они главная цель, почти нет — в атласе они показаны по упражнениям, в которых работают
   в помощь, а тренировка с акцентом на них не предлагается. Манжета с прицельными упражнениями (вращение плеча наружу
   на блоке и с эспандером) — уже не помощник: у неё есть тренировка с акцентом. */
const ATLAS_SUPPORT = new Set(['serratus']);
/* мышцы задней поверхности: камера для превью ищет их со спины */
const ATLAS_BACK = new Set(['delt_r', 'triceps', 'traps', 'midback', 'lats', 'lowback', 'glutes', 'hams', 'calves', 'cuff']);
let atlasEx = null, atlasCam = null;
/* ракурсы превью: «спереди» и «сзади» — три четверти, так видно и мышцу, и движение */
const ATLAS_CAMS = {angle:'Спереди', rear:'Со спины', side:'Сбоку', above:'Сверху'};

/* пик учебной кривой участия мышцы в упражнении (0…1) */
function atlasPeak(ex, m) {
  const p = motionProfile(ex.anim)?.muscles?.[m];
  if (p) return Math.max(...p.concentric, ...p.eccentric);
  return ex.pri.includes(m) ? .83 : ex.sec.includes(m) ? .6 : 0;
}
/* порядок в списке: мышца — единственная цель выше, чем одна из нескольких; затем выраженность и «полезность» упражнения */
function atlasScore(ex, m) {
  const pri = ex.pri.includes(m), share = pri ? 1 / Math.sqrt(ex.pri.length) : .45;
  /* кардио нагружает мышцы ног, но силовые упражнения для них идут первыми */
  return share * (.6 + .4 * atlasPeak(ex, m)) * Math.sqrt(EX_W[ex.id] ?? 1) * (ex.g === 'cardio' ? .6 : 1) + (pri && ex.pri[0] === m ? .05 : 0);
}
function atlasNeed(ex, E) {
  return ex.eq.filter(g => !g.some(id => E.has(id))).map(g => g.map(id => eqName(id).toLowerCase()).join(' или '));
}
function atlasFor(m, E) {
  const rows = EX.filter(ex => ex.pri.includes(m) || ex.sec.includes(m))
    .map(ex => ({ex, role:ex.pri.includes(m) ? 'pri' : 'sec', v:atlasPeak(ex, m), score:atlasScore(ex, m)}))
    .sort((a, b) => b.score - a.score || a.ex.lvl - b.ex.lvl);
  const here = rows.filter(r => available(r.ex, E));
  const other = rows.filter(r => !available(r.ex, E)).map(r => ({...r, need:atlasNeed(r.ex, E),
    places:S.places.filter(p => p.id !== S.place && available(r.ex, effEquip(p.equip))).map(p => p.name)}));
  return {pri:here.filter(r => r.role === 'pri'), sec:here.filter(r => r.role === 'sec'), other};
}
function atlasCounts(E) {
  const out = {};
  for (const m of ATLAS_ORDER) out[m] = EX.filter(ex => ex.pri.includes(m) && available(ex, E)).length;
  return out;
}
/* акцент тренировки на мышцу: в разовой тренировке её группа добавляется к выбранным */
function setFocus(m) {
  S.focus = m && MUSCLE_NAMES[m] ? m : null;
  if (S.focus && S.mode !== 'program' && !S.groups.includes(MUSCLE_GROUP[S.focus])) {
    S.groups = S.groups.concat(MUSCLE_GROUP[S.focus]).sort((a, b) => GROUPS.findIndex(x => x.id === a) - GROUPS.findIndex(x => x.id === b));
  }
}
/* ракурс превью, с которого мышцу видно: сравниваем направление на камеру с нормалью груди в середине повторения */
function atlasCamera(ex, m) {
  const R = ex.anim.catalogRig ? ex.anim.catalogRig(.5) : null;
  if (!R || !R.n) return ATLAS_BACK.has(m) ? 'back' : 'front';
  const want = (ATLAS_BACK.has(m) ? -1 : 1), n = [R.n[0] * want, -R.n[1] * want, R.n[2] * want];
  let best = 'side', top = .5;
  for (const key of ['angle', 'rear', 'above', 'front', 'back']) {
    const C = CAMERA3[key], y = C.yaw * Math.PI / 180, e = C.elevation * Math.PI / 180;
    const eye = [-Math.sin(y) * Math.cos(e), -Math.sin(e), Math.cos(y) * Math.cos(e)];
    /* три четверти объёмнее плоского вида, но только если мышца к ним действительно повёрнута */
    /* средняя дельта смотрит вбок: её и отведение руки лучше всего видно прямо спереди */
    const d = eye[0] * n[0] + eye[1] * n[1] + eye[2] * n[2], s = d + ((key === 'angle' || key === 'rear') && d > .4 && m !== 'delt_s' ? .5 : 0);
    if (s > top) { top = s; best = key; }
  }
  return best;
}

/* схема для выбора: средняя дельта выделена из передней и задней, каждая мышца — кнопка */
const ATLAS_SPLIT = {
  delt_f:[['delt_f', [[64, 36], [71, 36], [75, 47], [76, 58], [73, 54], [69, 45], [64, 40]]], ['delt_s', [[71, 36], [73, 36], [80, 42], [82, 53], [78, 61], [76, 58], [75, 47]]]],
  delt_r:[['delt_r', [[67, 36], [73, 36.8], [76, 46], [76.5, 55.5], [72, 48]]], ['delt_s', [[73, 36.8], [75, 37], [81, 43], [82, 53], [78, 58], [76.5, 55.5], [76, 46]]]]
};
function atlasMapSvg(sel, counts) {
  const neutral = new Set(['head', 'neck', 'hand', 'pelvis', 'knee', 'foot', 'flank']);
  const view = (shapes, dx, label) => {
    const by = new Map(), base = [];
    for (const [m, kind, d] of shapes) {
      const parts = ATLAS_SPLIT[m] ? ATLAS_SPLIT[m].map(([id, pts]) => [id, 'p', pts]) : [[m, kind, d]];
      for (const [id, k, dd] of parts) for (const q of [dd, mirrorShape(k, dd)]) {
        if (neutral.has(id)) { base.push(shapeSvg(k, q, {class:'mm-n'})); continue; }
        if (!by.has(id)) by.set(id, []);
        by.get(id).push(shapeSvg(k, q, {class:'mm-b'}));
      }
    }
    let s = `<g transform="translate(${dx},0)">${base.join('')}`;
    for (const [id, list] of by) {
      const on = id === sel, none = !counts[id];
      s += `<g class="am-m${on ? ' on' : ''}${none ? ' none' : ''}" data-atlas-m="${id}" role="button" tabindex="0" aria-pressed="${on}" aria-label="${esc(MUSCLE_NAMES[id])}"><title>${esc(MUSCLE_NAMES[id])}</title>${list.join('')}</g>`;
    }
    return s + `<text x="50" y="216" class="mm-l">${label}</text></g>`;
  };
  return `<svg viewBox="0 0 206 222" class="mmap amap" aria-label="Схема мышц: нажмите на мышцу">${view(MAP_FRONT, 0, 'спереди')}${view(MAP_BACK, 106, 'сзади')}</svg>`;
}

function atlasRow(r, m, sel) {
  const ex = r.ex, E = effEquip(S.equip), name = exName(ex, E);
  const others = ex.pri.filter(x => x !== m).map(x => MUSCLE_NAMES[x].toLowerCase());
  const how = r.role === 'pri' ? (others.length ? 'вместе с: ' + others.slice(0, 2).join(', ') : 'главная цель') : 'основная работа: ' + ex.pri.slice(0, 2).map(x => MUSCLE_NAMES[x].toLowerCase()).join(', ');
  return `<li class="at-row${sel ? ' on' : ''}">${favButton(ex.id)}<button type="button" class="at-ex" data-atlas-ex="${ex.id}" aria-pressed="${sel}"><span class="at-sw" style="background:${muscleColor(r.v)}" title="${MUSCLE_BANDS[muscleBand(r.v)]}"></span><span class="at-n"><b>${esc(name)}</b><small>${esc(equipLine(ex, E))} · ${esc(how)}${ex.lvl >= 3 ? ' · сложное' : ''}${unfitHtml(ex)}</small></span></button>`
    + `<button type="button" class="at-open" data-atlas-open="${ex.id}" aria-haspopup="dialog" aria-controls="motion-view" aria-label="Разобрать движение: ${esc(name)}">↗</button></li>`;
}
/* избранное и свой план для упражнения в превью */
function atlasKeepHtml(id) {
  return `${favButton(id, true)}<button type="button" class="btn-ghost" data-cp-add="${id}">+ В свой план</button><p class="cp-msg" hidden><span></span> <button type="button" class="link" data-cp-go="1">Открыть план →</button></p>`;
}
function atlasList(rows, m, sel, limit) {
  return `<ol class="at-list">${rows.map((r, i) => atlasRow(r, m, r.ex.id === sel).replace('<li class="at-row', i >= limit ? '<li hidden class="at-more at-row' : '<li class="at-row')).join('')}</ol>`
    + (rows.length > limit ? `<button type="button" class="at-show" data-atlas-show="1">Показать все: ${rows.length}</button>` : '');
}

function renderAtlas() {
  const m = MUSCLE_NAMES[S.atlasM] ? S.atlasM : 'chest', E = effEquip(S.equip);
  const A = atlasFor(m, E), counts = atlasCounts(E);
  const first = A.pri[0] || A.sec[0];
  if (!atlasEx || ![...A.pri, ...A.sec].some(r => r.ex.id === atlasEx)) { atlasEx = first ? first.ex.id : null; atlasCam = null; }
  const place = placeOf();
  const here = p => { const PE = effEquip(p.equip); return EX.filter(ex => (ex.pri.includes(m) || ex.sec.includes(m)) && available(ex, PE)).length; };
  const name = MUSCLE_NAMES[m], lower = name.toLowerCase();
  let html = `<header class="at-head">
    <p class="eyebrow">Атлас мышц</p>
    <h1 class="p-title">Выберите мышцу</h1>
    <p class="at-lead">Нажмите на мышцу — покажем упражнения, в которых она работает, из инвентаря выбранного места.</p>
    <p class="at-favs"><span>★ В избранном: <b class="at-favn">${S.fav.length}</b></span><button type="button" class="link" data-cp-go="1">Собрать свой план →</button></p>
  </header>
  <div class="at-grid">
    <section class="at-pick" aria-label="Мышцы">
      <div class="at-map">${atlasMapSvg(m, counts)}</div>
      ${ATLAS_GROUPS.map(([g, ids]) => `<h2 class="at-gh">${g}</h2><div class="at-chips">${ids.map(id => `<button type="button" class="at-chip${id === m ? ' on' : ''}${counts[id] ? '' : ' none'}" data-atlas-m="${id}" aria-pressed="${id === m}"><span>${esc(MUSCLE_NAMES[id])}</span><small>${counts[id] || '—'}</small></button>`).join('')}</div>`).join('')}
      <p class="f-note">Число — упражнения с основной нагрузкой на мышцу в месте «${esc(place.name)}».</p>
    </section>
    <section class="at-detail" id="at-detail" aria-labelledby="at-name">
      <h2 class="at-name" id="at-name">${esc(name)}</h2>
      <p class="at-desc">${esc(MUSCLE_INFO[m])}</p>
      <div class="at-where"><span class="at-wl">Упражнений на эту мышцу</span><div class="places at-places" role="group" aria-label="Где тренируетесь">${S.places.map(p => { const n = here(p); return `<button type="button" class="place${p.id === S.place ? ' on' : ''}" data-place="${p.id}" aria-pressed="${p.id === S.place}"><b>${esc(p.name)}</b><small>${n}</small></button>`; }).join('')}</div></div>
      <div class="at-acts">
        ${ATLAS_SUPPORT.has(m) ? '<p class="f-note">Эта мышца работает в помощь основным и отдельной тренировки не требует: она включается в упражнениях ниже.</p>' : `<button type="button" class="btn" data-atlas-focus="${m}">Тренировка с акцентом на эту мышцу →</button>
        ${S.focus === m ? '<span class="at-focus-on">Акцент уже выбран</span>' : ''}`}
      </div>`;
  if (first) {
    const it = previewItem(atlasEx);
    html += `<div class="motion-tile at-tile" id="at-preview">
        <button type="button" class="illus" data-fig="0" aria-haspopup="dialog" aria-controls="motion-view" aria-label="Разобрать движение: ${esc(it.name)}"><span class="at-stage"></span><span class="illus-zoom" aria-hidden="true">Разобрать ↗</span></button>
        <div class="motion-bar"><span class="motion-caption">Исходное положение</span><button type="button" data-motion-pause="0" aria-pressed="true">Пауза</button></div>
      </div>
      <div class="at-under"><p class="at-pv"><b id="at-pv-name">${esc(it.name)}</b></p><div class="at-cams" role="group" aria-label="Ракурс">${Object.entries(ATLAS_CAMS).map(([c, label]) => `<button type="button" data-atlas-cam="${c}" aria-pressed="false">${label}</button>`).join('')}</div></div>
      <div class="at-keep" id="at-keep">${atlasKeepHtml(atlasEx)}</div>
      <p class="at-hint">Оранжевым выделена выбранная мышца: чем ярче цвет, тем сильнее она работает в этот момент повторения.</p>`;
    if (A.pri.length) html += `<h3 class="at-h">Основная нагрузка <small>${A.pri.length}</small></h3>${atlasList(A.pri, m, atlasEx, 8)}`;
    else if (!ATLAS_SUPPORT.has(m)) html += `<p class="warn-inline">Здесь нет упражнений, где ${esc(lower)} — основная цель. Ниже — те, где она помогает, и что нужно для остальных.</p>`;
    if (A.sec.length) html += `<h3 class="at-h">Помогает <small>${A.sec.length}</small></h3>${atlasList(A.sec, m, atlasEx, 5)}`;
  } else {
    html += `<div class="empty"><h2>Здесь нечем нагрузить эту мышцу</h2><p>В месте «${esc(place.name)}» нет подходящего инвентаря. Ниже — что для этого нужно.</p></div>`;
  }
  if (A.other.length) {
    html += `<details class="at-other"><summary>Нужен другой инвентарь <small>${A.other.length}</small></summary><ul class="at-olist">${A.other.map(r => `<li><button type="button" class="at-open at-orow" data-atlas-open="${r.ex.id}" aria-haspopup="dialog" aria-controls="motion-view"><b>${esc(r.ex.name)}</b><small>${r.role === 'pri' ? 'основная' : 'помогает'} · нужно: ${esc(r.need.join('; '))}${r.places.length ? ` · есть: ${esc(r.places.join(', '))}` : ''}</small></button></li>`).join('')}</ul></details>`;
  }
  html += `<p class="legend">Схема и цвет — учебная иллюстрация участия мышц, а не замер электрической активности.</p></section></div>`;
  $('#plan').innerHTML = html;
  mountAtlasPreview(m);
}
function mountAtlasPreview(m = S.atlasM) {
  for (const F of figs) disposeMotion(F);
  figs = [];
  const tile = $('#at-preview');
  if (!tile || !atlasEx) return;
  const it = previewItem(atlasEx), btn = tile.querySelector('.illus');
  const cam = atlasCam || atlasCamera(it.ex, m);
  try {
    const f = createMotionFigure(it.ex.anim, {primary:it.ex.pri, has:it.has, ratio:1.25, t:0, label:it.name, camera:cam, muscles:true});
    f.setRegion?.(m); f.setVectors?.(false); f.setTrace?.(false); f.setJoints?.(false); f.svg.classList.remove('show-joints');
    tile.querySelector('.at-stage').replaceChildren(f.svg);
    const F = {btn, it, f, vis:true, paused:reduceMotion, clock:0, durations:motionDurations(it)};
    figs = [F]; paintMotion(F);
    const pause = tile.querySelector('[data-motion-pause]');
    pause.textContent = F.paused ? 'Пуск' : 'Пауза'; pause.setAttribute('aria-pressed', String(!F.paused));
  } catch (e) { console.error('Атлас', it.ex.id, e); }
  btn.setAttribute('aria-label', 'Разобрать движение: ' + it.name);
  $('#at-pv-name').textContent = it.name;
  /* плоский вид спереди или сзади отмечается на ближайшей кнопке */
  const near = {front:'angle', back:'rear'}[cam] || cam;
  for (const b of document.querySelectorAll('[data-atlas-cam]')) b.setAttribute('aria-pressed', String(b.dataset.atlasCam === near));
  for (const b of document.querySelectorAll('[data-atlas-ex]')) { const on = b.dataset.atlasEx === atlasEx; b.setAttribute('aria-pressed', String(on)); b.parentElement.classList.toggle('on', on); }
  scheduleMotionLoop();
}
function selectAtlasMuscle(m, scroll) {
  if (!MUSCLE_NAMES[m]) return;
  S.atlasM = m; atlasEx = null; atlasCam = null; saveSettings(); renderAtlas();
  if (scroll && window.innerWidth < 900) $('#at-detail').scrollIntoView({block:'start', behavior:reduceMotion ? 'auto' : 'smooth'});
}
document.addEventListener('click', e => {
  if (e.target.closest('[data-focus-clear]')) { setFocus(null); regen(); return; }
  if (S.view !== 'atlas') return;
  const g = e.target.closest('[data-atlas-m]');
  if (g) { selectAtlasMuscle(g.dataset.atlasM, true); return; }
  const t = e.target.closest('button');
  if (!t) return;
  if (t.dataset.atlasEx) { atlasEx = t.dataset.atlasEx; atlasCam = null; mountAtlasPreview(); const k = $('#at-keep'); if (k) k.innerHTML = atlasKeepHtml(atlasEx); return; }
  if (t.dataset.atlasCam) { atlasCam = t.dataset.atlasCam; mountAtlasPreview(); return; }
  if (t.dataset.atlasOpen) { openMotionItem(previewItem(t.dataset.atlasOpen)); return; }
  if (t.dataset.atlasShow) { for (const li of t.previousElementSibling.querySelectorAll('.at-more')) li.hidden = false; t.remove(); return; }
  if (t.dataset.atlasFocus) { setFocus(t.dataset.atlasFocus); S.view = 'plan'; regen(); $('#plan').scrollIntoView({block:'start'}); return; }
});
document.addEventListener('keydown', e => {
  if ((e.key !== 'Enter' && e.key !== ' ') || !e.target.closest) return;
  const g = e.target.closest('g[data-atlas-m]');
  if (!g) return;
  e.preventDefault(); selectAtlasMuscle(g.dataset.atlasM, true);
  const again = document.querySelector(`g[data-atlas-m="${g.dataset.atlasM}"]`); if (again) again.focus();
});

/* ===================== АТЛАС ДВИЖЕНИЙ: ВИТРИНА =====================
   Кнопка «Атлас движений» открывает витрину: все упражнения миниатюрами манекена, по группам мышц. Сверху — фильтр
   «Чем работать» (свободные веса, тренажёры и блоки, резинки, свой вес), «только то, что есть в месте» и поиск.
   Миниатюра открывает подробный разбор в том же окне; «← Все упражнения» возвращает к витрине на то же место.
   «Увеличить» в карточке плана по-прежнему открывает сразу разбор.
   Миниатюра — неподвижный SVG-кадр того же манекена, что в карточках плана (конечная точка движения), строится,
   когда подходит к экрану, — сколько успеется за ~8 мс кадра; готовые миниатюры переиспользуются при смене фильтра. Рамка — по самой
   показанной позе (opts.still), а не по всем фазам: так миниатюра в 4–5 раз дешевле. */
const WORK_KINDS = [
  {id:'all', name:'Всё'}, {id:'free', name:'Свободные веса'}, {id:'mach', name:'Тренажёры и блоки'},
  {id:'band', name:'Резинки'}, {id:'body', name:'Свой вес'}
];
const EQUIP_CAT = Object.fromEntries(EQUIP.map(e => [e.id, e.cat]));
const FREE_WEIGHTS = new Set(['db', 'bb', 'kb']);
/* чем работать: тренажёр или блок важнее всего (без него упражнение не сделать), потом свободный вес, потом резинка;
   без них — свой вес (скамья, турник, брусья, ролик — опора, а не отягощение) */
function workKind(ex) {
  const ids = ex.eq.flat();
  if (ids.some(id => EQUIP_CAT[id] === 'mach')) return 'mach';
  if (ids.some(id => FREE_WEIGHTS.has(id))) return 'free';
  if (ids.includes('band')) return 'band';
  return 'body';
}
const gallery = {kind:'all', here:false, q:'', on:false, scroll:0};
const galleryThumbs = new Map();
let galleryIO = null, galleryQueue = [], galleryRaf = 0;

function galleryList(kind = gallery.kind) {
  const E = effEquip(S.equip), q = gallery.q.trim().toLowerCase();
  return EX.filter(ex => (kind === 'all' || workKind(ex) === kind) && (!gallery.here || available(ex, E)) && (!q || ex.name.toLowerCase().includes(q)));
}
function galleryTile(ex, E, all) {
  const here = available(ex, E), name = exName(ex, here ? E : all), fav = isFav(ex.id);
  const sub = here ? equipLine(ex, E) : `Нет в месте «${placeOf().name}», нужно: ${equipLine(ex, all).toLowerCase()}`;
  return `<button type="button" class="mv-tile${here ? '' : ' off'}" data-gallery-open="${ex.id}"><span class="mv-thumb" data-thumb="${ex.id}" aria-hidden="true"></span>`
    + `<span class="mv-tname">${fav ? '<span class="mv-tfav" aria-label="В избранном">★</span> ' : ''}${esc(name)}</span><span class="mv-tsub">${esc(sub)}</span></button>`;
}
function galleryHtml() {
  const E = effEquip(S.equip), all = effEquip(EQUIP.map(e => e.id)), list = galleryList();
  const chips = WORK_KINDS.map(k => `<button type="button" class="${gallery.kind === k.id ? 'on' : ''}" data-gallery-kind="${k.id}" aria-pressed="${gallery.kind === k.id}">${esc(k.name)} <small>${galleryList(k.id).length}</small></button>`).join('');
  const sections = GROUPS.map(g => {
    const xs = list.filter(ex => ex.g === g.id); if (!xs.length) return '';
    return `<section class="mv-gsec" aria-labelledby="mv-g-${g.id}"><h3 id="mv-g-${g.id}">${esc(g.name)} <small>${xs.length}</small></h3><div class="mv-ggrid">${xs.map(ex => galleryTile(ex, E, all)).join('')}</div></section>`;
  }).join('');
  return `<div class="mv-gtools"><div class="mv-gkinds" role="group" aria-label="Чем работать">${chips}</div>`
    /* «…» вокруг названия места — в одном шаблоне со следующей подписью: перевод закрывающей кавычки идёт вместе с ней */
    + `<div class="mv-gfilters"><label class="mv-ghere"><input type="checkbox" id="mv-ghere"${gallery.here ? ' checked' : ''}> Только то, что есть в месте «${esc(placeOf().name)}»</label><label class="mv-gsearch"><span class="vh">Найти упражнение</span><input type="search" id="mv-gq" value="${esc(gallery.q)}" placeholder="Найти: жим, тяга, присед…" autocomplete="off"></label></div></div>`
    + `<p class="mv-gcount" aria-live="polite">${list.length} ${plural(list.length, 'упражнение', 'упражнения', 'упражнений')}</p>`
    + (sections || `<p class="mv-gempty">Ничего не найдено. Выберите «Всё» или измените поиск.</p>`);
}
function thumbKey(id) { return id + '|' + S.place + '|' + S.equip.join(','); }
/* конечная точка движения узнаётся лучше всего: штанга у груди, присед в нижней точке; у циклических — середина шага */
function thumbT(ex) { return ex.anim.hold ? 0 : ex.anim.loop ? .3 : 1; }
function buildThumb(el) {
  const id = el.dataset.thumb, key = thumbKey(id);
  let svg = galleryThumbs.get(key);
  if (!svg) {
    const it = previewItem(id);
    try { svg = buildFigure(it.ex.anim, {primary:it.ex.pri, has:it.has, ratio:1, camera:'angle', t:thumbT(it.ex), label:it.name, muscles:false, stress:false, still:true}).svg; }
    catch (e) { console.error('Миниатюра', id, e); return; }
    galleryThumbs.set(key, svg);
  }
  el.replaceChildren(svg); el.classList.add('ready');
}
/* за кадр — сколько успеется за ~8 мс, но не меньше одной миниатюры: на быстром телефоне экран заполняется сразу */
function pumpThumbs() {
  galleryRaf = 0;
  const end = performance.now() + 8;
  do {
    const el = galleryQueue.shift(); if (!el) return;
    if (el.isConnected && !el.classList.contains('ready')) buildThumb(el);
  } while (galleryQueue.length && performance.now() < end);
  if (galleryQueue.length) galleryRaf = requestAnimationFrame(pumpThumbs);
}
function renderGallery() {
  const box = $('#mv-gallery'); box.innerHTML = galleryHtml();
  if (galleryIO) galleryIO.disconnect();
  galleryQueue = [];
  const thumbs = [...box.querySelectorAll('[data-thumb]')];
  /* готовые миниатюры ставятся сразу, остальные — когда подходят к экрану */
  for (const el of thumbs) { const svg = galleryThumbs.get(thumbKey(el.dataset.thumb)); if (svg) { el.replaceChildren(svg); el.classList.add('ready'); } }
  if (typeof IntersectionObserver === 'function') {
    galleryIO = new IntersectionObserver(es => {
      for (const e of es) if (e.isIntersecting && !e.target.classList.contains('ready') && !galleryQueue.includes(e.target)) galleryQueue.push(e.target);
      if (galleryQueue.length && !galleryRaf) galleryRaf = requestAnimationFrame(pumpThumbs);
    }, {rootMargin:'300px 0px'});
    for (const el of thumbs) if (!el.classList.contains('ready')) galleryIO.observe(el);
  }
}
function showGallery(focusId) {
  disposeMotion(detailMotion); detailMotion = null;
  gallery.on = true;
  $('#motion-view').classList.add('mv-mode-gallery');
  $('#mv-detail').hidden = true; $('#mv-gallery').hidden = false;
  $('#mv-title').textContent = 'Все упражнения';
  renderGallery();
  const tile = focusId && $('#mv-gallery').querySelector(`[data-gallery-open="${focusId}"]`);
  if (tile) { tile.scrollIntoView({block:'center'}); tile.focus({preventScroll:true}); }
  else $('#mv-gallery').querySelector('[data-gallery-kind].on')?.focus({preventScroll:true});
}
function showDetail() {
  gallery.on = false;
  $('#motion-view').classList.remove('mv-mode-gallery');
  $('#mv-gallery').hidden = true; $('#mv-detail').hidden = false;
  if (galleryIO) galleryIO.disconnect(); cancelAnimationFrame(galleryRaf); galleryRaf = 0; galleryQueue = [];
}
function openGallery() {
  detailReturn = document.activeElement;
  const d = $('#motion-view'); if (!d.open) d.showModal();
  document.documentElement.classList.add('motion-open');
  showGallery();
  scheduleMotionLoop();
}
function closeGallery() {
  gallery.on = false;
  if (galleryIO) galleryIO.disconnect(); cancelAnimationFrame(galleryRaf); galleryRaf = 0; galleryQueue = [];
}
function setupGallery() {
  $('#mv-gallery').addEventListener('click', e => {
    const k = e.target.closest('[data-gallery-kind]');
    if (k) { gallery.kind = k.dataset.galleryKind; renderGallery(); $('#mv-gallery').querySelector(`[data-gallery-kind="${gallery.kind}"]`)?.focus(); return; }
    const t = e.target.closest('[data-gallery-open]');
    if (t) { showDetail(); selectMotion(previewItem(t.dataset.galleryOpen)); $('#mv-back').focus(); }
  });
  $('#mv-gallery').addEventListener('change', e => { if (e.target.id === 'mv-ghere') { gallery.here = e.target.checked; renderGallery(); $('#mv-ghere').focus(); } });
  $('#mv-gallery').addEventListener('input', e => {
    if (e.target.id !== 'mv-gq') return;
    gallery.q = e.target.value; const at = e.target.selectionStart;
    renderGallery(); const q = $('#mv-gq'); q.focus(); q.setSelectionRange(at, at);
  });
  $('#mv-back').addEventListener('click', () => showGallery(detailMotion?.it.ex.id));
}

/* ===================== ЗАГРУЗКА МЫШЦ ПО ЖУРНАЛУ ===================== */
/* Сколько подходов получила каждая группа мышц за 7 скользящих дней и сколько она отдыхает после последней существенной
   нагрузки; по этому собирается «тренировка на сегодня»: сначала недогруженные и отдохнувшие группы.
   Формат журнала прежний (13-log.js): LOG.data[exId] = [{d:'YYYY-MM-DD', s:[[кг, повторы] | null, …]}, …].

   Счёт подходов — то же правило, что у графика «Подходов на группу за неделю» в плане (groupShare, 11-planner.js):
   подход засчитывается целиком целевой группе упражнения и наполовину остальным работающим (Pelland et al.,
   Sports Med 2026; 56(2):481–505 — «дробный» счёт лучше всего предсказывает прирост). Считаются только записанные
   (непустые) подходы; односторонний подход «по 10 на каждую сторону» — одна строка журнала, один подход (с левой
   и правой стороной отдельно — тоже один: стороны лежат в том же подходе, 13a-sets.js).

   Журнал хранит только дату, без времени. Человек обычно тренируется примерно в одно время суток, поэтому часы отдыха —
   24 × число календарных дней между датой записи и сегодня: вчера — 24 ч, позавчера — 48 ч, три дня назад — 72 ч.
   «Середина дня» сделала бы статус зависимым от часа, когда открыт журнал: утром четверга понедельник — 68 ч
   («восстанавливается»), вечером — 78 ч («готова»), хотя тренировка та же. */
const LOAD = {
  days:7,        /* окно: сегодня и 6 предыдущих дней */
  lo:10, hi:20,  /* коридор подходов на группу в неделю: Schoenfeld, Ogborn, Krieger, J Sports Sci 2017; 35(11):1073–1082 —
                    10 и больше подходов в неделю дают больший прирост, чем меньше; верх 20 — как у графика плана и у Fitbod */
  minSets:2,     /* существенная нагрузка — 2 и больше подхода основной работы группы в одной тренировке (в один день) */
  loadedH:48,    /* Morán-Navarro et al., Eur J Appl Physiol 2017; 117(12):2387–2399: без отказа восстановление в основном
                    за 24–48 ч — до 48 ч группа «нагружена», */
  readyH:72,     /* после подходов до отказа — до 72 ч: 48–72 ч — «восстанавливается», от 72 ч — «готова» */
  perGroup:3     /* в тренировке на сегодня — не больше 3 упражнений на одну группу */
};
const LOAD_ST = {loaded:'нагружена', recovering:'восстанавливается', ready:'готова'};
const loadGroups = () => GROUPS.map(g => g.id).filter(g => g !== 'cardio');
/* разница в календарных днях между ключами 'YYYY-MM-DD' (без часовых поясов и перевода часов) */
function keyDays(a, b) {
  const t = k => { const [y, m, d] = k.split('-').map(Number); return Date.UTC(y, m - 1, d); };
  return Math.round((t(b) - t(a)) / 864e5);
}

/* Статус восстановления — по основной работе группы: подход засчитывается ей, если она целевая для упражнения или
   её мышцы в нём основные (pri). Вспомогательные мышцы (sec) и кардио статус не меняют: восстановление у Morán-Navarro
   и соавт. измерялось по основным мышцам упражнения, а иначе, например, четыре подхода тяги верхнего блока (грудные
   во вспомогательных) и три жима стоя (передняя зубчатая — в группе «Грудь») делали бы грудь «нагруженной» после дня
   спины и плеч. Объём за 7 дней (полосы) — по общему дробному правилу, как в плане. */
const mainGroupsOf = ex => ex.g === 'cardio' ? [] : [...groupsOf(ex)];

/* по каждой группе: v — засчитанные подходы за 7 дней; last — последняя существенная нагрузка {d, age (дней), sets —
   подходов основной работы в тот день}; h — часы отдыха; st — loaded | recovering | ready */
function muscleLoad(data = LOG.data, today = todayKey()) {
  const days = {};
  for (const [id, ss] of Object.entries(data || {})) {
    const ex = EXI[id]; if (!ex || !Array.isArray(ss)) continue;
    const share = groupShare(ex), main = mainGroupsOf(ex);
    for (const s of ss) {
      if (!s || typeof s.d !== 'string' || !Array.isArray(s.s)) continue;
      const n = s.s.filter(Boolean).length, age = keyDays(s.d, today);
      if (!n || !(age >= 0)) continue; /* записи «из будущего» (часы телефона) не считаем */
      const day = days[s.d] || (days[s.d] = {age, g:{}, m:{}});
      for (const [g, x] of Object.entries(share)) day.g[g] = (day.g[g] || 0) + n * x;
      for (const g of main) day.m[g] = (day.m[g] || 0) + n;
    }
  }
  const out = {};
  for (const g of loadGroups()) {
    let v = 0, last = null;
    for (const [d, day] of Object.entries(days)) {
      if (day.age < LOAD.days) v += day.g[g] || 0;
      const x = day.m[g] || 0;
      if (x >= LOAD.minSets && (!last || day.age < last.age)) last = {d, age:day.age, sets:x};
    }
    const h = last ? last.age * 24 : Infinity;
    out[g] = {v, last, h, st:h < LOAD.loadedH ? 'loaded' : h < LOAD.readyH ? 'recovering' : 'ready'};
  }
  return out;
}

/* ---------- тренировка на сегодня ---------- */
/* Кандидаты — «готовые» и «восстанавливающиеся» группы (у вторых вес вдвое меньше, одно упражнение и на подход меньше);
   «нагруженные» пропускаются, упражнения, где они основные, отодвигаются. Порядок — по недобору до 10 подходов
   за 7 дней, умноженному на долю группы в обычном плане (GROUP_W): 6 недостающих подходов спины важнее 6 подходов
   предплечий, которые и так работают в каждой тяге. Групп — не больше, чем упражнений; при меньше 3 групп с недобором
   добавляются готовые без недобора. Группы без упражнений в этом месте (инвентарь, уровень, бережный режим) не берутся. */
function logPick(load = muscleLoad(), opt = {}) {
  const count = opt.count || S.count, E = opt.E || effEquip(S.equip), lvlMax = S.level === 'beg' ? 2 : 3;
  const can = g => EX.some(ex => ex.g === g && available(ex, E) && ex.lvl <= lvlMax && (S.format !== 'static' || staticOk(ex)) && fitsBody(ex));
  const order = g => GROUPS.findIndex(x => x.id === g);
  const rows = loadGroups().map(g => {
    const L = load[g], need = Math.max(0, LOAD.lo - L.v);
    return {g, v:L.v, st:L.st, age:L.last ? L.last.age : null, sets:L.last ? L.last.sets : 0, need,
      p:GROUP_W[g] * (need / LOAD.lo + 0.1) * (L.st === 'recovering' ? 0.5 : 1)};
  });
  const rest = rows.filter(r => r.st === 'loaded');
  const cand = rows.filter(r => r.st !== 'loaded' && r.v < LOAD.hi && can(r.g)).sort((a, b) => b.p - a.p || order(a.g) - order(b.g));
  let chosen = cand.filter(r => r.need > 0).slice(0, count);
  if (chosen.length < 3) chosen = chosen.concat(cand.filter(r => !chosen.includes(r)).slice(0, 3 - chosen.length));
  return {rows:chosen, rest, groups:chosen.map(r => r.g).sort((a, b) => order(a) - order(b))};
}
/* доли групп для подбора: каждой — по упражнению, остальные упражнения — готовым группам пропорционально приоритету */
function pickWeights(rows, count) {
  const fresh = rows.filter(r => r.st !== 'recovering'), sumP = fresh.reduce((a, r) => a + r.p, 0), extra = Math.max(0, count - rows.length);
  const weights = {};
  for (const r of rows) weights[r.g] = Math.min(LOAD.perGroup, 1 + (r.st !== 'recovering' && sumP > 0 ? extra * r.p / sumP : 0));
  const total = Object.values(weights).reduce((a, b) => a + b, 0);
  return {weights, count:Math.max(1, Math.min(count, Math.round(total)))};
}
/* подбор по журналу действует в день, когда собран, пока группы в параметрах те же; иначе — обычный подбор */
function logPickCtx() {
  const p = S.logPick;
  if (S.mode !== 'single' || !p || typeof p !== 'object' || p.d !== todayKey() || !Array.isArray(p.groups) || !Array.isArray(p.rows) || !p.groups.length) return null;
  if (p.groups.length !== S.groups.length || !p.groups.every(g => S.groups.includes(g))) return null;
  const rows = p.rows.filter(r => r && GROUP_W[r.g] && p.groups.includes(r.g) && r.p > 0);
  if (rows.length !== p.groups.length) return null;
  return {...pickWeights(rows, S.count), rest:new Set((p.rest || []).map(r => r && r.g).filter(g => GROUP_W[g])),
    light:new Set(rows.filter(r => r.st === 'recovering').map(r => r.g)), pick:p};
}
/* восстанавливающаяся группа: на подход меньше (не меньше двух; в статодинамике — на серию меньше) */
function easeRx(rx) {
  if (rx.static) { if (rx.series > 1) { rx.eased = rx.sets; rx.series -= 1; rx.sets = rx.series * STATIC.perSeries; } }
  else if (rx.sets > 2) { rx.eased = rx.sets; rx.sets -= 1; }
  return rx;
}
function easedTag(r) { return r.eased && r.sets < r.eased && !r.circ ? '<span class="rx-light">на подход меньше: мышцы восстанавливаются</span>' : ''; }

/* собрать: группы — в параметры плана, снимок журнала — в S.logPick (план не меняется от записей по ходу тренировки) */
function applyLogPick(today = todayKey()) {
  const pick = logPick(muscleLoad(LOG.data, today));
  if (!pick.rows.length) return null;
  const prev = S.mode;
  S.view = 'plan';
  if (S.mode !== 'single') { S.mode = 'single'; S.day = 0; switchModeSettings(prev); }
  S.groups = pick.groups;
  S.logPick = {d:today, groups:pick.groups, rows:pick.rows, rest:pick.rest.map(r => ({g:r.g, age:r.age, sets:r.sets}))};
  regen();
  return pick;
}

/* ---------- тексты ---------- */
function setsWord(v) { return Number.isInteger(v) ? plural(v, 'подход', 'подхода', 'подходов') : 'подхода'; }
function agoText(age, d) {
  if (age === 0) return 'сегодня';
  if (age === 1) return 'вчера';
  if (age === 2) return 'позавчера';
  return age < LOAD.days ? `${age} ${plural(age, 'день', 'дня', 'дней')} назад` : fmtDay(d, true);
}
function restText(r) {
  if (r.age == null) return r.v > 0 ? 'основной нагрузки не было' : 'нагрузки не было';
  return `отдых ${r.age} ${plural(r.age, 'день', 'дня', 'дней')}`;
}
function loadStatusHtml(L) {
  const det = L.last ? `${agoText(L.last.age, L.last.d)}, ${L.last.sets} ${setsWord(L.last.sets)}` : L.v > 0 ? 'основной нагрузки не было' : 'нагрузки не было';
  return `<span class="ml-st"><i aria-hidden="true"></i><b>${LOAD_ST[L.st]}</b><span>${det}</span></span>`;
}

/* одна строка сверху: кто нагружен, кто восстанавливается, сколько групп готово */
function loadSummaryHtml(load) {
  const by = st => loadGroups().filter(g => load[g].st === st), names = gs => gs.map(g => GN[g].toLowerCase()).join(', ');
  const loaded = by('loaded'), rec = by('recovering'), ready = by('ready').length;
  if (!loaded.length && !rec.length) return `<p class="ml-sum"><span class="st-ready"><i aria-hidden="true"></i>Все группы готовы к нагрузке.</span></p>`;
  return `<p class="ml-sum">${loaded.length ? `<span class="st-loaded"><i aria-hidden="true"></i>Нагружены: ${names(loaded)}</span>` : ''}${rec.length ? `<span class="st-recovering"><i aria-hidden="true"></i>Восстанавливаются: ${names(rec)}</span>` : ''}${ready ? `<span class="st-ready"><i aria-hidden="true"></i>Готовы: ${ready} ${plural(ready, 'группа', 'группы', 'групп')}</span>` : ''}</p>`;
}
/* панель в журнале: подходы за 7 дней (полосы как в плане) и статус восстановления */
function muscleLoadHtml(load = muscleLoad()) {
  const ids = loadGroups(), any = ids.some(g => load[g].v > 0);
  const max = Math.max(22, ...ids.map(g => load[g].v));
  const body = any ? `<ul class="vbars ml-list">${ids.map(g => volRow(g, load[g].v, max, loadStatusHtml(load[g]), 'st-' + load[g].st)).join('')}</ul>
    <p class="ml-legend"><span class="st-loaded"><i></i>нагружена — меньше 48 ч</span><span class="st-recovering"><i></i>восстанавливается — 48–72 ч</span><span class="st-ready"><i></i>готова — от 72 ч</span></p>`
    : `<p class="ml-empty">За 7 дней записей нет — все мышцы отдохнули. Тренировка на сегодня начнётся с крупных групп.</p>`;
  return `<section class="ml" id="ml" aria-labelledby="ml-title">
    <div class="ml-head">
      <div><p class="eyebrow">Загрузка мышц</p><h2 id="ml-title">Подходы за 7 дней и отдых</h2>
        <p class="ml-sub">Сегодня и 6 предыдущих дней, по записанным подходам. Полоса — ориентир для роста: 10–20 подходов на группу в неделю.</p>
        ${any ? loadSummaryHtml(load) : ''}</div>
      <div class="ml-act"><button type="button" class="btn" data-logpick="journal">Собрать тренировку на сегодня →</button>
        <p class="p-hint ml-msg" id="ml-msg" role="status"></p></div>
    </div>
    ${body}
    <details class="rule ml-how"><summary>Как считается</summary>
      <p>Подход засчитывается целиком целевой группе упражнения и наполовину остальным работающим — как в графике недели в плане (Pelland и соавт., 2026). Считаются только записанные подходы; «по 10 на каждую сторону» — один подход.</p>
      <p>Ориентир — 10–20 подходов на группу в неделю: от 10 подходов мышцы растут заметнее (Schoenfeld, Ogborn, Krieger, 2017).</p>
      <p>Статус — по последней тренировке, где группа сделала 2 подхода и больше как основная: меньше 48 ч назад — нагружена, 48–72 ч — восстанавливается, от 72 ч — готова. Без отказа мышцы восстанавливаются в основном за 24–48 ч, после подходов до отказа — до 72 ч (Morán-Navarro и соавт., 2017). Вспомогательная работа и кардио статус не меняют. В журнале только даты, поэтому часы считаются по дням: вчера — 24 ч, позавчера — 48 ч, три дня назад — 72 ч.</p>
      <p>Тренировка на сегодня: сначала группы с наибольшим недобором до 10 подходов (крупные мышцы — раньше мелких), нагруженные пропускаются, восстанавливающиеся получают одно упражнение и на подход меньше. Инвентарь места, уровень и число упражнений — из параметров плана.</p>
    </details>
  </section>`;
}

/* строка-объяснение в плане по каждой выбранной группе */
function logPickHtml(p) {
  const lp = p && p.byLog ? logPickCtx() : null;
  if (!lp) return '';
  const order = g => GROUPS.findIndex(x => x.id === g);
  const rows = lp.pick.rows.slice().sort((a, b) => b.p - a.p || order(a.g) - order(b.g));
  const li = rows.map(r => {
    const today = Math.round((p.gvol[r.g] || 0) * 2) / 2;
    return `<li><span class="ar-i st-${r.st}" aria-hidden="true"></span><p><b>${GN[r.g]}:</b> ${fmtNum(r.v)} из 10 за 7 дней, ${restText(r)}${r.st === 'recovering' ? ' — восстанавливается, на подход меньше' : ''}<em class="lp-add">${today ? `сегодня +${fmtNum(today)}` : 'сегодня без упражнений'}</em></p></li>`;
  }).join('');
  const rest = (lp.pick.rest || []).filter(r => r && GN[r.g]);
  const skip = rest.length ? `<p class="lp-skip">Отдыхают — нагружены меньше 48 ч назад: ${rest.map(r => `${GN[r.g].toLowerCase()} (${agoText(r.age)})`).join(', ')}.</p>` : '';
  return `<section class="ar lp" aria-label="Подбор по журналу"><h2>Собрано по журналу</h2><ul>${li}</ul>${skip}</section>`;
}
/* «По журналу» среди заготовок мышц — в разовой тренировке, когда в журнале есть записи */
function logPresetHtml() {
  if (S.mode !== 'single' || !journalDays()) return '';
  const on = !!logPickCtx();
  return `<button type="button" class="pre pre-log${on ? ' on' : ''}" data-logpick="setup" aria-pressed="${on}" title="Недогруженные и отдохнувшие мышцы по журналу за 7 дней">По журналу</button>`;
}

document.addEventListener('click', e => {
  const t = e.target.closest('[data-logpick]'); if (!t) return;
  const from = t.dataset.logpick;
  if (applyLogPick()) { window.scrollTo({top:0}); return; }
  const msg = 'Все группы мышц нагружены меньше 48 ч назад или для них нет упражнений здесь — сегодня лучше отдохнуть.';
  const el = from === 'journal' ? $('#ml-msg') : $('#lp-msg');
  if (el) { el.hidden = false; el.textContent = msg; }
});

/* Режим тренировки использует тот же журнал, что и карточки плана. */
let workout=null,workoutTimer=0,workoutReturn=null;
const WORKOUT_STORE='podhod.workout.v3';
/* Экран не гаснет, пока открыт режим тренировки (Screen Wake Lock: Chrome; Safari с 16.4; приложение с экрана «Домой» на
   iPhone — с iOS 18.4). Уходя с экрана, страница теряет блокировку — при возвращении она берётся снова. Без поддержки всё
   работает как раньше: экран гаснет по настройкам телефона. */
const ScreenAwake=(()=>{
  let want=false,lock=null,asking=false;
  const free=l=>{try{const p=l.release();if(p&&p.catch)p.catch(()=>{});}catch(e){}};
  async function take(){
    const wl=typeof navigator!=='undefined'&&navigator.wakeLock;
    if(!want||lock||asking||!wl||typeof wl.request!=='function'||document.visibilityState==='hidden')return;
    asking=true;
    try{const l=await wl.request('screen');if(!want){free(l);return;}lock=l;if(l&&l.addEventListener)l.addEventListener('release',()=>{if(lock===l)lock=null;});}
    catch(e){}finally{asking=false;}
  }
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)take();});
  return{on(){want=true;return take();},off(){want=false;const l=lock;lock=null;if(l)free(l);},state:()=>({want,held:!!lock})};
})();
/* удержания с таймером — упражнения на время, кроме кардио (беговая дорожка, прыжки — не удержание) */
const isHold=ex=>ex.kind==='time'&&ex.g!=='cardio';
function workoutQueue(p){
  const q=[];
  for(const b of p.blocks){
    if(b.kind==='list')for(const it of b.items)for(let k=0;k<it.rx.sets;k++)q.push({it,k,n:it.rx.sets,rest:restAfter(it.rx,k),phase:it.rx.static?`Статодинамика · серия ${Math.floor(k/3)+1} из ${it.rx.series}`:'Классика'});
    if(b.kind==='pair')for(let k=0;k<Math.max(b.sets,...b.items.map(it=>it.rx.sets));k++){
      const active=b.items.filter(it=>k<it.rx.sets);active.forEach((it,j)=>q.push({it,k,n:it.rx.sets,rest:j===active.length-1?b.rest:0,phase:`Суперсет ${b.letter} · круг ${k+1}`}));
    }
    if(b.kind==='circuit'){
      const rounds=Math.max(b.rounds,...b.items.map(it=>it.rounds||b.rounds));
      for(let k=0;k<rounds;k++){const active=b.items.filter(it=>k<(it.rounds||b.rounds));active.forEach((it,j)=>q.push({it,k,n:it.rounds||b.rounds,rest:j===active.length-1?b.roundRest:b.rest,phase:`Круг ${k+1} из ${rounds}`}));}
    }
  }
  return q;
}
function workoutStamp(q){return JSON.stringify([todayKey(),S.mode,S.day,S.week,S.format,S.goal,q.map(x=>[x.it.ex.id,x.k,x.n,x.rest,x.it.rx.reps])]);}
function workoutValue(step){return todaySession(step.it.ex.id,false)?.s[step.k]||null;}
function workoutFirstOpen(q,after=-1){for(let j=1;j<=q.length;j++){const i=(after+j)%q.length;if(!workoutValue(q[i]))return i;}return -1;}
function workoutDraftKey(step){return step.it.ex.id+':'+step.k;}
function saveWorkout(){
  if(!workout)return;
  try{localStorage.setItem(WORKOUT_STORE,JSON.stringify({stamp:workout.stamp,index:workout.index,started:workout.started,restUntil:workout.restUntil,restTotal:workout.restTotal,restFrom:workout.restFrom,next:workout.next,last:workout.last,drafts:workout.drafts}));}catch(e){}
}
/* введённое в полях подхода: общее (kg, reps) и по сторонам (kl, rl — левая, kr, rr — правая) */
function workoutInputs(){return{kg:$('#wv-kg').value,reps:$('#wv-reps').value,kl:$('#wv-kg-l').value,rl:$('#wv-reps-l').value,kr:$('#wv-kg-r').value,rr:$('#wv-reps-r').value};}
function workoutCapture(){
  if(!workout||$('#wv-active').hidden)return;
  const step=workout.queue[workout.index];if(!step)return;
  workout.drafts[workoutDraftKey(step)]=workoutInputs();saveWorkout();
}
function startWorkout(id){
  if(!plan?.items?.length)return;
  workoutReturn=document.activeElement;
  const queue=workoutQueue(plan),stamp=workoutStamp(queue);
  let old=null;try{old=JSON.parse(localStorage.getItem(WORKOUT_STORE)||'null');}catch(e){}
  const same=old?.stamp===stamp;
  workout={queue,stamp,index:0,started:same&&Number.isFinite(old.started)?old.started:Date.now(),drafts:same&&old.drafts&&typeof old.drafts==='object'?old.drafts:{},restUntil:0,restTotal:0,restFrom:0,next:-1,last:-1,motion:null,hold:null,restOver:null,sideNote:''};
  const first=workoutFirstOpen(queue);
  if(same){workout.index=Math.max(0,Math.min(queue.length-1,Math.trunc(old.index)||0));workout.restUntil=Number(old.restUntil)||0;workout.restTotal=Number(old.restTotal)||0;workout.restFrom=Number(old.restFrom)||0;workout.next=Number.isInteger(old.next)?old.next:-1;workout.last=Number.isInteger(old.last)?old.last:-1;}
  else workout.index=Math.max(0,first);
  if(id){const i=queue.findIndex(x=>x.it.ex.id===id&&!workoutValue(x));workout.index=i>=0?i:Math.max(0,queue.findIndex(x=>x.it.ex.id===id));workout.restUntil=0;}
  const d=$('#workout-view');if(!d.open)d.showModal();document.documentElement.classList.add('workout-open');stopRest();ScreenAwake.on();
  $('#wv-context').textContent=S.mode==='program'?`${WD_FULL[prog.days[S.day].wd]} · ${prog.days[S.day].name}`:`${GOALS[S.goal].name} · ${FORMATS[S.format].name}`;
  const its=[...new Map(queue.map(x=>[x.it.ex.id,x.it])).values()];
  $('#wv-exercise').innerHTML=its.map(it=>`<option value="${it.ex.id}">${esc(it.label+'. '+it.name)}</option>`).join('');
  if(first<0&&!id)workoutFinish();
  else if(workout.restUntil&&workout.next>=0&&workout.next<queue.length){RestAlarm.unlock();RestAlarm.arm(workout.restUntil,{from:workout.restFrom||undefined});workoutShowRest();}
  else workoutShow(workout.index);
  clearInterval(workoutTimer);workoutTimer=setInterval(workoutTick,250);workoutTick();saveWorkout();$('#wv-close').focus();scheduleMotionLoop();
}
function closeWorkout(){
  if(!workout)return;holdStop();workoutCapture();saveWorkout();disposeMotion(workout.motion);clearInterval(workoutTimer);workoutTimer=0;ScreenAwake.off();
  const d=$('#workout-view');if(d.open)d.close();document.documentElement.classList.remove('workout-open');d.classList.remove('rest-over');workout.restOver=null;
  logRefresh(null);if(workoutReturn?.isConnected)workoutReturn.focus();workoutReturn=null;
}
function workoutShow(index){
  if(!workout)return;
  workout.index=Math.max(0,Math.min(workout.queue.length-1,index));workout.restUntil=0;workout.restFrom=0;workout.next=-1;workout.sideNote='';workout.holdPair=null;RestAlarm.cancel();paintRestPhase(false);
  const s=workout.queue[workout.index],it=s.it,ex=it.ex,stored=workoutValue(s),sg=suggest(it),hold=isHold(ex);
  const prev=sg.prev?.s[s.k]||sg.prev?.s.filter(Boolean).slice(-1)[0];
  $('#wv-active').hidden=false;$('#wv-rest').hidden=true;$('#wv-finish').hidden=true;
  $('#wv-title').textContent=it.name;$('#wv-exercise').value=ex.id;
  $('#wv-set-label').textContent=`${s.phase} · подход ${s.k+1} из ${s.n}`;
  $('#wv-equipment').textContent=it.eqLine;
  $('#wv-target').textContent=it.rx.reps+(ex.kind?'':' повторов');
  const unit=ex.kind==='time'?'с':ex.kind==='dist'?'м':'повт.',psd=prev&&setSides(prev,ex);
  $('#wv-previous').textContent=psd?`${setText(prev,ex)} ${unit}`:prev?`${prev[0]!=null?fmtKg(prev[0])+' кг × ':''}${prev[1]} ${unit}`:'Первая запись';
  $('#wv-previous-date').textContent=sg.prev?fmtDay(sg.prev.d,true):'';
  $('#wv-set-chips').innerHTML=workout.queue.map((x,i)=>x.it.ex.id===ex.id?`<button type="button" data-wv-index="${i}" class="${workoutValue(x)?'is-done ':''}${i===workout.index?'is-current':''}" aria-label="Подход ${x.k+1}${workoutValue(x)?', выполнен':''}" aria-current="${i===workout.index?'step':'false'}">${workoutValue(x)?'✓ ':''}${x.k+1}</button>`:'').join('');
  workoutFill(s,sg,prev);
  $('#wv-done').textContent=stored?'Сохранить изменения':'Подход выполнен';$('#wv-save-status').textContent=stored?'Этот подход уже записан.':'Запись появится в общем журнале.';
  $('#wv-suggestion').textContent=sg.text;
  holdSetup(s,sg);
  const cue=MOTION_FOCUS[ex.id];$('#wv-setup').textContent=cue?.setup||ex.tech[0];$('#wv-control').textContent=cue?.control||ex.tech[1];$('#wv-breath').textContent=ex.breath;
  disposeMotion(workout.motion);workout.motion={it,f:null,clock:0,paused:reduceMotion,durations:motionDurations(it)};$('#wv-angle').textContent=ex.viewNote||(ex.anim.view==='front'?'Вид спереди':'Вид сбоку');
  $('#wv-motion').textContent=reduceMotion?'Воспроизвести':'Пауза';$('#wv-motion').setAttribute('aria-pressed',String(!reduceMotion));mountWorkoutCameras();
  $('#wv-prev').disabled=workout.index===0;$('#wv-next').disabled=workout.index===workout.queue.length-1;
  saveWorkout();workoutTick();
}
/* поля подхода: подписи (вес одной гантели, повторы на каждую сторону), общий ввод или Л/П, подстановка веса */
function workoutFill(s,sg,prev){
  const it=s.it,ex=it.ex,stored=workoutValue(s),lt=loadType(ex),hold=isHold(ex),wl=weightLabel(it),lr=lrOn(ex),side=perSide(ex);
  $('#wv-unilateral').hidden=!side;$('#wv-unilateral').textContent=hold?'Обе стороны — в одном подходе: левая, пауза 10 с, правая. Записываются обе стороны, прогресс — по времени слабой стороны.'
    :lr?'Запишите результат каждой стороны. Прогресс и подсказки — по слабой стороне.':sidesOf(ex)==='alt'?'Чередуйте стороны. Запишите количество повторов для одной стороны.':'Выполните обе стороны. Запишите количество повторов для одной стороны.';
  $('#wv-lr-bar').hidden=!side;$('#wv-lr').setAttribute('aria-pressed',String(lr));$('#wv-one').hidden=lr;$('#wv-lr-fields').hidden=!lr;
  $('#wv-weight-label').hidden=lt==='none';$('#wv-weight-caption').textContent=wl?wl.full:'Вес, кг';$('#wv-rep-caption').textContent=side&&!ex.kind?'Повторы на каждую сторону':repLabel(ex);
  $('#wv-lr-fields').classList.toggle('wv-lr-nokg',lt==='none');$('#wv-lr-kg-cap').textContent=wl?wl.full:'Вес, кг';$('#wv-lr-rep-cap').textContent=repLabel(ex);
  for(const id of ['wv-reps','wv-reps-l','wv-reps-r'])$('#'+id).setAttribute('inputmode',ex.kind==='dist'?'decimal':'numeric');
  const draft=workout.drafts[workoutDraftKey(s)],today=todaySession(ex.id,false)?.s||[],last=today.slice(0,s.k).filter(Boolean).slice(-1)[0];
  const planned=planKg(it.rx,s.k),kgText=v=>v!=null?fmtKg(v):'';
  $('#wv-kg').value=draft?draft.kg:stored?kgText(stored[0]):planned!=null?fmtKg(planned):last?.[0]!=null?fmtKg(last[0]):prev?.[0]!=null?fmtKg(prev[0]):'';
  $('#wv-reps').value=draft?draft.reps:stored?String(stored[1]):'';$('#wv-reps').placeholder=it.rx.reps;
  /* Л/П: записанные стороны, иначе — общий вес; вес стороны по умолчанию — из прошлых сторон, если они были */
  const ssd=stored&&setSides(stored,ex),lsd=last&&setSides(last,ex),psd=prev&&setSides(prev,ex);
  for(const k of ['l','r']){
    const kgDef=planned!=null?fmtKg(planned):lsd?kgText(lsd[k][0]):last?.[0]!=null?fmtKg(last[0]):psd?kgText(psd[k][0]):prev?.[0]!=null?fmtKg(prev[0]):'';
    $('#wv-kg-'+k).value=draft&&draft['k'+k]!==undefined?draft['k'+k]:ssd?kgText(ssd[k][0]):stored?kgText(stored[0]):kgDef;
    $('#wv-reps-'+k).value=draft&&draft['r'+k]!==undefined?draft['r'+k]:ssd?String(ssd[k][1]):stored?String(stored[1]):'';$('#wv-reps-'+k).placeholder=it.rx.reps;
  }
  workoutPairTotal();
  $('#wv-input-hint').textContent=hold?(lt==='extra'?'Доп. вес можно оставить пустым. ':'')+'«Стоп» запишет секунды и начнёт отдых. Секунды можно ввести и вручную.'
    :lt==='extra'?(wl.impl==='db'?'Без гантелей оставьте вес пустым. Введите фактический результат.':'Дополнительный вес можно оставить пустым. Введите фактический результат.'):lt==='none'?'Укажите фактический результат подхода.':'Вес подставлен из последней записи, если она есть. Уточните его и введите результат.';
  $('#wv-error').textContent='';for(const id of ['wv-kg','wv-reps','wv-kg-l','wv-reps-l','wv-kg-r','wv-reps-r'])$('#'+id).removeAttribute('aria-invalid');
}
/* «×2 = 40 кг» под весом одной гантели, когда их две */
function workoutPairTotal(){
  const step=workout?.queue[workout.index];if(!step)return;
  const wl=weightLabel(step.it),v=parseNum($('#wv-kg').value),t=wl&&wl.n>1&&!lrOn(step.it.ex)?pairTotalText(wl.n,v):'';
  if($('#wv-kg-total').textContent!==t)$('#wv-kg-total').textContent=t;
}
/* «Л/П отдельно»: включили — введённое общее значение в обе стороны (вес — всегда, повторы — в пустые поля сторон);
   выключили — слабая сторона (если обе заполнены), иначе левая */
function workoutLrToggle(){
  const step=workout.queue[workout.index],ex=step.it.ex,on=!lrOn(ex),d=workoutInputs();
  if(on){if(d.kg.trim())d.kl=d.kr=d.kg;if(d.reps.trim()){if(!d.rl.trim())d.rl=d.reps;if(!d.rr.trim())d.rr=d.reps;}}
  else{
    const L=[parseNum(d.kl),parseNum(d.rl)],R=[parseNum(d.kr),parseNum(d.rr)];
    if(L[1]>0&&R[1]>0){const w=weakSide(L,R,ex)==='l';d.kg=w?d.kl:d.kr;d.reps=w?d.rl:d.rr;}else if(d.kl||d.rl){d.kg=d.kl||d.kg;d.reps=d.rl||d.reps;}
  }
  workout.drafts[workoutDraftKey(step)]=d;lrSet(ex,on);saveWorkout();
  const sg=suggest(step.it);workoutFill(step,sg,sg.prev?.s[step.k]||sg.prev?.s.filter(Boolean).slice(-1)[0]);
  $('#wv-lr').focus();
}
function paintWorkoutMotion(){if(!workout?.motion)return;const F=workout.motion,m=motionFrame(F);F.f.at(m.t,m);if($('#wv-cue').textContent!==m.cue)$('#wv-cue').textContent=m.cue;paintMusclePanel('wv',F,m);paintStressPanel('wv',F,m);}
function strictWorkoutNumber(value){const s=String(value).trim().replace(',','.');return /^\d+(\.\d+)?$/.test(s)?Number(s):null;}
function commitWorkout(e){
  if(e)e.preventDefault();if(!workout||$('#wv-active').hidden)return;
  const step=workout.queue[workout.index],ex=step.it.ex,lt=loadType(ex),lr=lrOn(ex);
  /* одна пара «вес × повторы» или две — левая и правая */
  const read=(kgEl,repsEl)=>{
    const kgRaw=kgEl.value.trim(),reps=strictWorkoutNumber(repsEl.value),kg=lt==='none'?null:kgRaw?strictWorkoutNumber(kgRaw):null;
    if(lt!=='none'&&kgRaw&&kg===null)return{bad:kgEl,msg:'Введите вес числом, например 12,5.'};
    if(lt==='kg'&&(kg===null||kg<=0))return{bad:kgEl,msg:'Укажите фактический вес снаряда.'};
    if(reps===null||reps<=0||(!ex.kind&&!Number.isInteger(reps)))return{bad:repsEl,msg:ex.kind?'Укажите фактический результат числом больше нуля.':'Укажите целое количество выполненных повторов.'};
    return{kg,reps:Math.round(reps*10)/10};
  };
  const got=lr?[read($('#wv-kg-l'),$('#wv-reps-l')),read($('#wv-kg-r'),$('#wv-reps-r'))]:[read($('#wv-kg'),$('#wv-reps'))],bad=got.find(g=>g.bad),pair=workout.holdPair;
  workout.holdPair=null;
  if(bad){$('#wv-error').textContent=bad.msg;bad.bad.setAttribute('aria-invalid','true');bad.bad.focus();return;}
  /* отдых, уже записанный у этого подхода (третье поле), при исправлении сохраняется */
  const already=!!workoutValue(step),session=todaySession(ex.id,true),rest=already?restField(session.s[step.k][2]):null;
  while(session.s.length<step.k)session.s.push(null);
  let rec;
  if(lr)rec=makeSidedSet([got[0].kg,got[0].reps],[got[1].kg,got[1].reps],ex,rest);
  else if(pair)rec=makeSidedSet([got[0].kg,pair[0]],[got[0].kg,pair[1]],ex,rest); /* таймер боковой планки: обе стороны, основное — слабая */
  if(!rec){rec=[got[0].kg,got[0].reps];if(rest)rec.push(rest);}
  session.s[step.k]=rec;session.target=Math.max(session.target||0,step.n);if(step.it.rx.static)session.fmt='static';markImpl(session,step.it);delete workout.drafts[workoutDraftKey(step)];
  logTouch(ex.id);logRefresh([ex.id]);workout.last=workout.index;
  if(already){workoutShow(workout.index);$('#wv-save-status').textContent='Изменения сохранены.';return;}
  const next=workoutFirstOpen(workout.queue,workout.index);
  if(next<0){workoutFinish();return;}
  if(step.rest>0){const now=Date.now();workout.next=next;workout.restTotal=step.rest;workout.restFrom=now;workout.restUntil=now+step.rest*1000;RestAlarm.unlock();RestAlarm.arm(workout.restUntil,{from:now});workoutShowRest();}
  else workoutShow(next);
  saveWorkout();
}
/* фактический отдых — от записи подхода до «Перейти к подходу» — третьим полем в запись подхода, после которого отдыхали */
function workoutRestTaken(){
  const sec=restActual(workout.restFrom,Date.now()),step=workout.queue[workout.last];workout.restFrom=0;
  if(!sec||!step)return;
  const v=todaySession(step.it.ex.id,false)?.s[step.k];
  if(Array.isArray(v)){v[2]=sec;logTouch(step.it.ex.id);}
}
function workoutShowRest(){
  holdStop();$('#wv-active').hidden=true;$('#wv-rest').hidden=false;$('#wv-finish').hidden=true;RestAlarm.paintButton($('#wv-sound'));RestAlarm.paintPrefs();
  const next=workout.queue[workout.next];
  $('#wv-next-name').textContent=next.it.name;$('#wv-next-detail').textContent=`${next.phase} · подход ${next.k+1} из ${next.n} · ${next.it.rx.reps}${next.it.ex.kind?'':' повторов'}`;
  $('#wv-rest-note').textContent=workout.sideNote||restNote();workout.sideNote='';workout.restOver=null;workoutTick();$('#wv-continue').focus();
}
/* после подхода: общий вес подхода, если он считается (внешний вес), и слабая сторона, если стороны отличались */
function restNote(){
  const step=workout.queue[workout.last],x=step&&workoutValue(step);
  if(!x)return 'Результат сохранён. Переходите дальше, когда будете готовы.';
  const ex=step.it.ex,t=setTonnage(ex,x,sessionImpl(ex,todaySession(ex.id,false))),w=weakSideNote(ex,{s:[x]});
  return (t>0?`Результат сохранён: общий вес подхода ${fmtTon(t)} кг.`:'Результат сохранён.')+(w?' '+w:'')+' Переходите дальше, когда будете готовы.';
}
/* общий вес упражнения за сегодня */
function todayTonnage(ex){return sessionTonnage(ex,todaySession(ex.id,false));}
/* отдых закончился: экран меняет цвет (видно с расстояния, телефон на скамье), время считает вверх «+0:25» */
function paintRestPhase(over){
  if(!workout)return;workout.restOver=over;
  $('#workout-view').classList.toggle('rest-over',over);$('#wv-rest-heading').textContent=over?'Пора к подходу':'Отдых';
  $('#wv-rest-over').textContent=over?'сверх отдыха':'';$('#wv-rest-minus').disabled=over;
}
function workoutFinish(){
  workout.restUntil=0;workout.restFrom=0;workout.next=-1;RestAlarm.cancel();holdStop();paintRestPhase(false);$('#wv-active').hidden=true;$('#wv-rest').hidden=true;$('#wv-finish').hidden=false;
  const n=workout.queue.filter(workoutValue).length,its=[...new Map(workout.queue.map(s=>[s.it.ex.id,s.it])).values()],tons=its.map(it=>todayTonnage(it.ex)),total=tons.reduce((a,b)=>a+b,0);
  $('#wv-finish-text').textContent=`Выполнено ${n} ${plural(n,'подход','подхода','подходов')} в ${its.length} ${plural(its.length,'упражнении','упражнениях','упражнениях')}.`+(total>0?` Общий вес — ${fmtTon(total)} кг.`:'');
  $('#wv-summary').innerHTML=its.map((it,i)=>`<p><span>${esc(it.name)}</span><strong>${tons[i]>0?`<small>${fmtTon(tons[i])+' кг'}</small>`:''}${workout.queue.filter(s=>s.it.ex.id===it.ex.id&&workoutValue(s)).length} ✓</strong></p>`).join('');saveWorkout();workoutTick();
}
function workoutTick(){
  if(!workout)return;
  const now=Date.now(),n=workout.queue.filter(workoutValue).length;$('#wv-progress').max=workout.queue.length;$('#wv-progress').value=n;$('#wv-progress-label').textContent=`${n} из ${workout.queue.length} подходов`;
  const elapsed=Math.max(0,Math.floor((now-workout.started)/60000));$('#wv-elapsed').textContent=elapsed?`${elapsed} мин с начала`:'';
  if(!$('#wv-rest').hidden){
    const v=restView(workout.restUntil,now);RestAlarm.poll(now);
    if($('#wv-rest-time').textContent!==v.text)$('#wv-rest-time').textContent=v.text;
    if(v.over!==workout.restOver)paintRestPhase(v.over);
  }
  if(workout.hold&&!$('#wv-active').hidden)paintHold(now);
}

/* ---------- таймер удержания (планка, боковая планка, «стульчик», вис, «лодочка») ----------
   «Старт» → 3-2-1 → отсчёт до цели со звуком на нуле → счёт вверх «+7 с»; «Стоп» пишет секунды в поле и отмечает подход,
   как «Подход выполнен». Боковая планка — левая, пауза 10 с, правая в одном подходе; записывается слабая сторона.
   Фазы и времена — по меткам нажатий (holdState в 12a-set-timers.js). */
function holdSetup(s,sg){
  const it=s.it,ex=it.ex;RestAlarm.hush();
  if(!isHold(ex)){workout.hold=null;$('#wv-hold').hidden=true;$('#wv-done').classList.remove('wv-secondary');$('#wv-done').disabled=false;return;}
  const sug=sg.reps[s.k]??sg.reps[sg.reps.length-1],T=holdTarget(it.rx.reps,sug);
  workout.hold={target:T,sides:ex.uni?2:1,h:null,last:null};
  $('#wv-hold').hidden=false;$('#wv-done').classList.add('wv-secondary');RestAlarm.paintButton($('#wv-hold-sound'));
  $('#wv-hold-goal').textContent=T.from==='log'?`Цель ${holdText(T.sec)} — по журналу (план ${it.rx.reps})`:`Цель ${holdText(T.sec)} — нижняя граница плана ${it.rx.reps}`;
  paintHold();
}
function paintHold(now=Date.now()){
  const H=workout?.hold;if(!H)return;
  const st=H.h?holdState(H.h,now):null,two=H.sides===2,sideName=i=>i?'Правая':'Левая';
  let mode,time,btn,cls='';
  if(!st){mode=two?'Левая, затем правая':'Таймер удержания';time=holdText(H.target.sec);btn='Старт';}
  else if(st.phase==='lead'){mode='Приготовьтесь';time=String(st.count);btn='Отмена';cls='is-lead';}
  else if(st.phase==='switch'){mode='Смена стороны';time=String(st.count);btn='Правая — сейчас';cls='is-lead';}
  else if(st.phase==='hold'){mode=(two?sideName(st.side)+' · ':'')+(st.mode==='to'?(two?'до цели':'До цели'):(two?'сверх цели':'Сверх цели'));time=st.mode==='to'?holdText(st.left):holdText(st.over,true);btn='Стоп';cls=st.mode==='over'?'is-over':'is-run';}
  else{mode='Записано';time=holdText(st.value);btn='Старт заново';}
  let sides='';
  if(two&&st){
    const r=st.results;
    sides=st.phase==='done'?`Левая ${holdText(r[0])}, правая ${holdText(r[1])} — записывается слабая сторона: ${holdText(st.value)}`
      :st.phase==='switch'?`Левая ${holdText(r[0])} · правая — через ${st.count} с`:r.length?`Левая ${holdText(r[0])} · правая идёт`:'';
  }
  const box=$('#wv-hold');box.className='wv-hold'+(cls?' '+cls:'');
  if($('#wv-hold-mode').textContent!==mode)$('#wv-hold-mode').textContent=mode;
  /* единица «с» — мельче числа и не моноширинная, иначе «30  с» расползается */
  const tEl=$('#wv-hold-time');if(tEl.textContent!==time){const i=time.lastIndexOf(' ');if(i>0){const u=document.createElement('span');u.className='wv-hold-unit';u.textContent=time.slice(i);tEl.replaceChildren(time.slice(0,i),u);}else tEl.textContent=time;}
  if($('#wv-hold-sides').textContent!==sides){$('#wv-hold-sides').textContent=sides;$('#wv-hold-sides').hidden=!sides;}
  const go=$('#wv-hold-go');if(go.textContent!==btn)go.textContent=btn;
  const running=!!st&&st.phase!=='done';go.classList.toggle('is-stop',running);$('#wv-hold-reset').hidden=!running||st.phase==='lead';$('#wv-done').disabled=running;
  /* вибрация (Android) на «пошли» и на достижении цели — по смене фазы */
  const key=st?st.phase+(st.mode||'')+st.side:'idle';
  if(H.last!==key){if(st?.phase==='hold'&&(st.mode==='over'?H.last===`holdto${st.side}`:/^(lead|switch)/.test(H.last||'')))RestAlarm.buzz(st.mode==='over'?'end':'go');H.last=key;}
}
function holdGo(){
  const H=workout?.hold;if(!H)return;
  const now=Date.now();
  if(!H.h||holdState(H.h,now).phase==='done'){RestAlarm.unlock();H.h=holdNew(now,H.target.sec,H.sides);H.last=null;RestAlarm.cue(holdCues(H.h));$('#wv-error').textContent='';paintHold(now);return;}
  const r=holdPress(H.h,now);
  if(r.action==='cancel'){H.h=null;RestAlarm.hush();}
  else if(r.action==='done'){H.h=r.h;RestAlarm.hush();holdCommit();return;}
  else if(r.h){H.h=r.h;RestAlarm.cue(holdCues(H.h));}
  paintHold(now);
}
/* «Стоп» последней стороны: секунды — в поле подхода, дальше — как «Подход выполнен» */
function holdCommit(){
  const H=workout.hold,st=holdState(H.h,Date.now());paintHold();
  if(!(st.value>0)){H.h=null;paintHold();$('#wv-error').textContent='Таймер остановлен в первую секунду — подход не записан.';return;}
  /* обе стороны — в поле сторон подхода (основное — слабая); при «Л/П отдельно» — в поля левой и правой */
  if(H.sides===2&&lrOn(workout.queue[workout.index].it.ex)){$('#wv-reps-l').value=String(st.results[0]);$('#wv-reps-r').value=String(st.results[1]);}
  else{$('#wv-reps').value=String(st.value);$('#wv-reps').removeAttribute('aria-invalid');workout.holdPair=H.sides===2?[st.results[0],st.results[1]]:null;}
  workout.sideNote=H.sides===2?`Записано ${holdText(st.value)} — время слабой стороны (левая ${holdText(st.results[0])}, правая ${holdText(st.results[1])}).`:'';
  commitWorkout();
}
function holdStop(){if(workout?.hold){workout.hold.h=null;workout.hold.last=null;}RestAlarm.hush();}
function setupWorkout(){
  $('#wv-form').addEventListener('submit',commitWorkout);
  for(const id of ['wv-kg','wv-reps','wv-kg-l','wv-reps-l','wv-kg-r','wv-reps-r'])$('#'+id).addEventListener('input',()=>{workoutCapture();$('#wv-error').textContent='';$('#'+id).removeAttribute('aria-invalid');if(id==='wv-kg')workoutPairTotal();});
  $('#wv-exercise').addEventListener('change',e=>{workoutCapture();const i=workout.queue.findIndex(s=>s.it.ex.id===e.target.value&&!workoutValue(s));workoutShow(i>=0?i:workout.queue.findIndex(s=>s.it.ex.id===e.target.value));});
  $('#workout-view').addEventListener('cancel',e=>{e.preventDefault();closeWorkout();});
  /* вернулись на экран: таймеры страницы в фоне редки — обновить отдых и удержание сразу */
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&workout&&$('#workout-view').open)workoutTick();});
  document.addEventListener('click',e=>{
    const t=e.target.closest('button');if(!t)return;
    if(t.id==='start-workout'||t.dataset.workout!==undefined){startWorkout(t.dataset.workout);return;}
    if(!workout||!$('#workout-view').open)return;
    if(t.id==='wv-close'||t.id==='wv-finish-close'){closeWorkout();return;}
    if(t.id==='wv-prev'||t.id==='wv-next'){workoutCapture();workoutShow(workout.index+(t.id==='wv-next'?1:-1));return;}
    if(t.dataset.wvIndex!==undefined){workoutCapture();workoutShow(Number(t.dataset.wvIndex));return;}
    if(t.id==='wv-review'){workoutShow(0);return;}
    if(t.id==='wv-undo'){workoutShow(workout.last);return;}
    if(t.id==='wv-continue'){workoutRestTaken();workoutShow(workout.next);return;}
    if(t.id==='wv-lr'){workoutLrToggle();return;}
    if(t.id==='wv-hold-go'){holdGo();return;}
    if(t.id==='wv-hold-reset'){holdStop();paintHold();return;}
    if(t.dataset.wvRest){const end=restAdjust(workout.restUntil,Date.now(),Number(t.dataset.wvRest));if(end!==workout.restUntil){workout.restUntil=end;RestAlarm.arm(end,{from:workout.restFrom||undefined});saveWorkout();workoutTick();}return;}
    if(t.id==='wv-motion'){const m=workout.motion;m.paused=!m.paused;t.textContent=m.paused?'Воспроизвести':'Пауза';t.setAttribute('aria-pressed',String(!m.paused));return;}
    if(t.id==='wv-technique'){workoutCapture();if(workout.motion)openMotionItem(workout.motion.it,workout.motion.clock);}
  });
}

function motionCamera(ex){
 const cameras=ex.anim.catalogCameras||ex.anim.cameras||[],saved=motionPrefs.views?.[ex.id];
 return cameras.includes(saved)?saved:ex.anim.catalogRig?'above':ex.anim.camera||ex.anim.view;
}
function cameraButtons(ex,current){
 return (ex.anim.catalogCameras||ex.anim.cameras||[]).map(key=>`<button type="button" data-motion-camera="${key}" aria-pressed="${current===key}">${CAMERA3[key].label}</button>`).join('');
}
function rememberCamera(ex,key){
 if(!(ex.anim.catalogCameras||ex.anim.cameras)?.includes(key))return false;
 motionPrefs.views=Object.assign({},motionPrefs.views,{[ex.id]:key});saveMotionPrefs();return true;
}
function mountDetailCameras(){
 if(!detailMotion)return;
 const F=detailMotion,ex=F.it.ex,a=ex.anim,key=motionCamera(ex),cameras=a.catalogCameras||a.cameras||[];
 disposeMotion(F);
 const m=motionFrame(F),make=camera=>{
  const f=createMotionFigure(a,{primary:ex.pri,has:F.it.has,ratio:1.15,t:m.t,label:F.it.name,camera,muscles:motionPrefs.muscles});
  f.svg.classList.toggle('show-joints',!!motionPrefs.joints);f.setTrace(!!motionPrefs.trace);f.setVectors(!!motionPrefs.vectors);return f;
 };
 F.f=make(key);$('#mv-stage').replaceChildren(F.f.svg);
 $('#mv-camera-controls').hidden=cameras.length<2;
 $('#mv-cameras').innerHTML=cameraButtons(ex,key);
 $('#mv-view').textContent=CAMERA3[key]?.label||ex.viewNote||(a.view==='front'?'Вид спереди':'Вид сбоку');
 $('#mv-camera-hint').textContent=a.cameraHints?.[key]||'';
 $('#mv-camera-hint').hidden=!a.cameraHints;
 const pair=cameras.length>1&&!!motionPrefs.dual;
 $('#mv-dual').checked=!!motionPrefs.dual;$('#mv-second').hidden=!pair;$('#mv-projections').classList.toggle('is-dual',pair);
 F.extra=null;
 if(pair){
  const other=pairCamera(a,key);F.extra=make(other);$('#mv-second-stage').replaceChildren(F.extra.svg);
  $('#mv-second-label').textContent=CAMERA3[other].label;$('#mv-second-hint').textContent=a.cameraHints?.[other]||'';
 }else $('#mv-second-stage').replaceChildren();
 configureMusclePanel('mv',F.it);configureStressPanel('mv',F);applyFigureView(F);paintMotion(F,true);
}
/* второй ракурс пары: из профиля мышц упражнения, иначе первый другой */
function pairCamera(a,key){const cameras=a.catalogCameras||a.cameras||[],preferred=motionProfile(a)?.pair;return preferred!==key&&cameras.includes(preferred)?preferred:cameras.find(c=>c!==key);}
/* Смена ракурса в разборе: объёмная фигура переключает камеру сама — без новой сцены и пересчёта позы (≈0,2 с на
   компьютере, втрое дольше на слабом телефоне). Плоская запасная схема и смена числа видов пересобирают окно. */
function switchDetailCamera(){
 const F=detailMotion,a=F.it.ex.anim,key=motionCamera(F.it.ex),pair=(a.catalogCameras||a.cameras||[]).length>1&&!!motionPrefs.dual,other=pair?pairCamera(a,key):null;
 if(!F.f?.setCamera||(pair?!F.extra?.setCamera:!!F.extra)||!F.f.setCamera(key)||(pair&&!F.extra.setCamera(other)))return mountDetailCameras();
 pressCamera('#mv-cameras',key);
 $('#mv-view').textContent=CAMERA3[key]?.label||F.it.ex.viewNote||(a.view==='front'?'Вид спереди':'Вид сбоку');
 $('#mv-camera-hint').textContent=a.cameraHints?.[key]||'';
 if(pair){$('#mv-second-label').textContent=CAMERA3[other].label;$('#mv-second-hint').textContent=a.cameraHints?.[other]||'';}
}
function switchWorkoutCamera(){
 const F=workout.motion,ex=F.it.ex,key=motionCamera(ex);
 if(!F.f?.setCamera||!F.f.setCamera(key))return mountWorkoutCameras();
 pressCamera('#wv-cameras',key);$('#wv-angle').textContent=CAMERA3[key]?.label||(ex.anim.view==='front'?'Вид спереди':'Вид сбоку');
}
/* кнопки ракурсов не перерисовываются — фокус остаётся на нажатой */
function pressCamera(sel,key){for(const b of $(sel).querySelectorAll('[data-motion-camera]'))b.setAttribute('aria-pressed',String(b.dataset.motionCamera===key));}
function mountWorkoutCameras(){
 if(!workout?.motion)return;
 const F=workout.motion,ex=F.it.ex,key=motionCamera(ex),m=motionFrame(F);
 disposeMotion(F);F.f=createMotionFigure(ex.anim,{has:F.it.has,ratio:1.15,t:m.t,label:F.it.name,camera:key,muscles:motionPrefs.muscles});F.f.setVectors(!!motionPrefs.vectors);
 $('#wv-stage').replaceChildren(F.f.svg);$('#wv-cameras').innerHTML=cameraButtons(ex,key);$('#wv-cameras').hidden=!(ex.anim.catalogCameras||ex.anim.cameras);
 $('#wv-angle').textContent=CAMERA3[key]?.label||(ex.anim.view==='front'?'Вид спереди':'Вид сбоку');configureMusclePanel('wv',F.it);configureStressPanel('wv',F);paintWorkoutMotion();
}
function setupMotionCameras(){
 $('#mv-cameras').addEventListener('click',e=>{const b=e.target.closest('[data-motion-camera]');if(b&&detailMotion&&rememberCamera(detailMotion.it.ex,b.dataset.motionCamera))switchDetailCamera();});
 $('#wv-cameras').addEventListener('click',e=>{const b=e.target.closest('[data-motion-camera]');if(b&&workout?.motion&&rememberCamera(workout.motion.it.ex,b.dataset.motionCamera))switchWorkoutCamera();});
 $('#mv-dual').addEventListener('change',e=>{motionPrefs.dual=e.target.checked;saveMotionPrefs();mountDetailCameras();});
}

/* ===================== АВТОРЕГУЛИРОВКА ===================== */
/* Решения принимаются по журналу. Правила:
   1. Застой: 3 последние тренировки по упражнению без роста расчётного максимума (±1%) и без выхода на верх диапазона → заменить упражнение или поработать в другом диапазоне.
   2. Недобор: 2 последние тренировки подряд ниже нижней границы повторов → снизить вес (это уже делает подсказка) — здесь только отмечаем.
   3. Усталость: за последние 10 дней не меньше 4 записей, и в половине из них хотя бы один подход ниже нижней границы → внеплановая разгрузка.
   4. Пропуск: последняя запись старше 14 дней при наличии истории → мягкий возврат: веса на 10% ниже. */
const AR = {dismissed:{}, light:false};
try { Object.assign(AR, JSON.parse(localStorage.getItem('podhod.autoreg.v1') || '{}')); } catch (e) {}
function arSave() { try { localStorage.setItem('podhod.autoreg.v1', JSON.stringify({dismissed:AR.dismissed, light:AR.light})); } catch (e) {} }
function daysBetween(a, b) { return Math.round((new Date(b) - new Date(a)) / 86400000); }

function exerciseStall(it) {
  const ex = it.ex, past = pastSessions(ex.id);
  if (past.length < 3 || ex.kind || loadType(ex) !== 'kg') return null;
  const m = metricOf(ex), [lo, hi] = parseRange(it.rx.reps);
  const last3 = past.slice(-3), vals = last3.map(m.f);
  if (vals.some(v => v == null)) return null;
  const grew = vals[2] > vals[0] * 1.01 || vals[2] > vals[1] * 1.01;
  const topReached = last3.some(s => { const sets = s.s.filter(Boolean); const w = Math.max(...sets.map(x => x[0] || 0)); return sets.filter(x => x[0] === w).every(x => x[1] >= hi); });
  if (grew || topReached) return null;
  return {kind:'stall', ex, since:last3[0].d, text:`${ex.name}: три тренировки подряд без роста (${fmtDay(last3[0].d, true)} — ${fmtDay(last3[2].d, true)}). Смените упражнение на 3–4 недели или поработайте в диапазоне ${hi + 2}–${hi + 5} повторов с меньшим весом.`};
}
function fatigueCheck(items) {
  const today = todayKey(), cutoff = dayKey(new Date(Date.now() - 10 * 86400000));
  let n = 0, low = 0;
  const seen = new Set();
  for (const [id, ss] of Object.entries(LOG.data)) {
    const ex = EXI[id]; if (!ex || ex.kind) continue;
    const it = items.find(x => x.ex.id === id);
    const [lo] = parseRange(it ? it.rx.reps : GOALS[S.goal].reps[ex.type]);
    for (const s of ss) {
      if (s.d < cutoff || s.d >= today || !s.s.some(Boolean)) continue;
      n++; seen.add(s.d);
      if (s.s.filter(Boolean).some(x => x[1] < lo)) low++;
    }
  }
  if (n < 4 || low * 2 < n) return null;
  return {kind:'fatigue', n, low, text:`За 10 дней в ${low} из ${n} записей не дотянули до нижней границы повторов. Похоже на накопленную усталость: возьмите разгрузочную неделю — подходов на 40% меньше, веса на 10–15% ниже.`};
}
function layoffCheck() {
  let last = '';
  for (const ss of Object.values(LOG.data)) for (const s of ss) if (s.s.some(Boolean) && s.d > last && s.d < todayKey()) last = s.d;
  if (!last) return null;
  const gap = daysBetween(last, todayKey());
  if (gap < 14) return null;
  return {kind:'layoff', gap, text:`Последняя запись ${fmtDay(last, true)}, перерыв ${gap} ${plural(gap, 'день', 'дня', 'дней')}. Первую тренировку после перерыва проведите на весах на 10% ниже прежних, затем возвращайтесь по правилу прибавок.`};
}
function autoreg() {
  if (!plan || !plan.items) return [];
  const out = [];
  const lay = layoffCheck(); if (lay) out.push(lay);
  const fat = !lay && fatigueCheck(plan.items); if (fat) out.push(fat);
  if (!fat && !lay) for (const it of plan.items) { const st = exerciseStall(it); if (st) out.push(st); }
  return out.filter(r => !AR.dismissed[arKey(r)]);
}
function arKey(r) { return r.kind === 'stall' ? 'stall:' + r.ex.id + ':' + r.since : r.kind + ':' + todayKey().slice(0, 7); }
function autoregHtml() {
  const recs = autoreg();
  const items = recs.map(r => {
    const key = arKey(r);
    let act = '';
    if (r.kind === 'stall') act = `<button type="button" class="btn-ghost" data-ar-swap="${r.ex.id}">${ICON.swap}<span>Заменить</span></button>`;
    else if (r.kind === 'fatigue') act = S.mode === 'program' ? `<button type="button" class="btn-ghost" data-ar-deload="1">Включить разгрузку</button>` : `<button type="button" class="btn-ghost" data-ar-light="1">${AR.light ? 'Вернуть обычный объём' : 'Облегчить тренировку'}</button>`;
    return `<li><span class="ar-i ar-${r.kind}" aria-hidden="true"></span><p>${esc(r.text)}</p><div class="ar-act">${act}<button type="button" class="lk" data-ar-dismiss="${esc(key)}">Скрыть</button></div></li>`;
  }).join('');
  if (!items && !AR.light) return '';
  const lightNote = AR.light ? `<li><span class="ar-i ar-fatigue" aria-hidden="true"></span><p>Облегчённый режим: подходов на 40% меньше, подсказки весов на 10% ниже. Действует, пока вы его не выключите.</p><div class="ar-act"><button type="button" class="btn-ghost" data-ar-light="1">Вернуть обычный объём</button></div></li>` : '';
  return `<section class="ar" aria-label="Рекомендации по нагрузке"><h2>По вашему журналу</h2><ul>${items}${lightNote}</ul></section>`;
}
/* облегчённый режим влияет на дозировку в одиночном режиме */
function applyLight(rx, ex) {
  if (!AR.light || S.mode === 'program') return rx;
  if (rx.static) { rx.series = Math.max(1, rx.series - 1); rx.sets = rx.series * 3; }
  else if (!rx.circ) rx.sets = Math.max(2, Math.ceil(rx.sets * 0.6));
  rx.light = true;
  return rx;
}
document.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t) return;
  if (t.dataset.arDismiss) { AR.dismissed[t.dataset.arDismiss] = true; arSave(); renderPlan(); return; }
  if (t.dataset.arSwap) {
    const it = plan.items.find(x => x.ex.id === t.dataset.arSwap); if (!it) return;
    const btn = document.querySelector(`.card[data-ex="${it.ex.id}"] [data-swap]`); if (btn) btn.click();
    return;
  }
  if (t.dataset.arDeload) { S.week = 4; AR.dismissed['fatigue:' + todayKey().slice(0, 7)] = true; arSave(); saveSettings(); renderPlan(); return; }
  if (t.dataset.arLight) { AR.light = !AR.light; if (AR.light) AR.dismissed['fatigue:' + todayKey().slice(0, 7)] = true; arSave(); renderPlan(); return; }
});

/* ===================== ЭКСПОРТ В КАЛЕНДАРЬ ===================== */
const ICS_KEY = 'podhod.ics.v1';
const ICS = {time:'19:00', weeks:4, alarm:60};
try { Object.assign(ICS, JSON.parse(localStorage.getItem(ICS_KEY) || '{}')); } catch (e) {}
function nextMonday() { const d = new Date(); d.setHours(12, 0, 0, 0); const dow = (d.getDay() + 6) % 7; d.setDate(d.getDate() + (dow === 0 ? 0 : 7 - dow)); return d; }
const pad2 = n => String(n).padStart(2, '0');
const icsDate = d => `${d.getFullYear()}${pad2(d.getMonth() + 1)}${pad2(d.getDate())}T${pad2(d.getHours())}${pad2(d.getMinutes())}00`;
const icsEsc = s => String(s).replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;');
function icsFold(line) { const out = []; let b = ''; for (const ch of line) { const t = new TextEncoder().encode(b + ch).length; if (t > 72) { out.push(b); b = ' ' + ch; } else b += ch; } out.push(b); return out.join('\r\n'); }
function icsText(start, time, weeksN) {
  const [hh, mm] = time.split(':').map(Number);
  const saved = {week:S.week, day:S.day};
  const lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//LazyGymPlanner//Workout planner//RU', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'X-WR-CALNAME:Lazy Gym Planner — тренировки'];
  const stamp = icsDate(new Date()).replace(/T.*/, 'T000000Z');
  for (let w = 0; w < weeksN; w++) {
    S.week = (w % 4) + 1;
    const pr = buildProgram();
    for (const d of pr.days) {
      if (!d.plan.items) continue;
      const dt = new Date(start); dt.setDate(start.getDate() + w * 7 + d.wd); dt.setHours(hh, mm, 0, 0);
      const end = new Date(dt.getTime() + Math.max(30, d.plan.minutes + 15) * 60000);
      const title = `Тренировка: ${d.name} · неделя ${S.week} (${pr.week.name.toLowerCase()})`;
      const body = [`${GOALS[S.goal].name}, ${FORMATS[S.format].name.toLowerCase()}, ≈${d.plan.minutes} мин`, pr.week.note, ''].concat(blocksText(d.plan)).join('\n');
      lines.push('BEGIN:VEVENT', `UID:podhod-${icsDate(dt)}-${d.tid}@podhod`, `DTSTAMP:${stamp}`, `DTSTART:${icsDate(dt)}`, `DTEND:${icsDate(end)}`,
        icsFold(`SUMMARY:${icsEsc(title)}`), icsFold(`DESCRIPTION:${icsEsc(body)}`), 'CATEGORIES:Тренировка');
      if (ICS.alarm > 0) lines.push('BEGIN:VALARM', 'ACTION:DISPLAY', icsFold(`DESCRIPTION:${icsEsc('Через ' + (ICS.alarm >= 60 ? ICS.alarm / 60 + ' ч' : ICS.alarm + ' мин') + ' тренировка: ' + d.name)}`), `TRIGGER:-PT${ICS.alarm}M`, 'END:VALARM');
      lines.push('END:VEVENT');
    }
  }
  lines.push('END:VCALENDAR');
  S.week = saved.week; S.day = saved.day;
  return lines.join('\r\n') + '\r\n';
}
function icsDialogHtml() {
  const mon = nextMonday();
  const sched = SCHEDULE[S.days].map(i => WD[i]).join(', ');
  return `<form method="dialog" class="gear ics">
    <h2>В календарь</h2>
    <p class="gear-hint">Файл .ics с тренировками по дням сплита (${sched}) на ${ICS.weeks} ${plural(ICS.weeks, 'неделю', 'недели', 'недель')} цикла. Откройте его в календаре телефона или компьютера — события добавятся с напоминанием и текстом тренировки.</p>
    <div class="ics-grid">
      <label>Первый понедельник<input id="ics-start" type="date" value="${dayKey(mon)}"></label>
      <label>Время начала<input id="ics-time" type="time" value="${ICS.time}"></label>
      <label>Недель<select id="ics-weeks">${[4, 8, 12].map(n => `<option value="${n}"${n === ICS.weeks ? ' selected' : ''}>${n}</option>`).join('')}</select></label>
      <label>Напоминание<select id="ics-alarm">${[[0, 'без'], [30, 'за 30 мин'], [60, 'за час'], [120, 'за 2 часа'], [720, 'за 12 часов']].map(([v, n]) => `<option value="${v}"${v === ICS.alarm ? ' selected' : ''}>${n}</option>`).join('')}</select></label>
    </div>
    <p class="gear-hint">Тренировки ставятся на дни недели из сплита. После 4-й недели цикл повторяется с первой.</p>
    <p class="p-hint" id="ics-msg" role="status"></p>
    <div class="gear-btns"><button type="button" class="btn btn-2" id="ics-cancel">Закрыть</button><button type="button" class="btn" id="ics-save">Сохранить файл</button></div>
  </form>`;
}
function openIcs() {
  let d = $('#ics-view');
  if (!d) { d = document.createElement('dialog'); d.id = 'ics-view'; d.className = 'gear-view'; document.body.appendChild(d); }
  d.innerHTML = icsDialogHtml(); d.showModal();
}
async function saveIcs() {
  const start = new Date($('#ics-start').value + 'T12:00:00');
  if (isNaN(start)) { $('#ics-msg').textContent = 'Укажите дату начала.'; return; }
  ICS.time = $('#ics-time').value || '19:00'; ICS.weeks = +$('#ics-weeks').value || 4; ICS.alarm = +$('#ics-alarm').value || 0;
  try { localStorage.setItem(ICS_KEY, JSON.stringify(ICS)); } catch (e) {}
  const txt = icsText(start, ICS.time, ICS.weeks);
  const r = await saveFile(`lazy-gym-workouts-${dayKey(start)}.ics`, txt, 'text/calendar');
  $('#ics-msg').textContent = r === 'ok' ? 'Файл сохранён. Откройте его — календарь предложит добавить события.' : r === 'declined' ? 'Сохранение отменено.' : 'Сохранить файл не удалось.';
}
document.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t) return;
  if (t.id === 'ics-open') { openIcs(); return; }
  if (t.id === 'ics-cancel') { $('#ics-view').close(); return; }
  if (t.id === 'ics-save') { saveIcs(); return; }
});

/* ===================== РАЗМИНКА И БЛИНЫ ===================== */
const GEAR_KEY = 'podhod.gear.v1';
const GEAR = {bar:20, plates:[25, 20, 15, 10, 5, 2.5, 1.25], dbStep:2, machineStep:5};
const PLATE_SETS = {
  std:{name:'Стандарт', plates:[25, 20, 15, 10, 5, 2.5, 1.25]},
  home:{name:'Домашний', plates:[20, 10, 5, 2.5, 1.25]},
  fine:{name:'С мелкими', plates:[25, 20, 15, 10, 5, 2.5, 1.25, 0.5]}
};
function gearLoad() { try { const g = JSON.parse(localStorage.getItem(GEAR_KEY) || 'null'); if (g && typeof g === 'object') { if (isFinite(g.bar)) GEAR.bar = +g.bar; if (Array.isArray(g.plates)) GEAR.plates = g.plates.map(Number).filter(v => v > 0).sort((a, b) => b - a); } } catch (e) {} }
function gearSave() { try { localStorage.setItem(GEAR_KEY, JSON.stringify({bar:GEAR.bar, plates:GEAR.plates})); } catch (e) {} }
gearLoad();

/* чем нагружают: штанга (гриф + блины), гантели, тренажёр (стек), гиря */
function implementOf(it) {
  const ids = it.eqIds || [];
  if (ids.includes('bb') || ids.includes('smith')) return 'bb';
  if (ids.includes('db')) return 'db';
  if (ids.includes('kb')) return 'kb';
  if (ids.some(i => MACHINE.has(i) || i === 'legpress')) return 'machine';
  return null;
}
/* раскладка блинов на одну сторону грифа; возвращает {side:[...], total, diff} */
function plateSplit(target, bar = GEAR.bar, plates = GEAR.plates) {
  let perSide = (target - bar) / 2, side = [];
  if (perSide <= 0) return {side, total:bar, diff:target - bar};
  for (const p of plates) while (perSide >= p - 1e-9) { side.push(p); perSide -= p; }
  const total = bar + 2 * side.reduce((a, b) => a + b, 0);
  return {side, total, diff:target - total};
}
/* ближайший достижимый вес (вниз) */
function roundToGear(target, impl) {
  if (impl === 'bb') return plateSplit(target).total;
  if (impl === 'db') return Math.round(target / GEAR.dbStep) * GEAR.dbStep;
  if (impl === 'machine') return Math.round(target / GEAR.machineStep) * GEAR.machineStep;
  if (impl === 'kb') return Math.round(target / 4) * 4;
  return Math.round(target * 2) / 2;
}
/* пирамида разминки: от грифа/лёгкого к рабочему; число шагов зависит от веса */
function warmupPlan(work, impl, reps) {
  if (!work || work <= 0) return [];
  const [lo] = parseRange(reps);
  const steps = [];
  if (impl === 'bb') {
    if (work <= GEAR.bar * 1.6) return [{kg:GEAR.bar, reps:Math.max(8, lo + 4), note:'пустой гриф'}];
    steps.push({kg:GEAR.bar, reps:10, note:'пустой гриф'});
  }
  const ratios = work >= 140 ? [0.4, 0.6, 0.75, 0.9] : work >= 90 ? [0.5, 0.7, 0.85] : work >= 50 ? [0.55, 0.8] : [0.6];
  const repsFor = r => r < 0.55 ? 8 : r < 0.72 ? 5 : r < 0.87 ? 3 : 1;
  for (const r of ratios) {
    const kg = roundToGear(work * r, impl);
    if (kg <= (steps.length ? steps[steps.length - 1].kg : 0) || kg >= work) continue;
    steps.push({kg, reps:repsFor(r), note:`${Math.round(r * 100)}%`});
  }
  return steps;
}
function platesHtml(target) {
  const s = plateSplit(target);
  if (!s.side.length && s.diff <= 0) return `<span class="pl-empty">пустой гриф ${fmtKg(GEAR.bar)}</span>`;
  const chips = s.side.map(p => `<i class="pl pl-${String(p).replace('.', '_')}" title="${fmtKg(p)} кг">${fmtKg(p)}</i>`).join('');
  const warn = s.diff > 0.01 ? `<small class="pl-diff">= ${fmtKg(s.total)}, не хватает ${fmtKg(s.diff)}</small>` : '';
  return `<span class="pl-row" aria-label="На каждую сторону: ${s.side.map(fmtKg).join(', ')} кг">${chips}</span>${warn}`;
}
function warmupHtml(it, work) {
  const impl = implementOf(it);
  if (!impl || !work) return '';
  const steps = warmupPlan(work, impl, it.rx.reps);
  if (!steps.length) return '';
  const rows = steps.map((s, i) => `<li><span class="wu-n">${i + 1}</span><span class="wu-kg">${fmtKg(s.kg)}<small>кг</small></span><span class="wu-r">× ${s.reps}</span><span class="wu-note">${s.note}</span>${impl === 'bb' ? `<span class="wu-pl">${s.note === 'пустой гриф' ? '' : platesHtml(s.kg)}</span>` : ''}</li>`).join('');
  const workRow = impl === 'bb' ? `<li class="wu-work"><span class="wu-n">→</span><span class="wu-kg">${fmtKg(work)}<small>кг</small></span><span class="wu-r">рабочий</span><span class="wu-note"></span><span class="wu-pl">${platesHtml(work)}</span></li>` : '';
  return `<details class="wu"><summary>Разминка к ${fmtKg(work)} кг<small>${steps.length} ${plural(steps.length, 'подход', 'подхода', 'подходов')}${impl === 'bb' ? ' · блины на сторону' : ''}</small></summary>
    <ol class="wu-list${impl === 'bb' ? ' wu-bb' : ''}">${rows}${workRow}</ol>
    <p class="wu-note-f">Отдых между разминочными 30–60 с. ${impl === 'bb' ? `Гриф ${fmtKg(GEAR.bar)} кг, блины: ${GEAR.plates.map(fmtKg).join(' · ')} — <button type="button" class="lk" data-gear="1">настроить</button>.` : impl === 'machine' ? 'Шаг стека принят 5 кг.' : ''}</p>
  </details>`;
}
/* рабочий вес для разминки: из первого введённого поля, иначе из подсказки */
function workWeightOf(it, card) {
  if (card) { const inp = card.querySelector('.lt-r:not(.done) [data-f="kg"], .lt-r [data-f="kg"]'); if (inp && inp.value) { const v = parseNum(inp.value); if (v > 0) return v; } }
  const sg = suggest(it); return sg.kg && sg.kg > 0 ? sg.kg : null;
}
function refreshWarmup(card) {
  if (!plan || !plan.items) return;
  const it = plan.items.find(x => x.ex.id === card.dataset.ex); if (!it) return;
  const box = card.querySelector('.c-warm'); if (!box) return;
  const open = box.querySelector('details') && box.querySelector('details').open;
  box.innerHTML = warmupHtml(it, workWeightOf(it, card));
  if (open && box.querySelector('details')) box.querySelector('details').open = true;
}
/* настройка инвентаря */
function gearDialogHtml() {
  const cur = Object.entries(PLATE_SETS).find(([, v]) => v.plates.join() === GEAR.plates.join());
  return `<form method="dialog" class="gear">
    <h2>Гриф и блины</h2>
    <label>Вес грифа, кг<input id="gear-bar" type="text" inputmode="decimal" value="${fmtKg(GEAR.bar)}"></label>
    <p class="gear-l">Набор блинов</p>
    <div class="pres">${Object.entries(PLATE_SETS).map(([k, v]) => `<button type="button" class="pre${cur && cur[0] === k ? ' on' : ''}" data-pset="${k}">${v.name}</button>`).join('')}</div>
    <label>Свои блины, кг через запятую<input id="gear-plates" type="text" inputmode="decimal" value="${GEAR.plates.map(fmtKg).join(', ')}"></label>
    <p class="gear-hint">Калькулятор раскладывает блины на одну сторону от самого тяжёлого к лёгкому. Укажите те, что есть в зале.</p>
    <div class="gear-btns"><button type="button" class="btn btn-2" value="cancel" id="gear-cancel">Отмена</button><button type="submit" class="btn" id="gear-save">Сохранить</button></div>
  </form>`;
}
function openGear() {
  let d = $('#gear-view');
  if (!d) { d = document.createElement('dialog'); d.id = 'gear-view'; d.className = 'gear-view'; document.body.appendChild(d); }
  d.innerHTML = gearDialogHtml(); d.showModal();
  d.querySelector('form').addEventListener('submit', () => {
    const bar = parseNum($('#gear-bar').value); if (bar > 0) GEAR.bar = bar;
    const pl = $('#gear-plates').value.split(/[,;\s]+/).map(parseNum).filter(v => v > 0).sort((a, b) => b - a);
    if (pl.length) GEAR.plates = [...new Set(pl)];
    gearSave(); document.querySelectorAll('.card').forEach(refreshWarmup);
  });
}
document.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t) return;
  if (t.dataset.gear) { openGear(); return; }
  if (t.dataset.pset) { $('#gear-plates').value = PLATE_SETS[t.dataset.pset].plates.map(fmtKg).join(', '); t.parentElement.querySelectorAll('.pre').forEach(b => b.classList.toggle('on', b === t)); return; }
  if (t.id === 'gear-cancel') { $('#gear-view').close(); return; }
});
document.addEventListener('input', e => {
  if (e.target.classList && e.target.classList.contains('lt-in') && e.target.dataset.f === 'kg') {
    const card = e.target.closest('.card'); if (card) { clearTimeout(card._wuT); card._wuT = setTimeout(() => refreshWarmup(card), 400); }
  }
});

/* ===================== ТЕЛО: ВЕС И ЗАМЕРЫ ===================== */
/* BODY.rows = [{d:'2026-10-06', kg:82.4, waist:88, …}] — одна запись на день, любые поля.
   Хранится в localStorage (podhod.body.v1) и, при входе в аккаунт, в документе «_body» той же коллекции, что журнал. */
const BODY_KEY = 'podhod.body.v1';
const BODY_FIELDS = [
  {k:'kg', name:'Вес', unit:'кг', main:true},
  {k:'waist', name:'Талия', unit:'см'}, {k:'chest', name:'Грудь', unit:'см'}, {k:'hips', name:'Таз', unit:'см'},
  {k:'arm', name:'Бицепс', unit:'см'}, {k:'thigh', name:'Бедро', unit:'см'}, {k:'calf', name:'Голень', unit:'см'}, {k:'neck', name:'Шея', unit:'см'}
];
const BODY = {rows:[], pending:false, writing:false, again:false};
function validBodyRows(rows) { return Array.isArray(rows) && rows.every(r => r && typeof r.d === 'string' && /^\d{4}-\d\d-\d\d$/.test(r.d)); }
function cleanBodyRow(r) { const o = {d:r.d}; for (const f of BODY_FIELDS) { const v = parseNum(r[f.k]); if (v != null && v > 0 && v < 1000) o[f.k] = Math.round(v * 10) / 10; } return o; }
function bodyHasValues(r) { return BODY_FIELDS.some(f => r[f.k] != null); }
function bodyLoad() { try { const s = JSON.parse(localStorage.getItem(BODY_KEY) || 'null'); if (s && validBodyRows(s.rows)) BODY.rows = s.rows.map(cleanBodyRow).filter(bodyHasValues); } catch (e) {} }
function bodySaveLocal() { try { localStorage.setItem(BODY_KEY, JSON.stringify({rows:BODY.rows})); } catch (e) {} }
/* объединение по дате: поля складываются, при совпадении приоритет у b */
function mergeBodyRows(a, b) {
  const by = new Map();
  for (const r of a || []) by.set(r.d, {...r});
  for (const r of b || []) by.set(r.d, {...(by.get(r.d) || {}), ...r});
  return [...by.values()].filter(bodyHasValues).sort((p, q) => p.d < q.d ? -1 : 1).slice(-400);
}
/* синхронизация с аккаунтом: вызывается из logInit при каждом снимке коллекции */
function bodyRemote(doc, first) {
  const remote = doc && validBodyRows(doc.rows) ? doc.rows.map(cleanBodyRow).filter(bodyHasValues) : [];
  if (first) {
    const merged = mergeBodyRows(remote, BODY.rows);
    if (JSON.stringify(merged) !== JSON.stringify(remote)) { BODY.rows = merged; bodyTouch(true); } else BODY.rows = remote;
  } else {
    if (BODY.pending || JSON.stringify(remote) === JSON.stringify(BODY.rows)) return;
    BODY.rows = remote;
  }
  bodySaveLocal();
  if (S.view === 'journal' && !$('#b-form input:focus')) renderJournal();
}
function bodyTouch(now) {
  bodySaveLocal();
  if (LOG.mode !== 'cloud' || !LOG.col) return;
  BODY.pending = true;
  clearTimeout(BODY.timer);
  BODY.timer = setTimeout(bodyFlush, now ? 0 : 800);
}
async function bodyFlush(retried) {
  if (BODY.writing) { BODY.again = true; return; }
  BODY.writing = true;
  try {
    if (BODY.rows.length) await LOG.col.doc('_body').set({ex:'_body', rows:BODY.rows});
    else await LOG.col.doc('_body').delete();
  } catch (e) {
    if (e && e.code === 'unavailable' && !retried) { BODY.writing = false; setTimeout(() => bodyFlush(true), 800); return; }
    LOG.err = 'Сохранить замеры в аккаунт не получилось — они остаются в этом браузере.'; logRefresh(null);
  } finally {
    BODY.writing = false;
    if (BODY.again) { BODY.again = false; bodyFlush(); } else BODY.pending = false;
  }
}
function bodyLatest(k) { for (let i = BODY.rows.length - 1; i >= 0; i--) if (BODY.rows[i][k] != null) return BODY.rows[i]; return null; }
/* изменение за период: сравниваем последнее значение с ближайшим не позже cutoff */
function bodyDelta(k, days) {
  const last = bodyLatest(k); if (!last) return null;
  const cutoff = dayKey(new Date(new Date(last.d + 'T12:00:00') - days * 86400000));
  const prev = [...BODY.rows].reverse().find(r => r[k] != null && r.d <= cutoff && r.d !== last.d);
  return prev ? {v:Math.round((last[k] - prev[k]) * 10) / 10, from:prev.d} : null;
}
const fmtDelta = v => (v > 0 ? '+' : v < 0 ? '−' : '±') + fmtKg(Math.abs(v));
/* окраска изменения веса зависит от цели: на массе рост — хорошо, на рельефе — наоборот; на силе нейтрально */
function deltaClass(v) { const g = S.goal === 'mass' ? 1 : S.goal === 'cut' ? -1 : 0; return !g || !v ? '' : v * g > 0 ? 'good' : 'bad'; }
function bodyHtml() {
  const last = bodyLatest('kg'), d4 = bodyDelta('kg', 28);
  const pts = BODY.rows.filter(r => r.kg != null).slice(-40).map(r => ({d:r.d, v:r.kg}));
  const chips = BODY_FIELDS.filter(f => !f.main).map(f => { const l = bodyLatest(f.k); if (!l) return ''; const dl = bodyDelta(f.k, 28); return `<li><span>${f.name}</span><b>${fmtKg(l[f.k])}<small>${f.unit}</small></b>${dl && dl.v ? `<em>${fmtDelta(dl.v)}</em>` : ''}</li>`; }).join('');
  const form = `<form class="b-form" id="b-form" autocomplete="off">
    <label class="b-date">Дата<input type="date" id="b-date" value="${todayKey()}" max="${todayKey()}" required></label>
    ${BODY_FIELDS.map(f => { const l = bodyLatest(f.k); return `<label${f.main ? ' class="b-main"' : ''}>${f.name}, ${f.unit}<input class="lt-in" type="text" inputmode="decimal" data-bf="${f.k}" placeholder="${l ? fmtKg(l[f.k]) : '—'}" aria-label="${f.name}, ${f.unit}"></label>`; }).join('')}
    <button type="submit" class="btn">Записать</button>
    <p class="b-hint">Заполняйте то, что измерили: вес — утром натощак, обхваты — сантиметровой лентой без натяжения, в одних и тех же точках. Остальное можно оставить пустым.</p>
  </form>`;
  const rows = [...BODY.rows].reverse();
  const rowHtml = r => `<li><span class="h-d">${fmtDay(r.d, true)}</span><span class="h-s">${BODY_FIELDS.filter(f => r[f.k] != null).map(f => `${f.main ? '' : f.name.toLowerCase() + ' '}${fmtKg(r[f.k])}${f.main ? ' кг' : ''}`).join(' · ')}</span><button type="button" class="h-del" data-bdel="${r.d}" aria-label="Удалить замер за ${fmtDay(r.d, true)}">Удалить</button></li>`;
  const list = rows.length ? `<ul class="h-list b-list">${rows.slice(0, 6).map(rowHtml).join('')}</ul>${rows.length > 6 ? `<details class="j-all"><summary>Все замеры (${rows.length})</summary><ul class="h-list b-list">${rows.slice(6).map(rowHtml).join('')}</ul></details>` : ''}` : '';
  return `<section class="b-sec" aria-labelledby="b-title">
    <div class="b-head">
      <div>
        <p class="eyebrow">Тело</p>
        <h2 id="b-title">Вес и замеры</h2>
        ${last ? `<p class="b-now"><b>${fmtKg(last.kg)}<small>кг</small></b>${d4 && d4.v ? `<em class="${deltaClass(d4.v)}">${fmtDelta(d4.v)} за 4 нед.</em>` : `<em>${fmtDay(last.d, true)}</em>`}</p>` : `<p class="b-empty">Записей о весе пока нет. Взвешивайтесь раз в неделю в одно и то же время — по графику будет видно, куда идёт масса, а не дневные колебания воды.</p>`}
        ${chips ? `<ul class="b-chips">${chips}</ul>` : ''}
      </div>
      ${pts.length > 1 ? `<div class="h-chart b-chart"><p class="h-cap">Вес, кг · ${pts.length} ${plural(pts.length, 'запись', 'записи', 'записей')}</p>${sparkSvg(pts, 'кг', 0.1)}</div>` : ''}
    </div>
    ${form}
    ${list}
  </section>`;
}
function bodySubmit(form) {
  const d = $('#b-date').value;
  if (!/^\d{4}-\d\d-\d\d$/.test(d) || d > todayKey()) { $('#b-date').focus(); return; }
  const row = {d};
  let any = false;
  form.querySelectorAll('[data-bf]').forEach(inp => { const v = parseNum(inp.value); if (v != null && v > 0) { row[inp.dataset.bf] = v; any = true; } });
  if (!any) { const f = form.querySelector('[data-bf="kg"]'); f.classList.add('need'); f.focus(); setTimeout(() => f.classList.remove('need'), 1200); return; }
  BODY.rows = mergeBodyRows(BODY.rows, [cleanBodyRow(row)]);
  bodyTouch(false);
  renderJournal();
  const m = $('#j-msg'); if (m) m.textContent = `Замер за ${fmtDay(d, true)} записан.`;
}
function bodyDelete(btn) {
  if (!btn.classList.contains('armed')) { btn.classList.add('armed'); btn.textContent = 'Точно удалить?'; setTimeout(() => { btn.classList.remove('armed'); btn.textContent = 'Удалить'; }, 3000); return; }
  BODY.rows = BODY.rows.filter(r => r.d !== btn.dataset.bdel);
  bodyTouch(false); renderJournal();
}
function bodyCsv() {
  const head = ['Дата'].concat(BODY_FIELDS.map(f => `${f.name}, ${f.unit}`));
  const rows = BODY.rows.map(r => [r.d].concat(BODY_FIELDS.map(f => r[f.k] != null ? fmtKg(r[f.k]) : '')));
  return '﻿' + [head].concat(rows).map(r => r.join(';')).join('\r\n');
}
document.addEventListener('submit', e => { if (e.target.id === 'b-form') { e.preventDefault(); bodySubmit(e.target); } });
document.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t) return;
  if (t.dataset.bdel) { bodyDelete(t); return; }
  if (t.id === 'exp-body') { saveFile(`lazy-gym-body-${todayKey()}.csv`, bodyCsv(), 'text/csv').then(r => { const m = $('#j-msg'); if (m) m.textContent = r === 'ok' ? 'Таблица замеров сохранена.' : r === 'declined' ? 'Сохранение отменено.' : 'Сохранить файл не удалось.'; }); }
});
bodyLoad();

/* ===================== ПОЛНАЯ РЕЗЕРВНАЯ КОПИЯ ===================== */
/* v2: настройки планировщика, инвентарь, авторегулировка, календарь, атлас, журнал и замеры. v1 (только журнал) тоже читается.
   Подход в журнале — [кг, повторы], [кг, повторы, отдых, с] или [кг, повторы, отдых | null, {l, r}] (Л/П, 13a-sets.js):
   отдых и стороны необязательны, неверные отбрасываются, подход остаётся. Снаряд записи (eq) — только допустимый
   для упражнения. */
function backupObject() {
  return {app:'podhod', v:2, exported:new Date().toISOString(), version:window.PODHOD_VERSION || '',
    settings:{...S}, gear:{bar:GEAR.bar, plates:GEAR.plates}, autoreg:{dismissed:AR.dismissed, light:AR.light}, ics:{...ICS}, motion:{...motionPrefs},
    log:LOG.data, body:BODY.rows};
}
function restoreBackup(obj) {
  const out = {sessions:0, exercises:0, body:0, settings:false};
  if (obj.log && typeof obj.log === 'object') {
    for (const [id, ss] of Object.entries(obj.log)) {
      if (!EXI[id] || !validSessions(ss)) continue;
      const ex = EXI[id];
      const clean = ss.map(x => ({d:x.d, ...(x.wk ? {wk:+x.wk} : {}), ...(x.fmt === 'static' ? {fmt:'static'} : {}),
        ...(Number.isSafeInteger(+x.target) && +x.target > 0 ? {target:+x.target} : {}),
        ...(cleanImpl(ex, x.eq) ? {eq:x.eq} : {}),
        s:x.s.map(v => cleanSet(v, ex))}));
      const merged = mergeSessions(LOG.data[id], clean);
      if (JSON.stringify(merged) !== JSON.stringify(LOG.data[id] || [])) { LOG.data[id] = merged; logTouch(id, true); out.exercises++; out.sessions += clean.length; }
    }
    logSaveLocal();
  }
  if (validBodyRows(obj.body)) {
    const merged = mergeBodyRows(BODY.rows, obj.body.map(cleanBodyRow).filter(bodyHasValues));
    if (JSON.stringify(merged) !== JSON.stringify(BODY.rows)) { out.body = merged.length - BODY.rows.length; BODY.rows = merged; bodyTouch(true); }
  }
  if (obj.v >= 2) {
    if (obj.settings && typeof obj.settings === 'object') {
      const s = obj.settings, ok = {};
      for (const k of Object.keys(DEFAULTS)) if (k in s && k !== 'view') ok[k] = s[k];
      if (Array.isArray(ok.groups)) ok.groups = ok.groups.filter(g => GROUPS.some(x => x.id === g));
      if (Array.isArray(ok.equip)) ok.equip = ok.equip.filter(id => EQUIP.some(x => x.id === id));
      if (!GOALS[ok.goal]) delete ok.goal; if (!FORMATS[ok.format]) delete ok.format; if (!LEVELS[ok.level]) delete ok.level;
      if ('lr' in ok) ok.lr = cleanLr(ok.lr);
      Object.assign(S, ok); saveSettings(); out.settings = true;
    }
    if (obj.gear && typeof obj.gear === 'object') { if (isFinite(obj.gear.bar) && obj.gear.bar > 0) GEAR.bar = +obj.gear.bar; if (Array.isArray(obj.gear.plates)) { const pl = obj.gear.plates.map(Number).filter(v => v > 0); if (pl.length) GEAR.plates = [...new Set(pl)].sort((a, b) => b - a); } gearSave(); }
    if (obj.autoreg && typeof obj.autoreg === 'object') { if (obj.autoreg.dismissed && typeof obj.autoreg.dismissed === 'object') AR.dismissed = obj.autoreg.dismissed; AR.light = !!obj.autoreg.light; arSave(); }
    if (obj.ics && typeof obj.ics === 'object') { Object.assign(ICS, obj.ics); try { localStorage.setItem(ICS_KEY, JSON.stringify(ICS)); } catch (e) {} }
    if (obj.motion && typeof obj.motion === 'object') { Object.assign(motionPrefs, obj.motion); saveMotionPrefs(); }
    S.view = 'journal';
    renderSetup();
  }
  return out;
}

/* ---------- запуск ---------- */
logLoadLocal();
setupMotionViewer();
setupGallery();
setupWorkout();
setupMotionCameras();
renderSetup();
renderPlan();
prefetchStressIds();
logInit();

